"""Una vez que la API de Earth Engine está autenticada e inicializada, puedes empezar a buscar y listar colecciones de imágenes. Por ejemplo, aquí te muestro cómo listar las imágenes de la colección LANDSAT 8 Surface Reflectance:

Para filtrar una colección de imágenes por una región de interés (ROI), primero necesitas definir tu ROI como un objeto `ee.Geometry`. Luego, puedes usar el método `.filterBounds()` en tu colección de imágenes.

### Entendiendo los Tipos de Activos en Earth Engine: `ee.Image` vs `ee.ImageCollection` y `ee.Feature` vs `ee.FeatureCollection`

En Earth Engine, es crucial diferenciar entre `Image` (una sola imagen ráster) y `ImageCollection` (un conjunto de imágenes ráster). Lo mismo aplica para `Feature` (un objeto vectorial único) y `FeatureCollection` (un conjunto de objetos vectoriales).

Los errores anteriores indicaban que estabas intentando cargar un `ee.Image` (`WWF/HydroSHEDS/03VFDEM`) como `ee.ImageCollection`, y un `ee.FeatureCollection` no encontrado (`WWF/HydroSHEDS/v1/Basins/riv_bas`).

Ahora vamos a cargar correctamente estos activos.
"""

# Reutilizamos la región de interés para Colombia.
min_lon = -81.7
min_lat = -4.2
max_lon = -66.8
max_lat = 13.5

roi_colombia = ee.Geometry.Rectangle([min_lon, min_lat, max_lon, max_lat])

# 1. Cargar el DEM de HydroSHEDS como ee.Image (correctamente)
# 'WWF/HydroSHEDS/03VFDEM' es un Digital Elevation Model (DEM) ráster.
hydrosheds_dem_image = ee.Image('WWF/HydroSHEDS/03VFDEM')

print('DEM de HydroSHEDS (ee.Image):')
print(hydrosheds_dem_image.getInfo())

# Puedes recortar el DEM a la región de interés si lo necesitas
hydrosheds_dem_colombia = hydrosheds_dem_image.clip(roi_colombia)
print('\nDEM de HydroSHEDS recortado para Colombia:')
print(hydrosheds_dem_colombia)

"""### Cálculo de la Pendiente (Slope) a partir del DEM de Earth Engine

Vamos a calcular la pendiente del DEM de HydroSHEDS para nuestra región de interés en Colombia. La función `ee.Terrain.slope()` en Earth Engine calcula la pendiente en grados (por defecto) o en radianes a partir de una imagen de elevación.
"""

# Calcular la pendiente a partir del DEM de HydroSHEDS para Colombia
# La función ee.Terrain.slope() devuelve la pendiente en grados por defecto.
slope_image = ee.Terrain.slope(hydrosheds_dem_colombia)

print('Imagen de Pendiente (Slope) calculada:')
print(slope_image)

# Visualizar la imagen de pendiente
# Definir parámetros de visualización para la pendiente (en grados)
slope_vis = {
  'min': 0,
  'max': 60,
  'palette': ['000000', '303030', '505050', '808080', 'B0B0B0', 'E0E0E0', 'FFFFFF'] # Escala de grises, del negro (plano) al blanco (empinado)
}

# Para visualizar en Colab, necesitamos el módulo ipygee o folium.
# Si no tienes ipygee instalado, el siguiente código lo instalará y configurará un mapa interactivo.
try:
    import ee_extra.ee_view as ee_view
    Map = ee_view.get_map()
    Map.addLayer(slope_image, slope_vis, 'Pendiente (Slope)')
    Map.centerObject(roi_colombia, 7)
    display(Map)
except ImportError:
    print("ipygee o ee_extra no están instalados. Para visualizar el mapa interactivo, ejecuta: !pip install ipygee ee_extra")
    print("Luego, reinicia el entorno de ejecución y vuelve a ejecutar las celdas.")
    print("Puedes inspeccionar el objeto 'slope_image' con .getInfo() si la visualización interactiva no es posible.")

"""### Estadísticas de la Pendiente (Slope)

Vamos a calcular las estadísticas básicas (mínimo, máximo, media, desviación estándar) de la pendiente dentro de la región de interés de Colombia. Esto nos dará una cuantificación de la rugosidad del terreno.
"""

# Calcular estadísticas de la pendiente para la región de Colombia
# La escala (scale) define la resolución a la que se realiza el cálculo.
# Aumentaremos la escala para reducir la cantidad de píxeles procesados.

# Definir los reducers individualmente.
reducer_min = ee.Reducer.min()
reducer_max = ee.Reducer.max()
reducer_mean = ee.Reducer.mean().unweighted()
reducer_stdDev = ee.Reducer.stdDev().unweighted()

# Combinar los reducers secuencialmente, asegurando que compartan la misma entrada
# y especificando explícitamente 'sharedInputs'.
combined_reducer = reducer_min.combine(reducer_max, sharedInputs=True)
combined_reducer = combined_reducer.combine(reducer_mean, sharedInputs=True)
combined_reducer = combined_reducer.combine(reducer_stdDev, sharedInputs=True)

# Asignar nombres a las salidas del reducer combinado.
combined_reducer = combined_reducer.setOutputs(['min', 'max', 'mean', 'stdDev'])

slope_stats = slope_image.reduceRegion(**{
    'reducer': combined_reducer,
    'geometry': roi_colombia,
    'scale': 100, # Aumentado a 100 metros para reducir el número de píxeles
    'maxPixels': 1e13, # Mantenemos un valor alto para maxPixels
    'bestEffort': True # Permite que Earth Engine ajuste la escala si es necesario
})

print('Estadísticas de la Pendiente para Colombia (en grados):')
print(slope_stats.getInfo())

