import geopandas as gpd
import zipfile
import os

watershed_gdf = None

zip_file_path = '/content/watershed.zip'
unzip_dir = '/content/watershed_extracted'
shp_file_path = os.path.join(unzip_dir, 'watershed.shp')

# Crear el directorio si no existe
os.makedirs(unzip_dir, exist_ok=True)

# Descomprimir el archivo y luego intentar cargar el Shapefile
try:
    with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:
        zip_ref.extractall(unzip_dir)
    print(f"Archivo '{zip_file_path}' descomprimido en '{unzip_dir}'.")

    # Ahora intentar cargar el shapefile, ya que la descompresión fue exitosa
    if not os.path.exists(shp_file_path):
        print(f"Error: El archivo Shapefile esperado '{shp_file_path}' no se encontró después de la descompresión.")
        watershed_gdf = None # Asegurar que sea None si el SHP no se encuentra
    else:
        try:
            watershed_gdf = gpd.read_file(shp_file_path)
            print('Shapefile cargado exitosamente en un GeoDataFrame:')
            print(watershed_gdf.head())
            print(f'Sistema de Coordenadas (CRS): {watershed_gdf.crs}')
            print(f'Número de geometrías: {len(watershed_gdf)}')
        except Exception as e:
            print(f'Error al cargar el Shapefile: {e}')
            watershed_gdf = None # Asegurar que sea None si hay un error al leer

except FileNotFoundError:
    print(f"Error: El archivo ZIP '{zip_file_path}' no se encontró. Asegúrate de que el archivo esté presente en la ruta especificada.")
    watershed_gdf = None # Asegurar que sea None si el ZIP no se encuentra
except Exception as e:
    print(f"Ocurrió un error inesperado al descomprimir el archivo: {e}")
    watershed_gdf = None # Asegurar que sea None si hay un error inesperado

import geopandas as gpd

# Asegurarse de que `watershed_gdf` esté disponible
if 'watershed_gdf' not in locals() or watershed_gdf is None:
    print('Error: El GeoDataFrame de la cuenca (`watershed_gdf`) no está disponible. Asegúrate de haber cargado el Shapefile de la cuenca previamente.')
else:
    # Reproyectar a un CRS proyectado adecuado para Colombia (e.g., EPSG:3116 para MAGNA-SIRGAS / Colombia Bogota Zone)
    # Este CRS es métrico y adecuado para cálculos de área y distancia en Colombia.
    watershed_gdf_projected = watershed_gdf.to_crs(epsg=3116)

    # Calcular el área de la cuenca utilizando el GeoDataFrame proyectado
    # El área estará en las unidades del CRS proyectado (metros cuadrados en este caso)
    watershed_area_sq_m = watershed_gdf_projected.geometry.area.iloc[0]

    print(f"Área de la cuenca: {watershed_area_sq_m:.2f} metros cuadrados")
    print(f"Área de la cuenca: {watershed_area_sq_m / 1_000_000:.2f} kilómetros cuadrados")

