"""### Preparación de las Zonas de Vida de Holdridge para Earth Engine

Convertiremos el `GeoDataFrame` `holdridge_gdf` en un objeto `ee.FeatureCollection`, lo cual es necesario para realizar operaciones espaciales dentro de Earth Engine, como recortar a la cuenca de interés.
"""

import ee

if 'holdridge_gdf' in locals() and holdridge_gdf is not None:
    # Asegurarse de que el GeoDataFrame esté en un CRS compatible con Earth Engine (EPSG:4326)
    # El CRS actual es EPSG:3116, así que lo reproyectamos.
    holdridge_gdf_wgs84 = holdridge_gdf.to_crs(epsg=4326)

    # Convertir el GeoDataFrame a una ee.FeatureCollection
    # Earth Engine requiere que los GeoJSON sean `Feature` o `FeatureCollection`.
    # `__geo_interface__` convierte un GeoDataFrame a un diccionario GeoJSON compatible.
    ee_holdridge_zones = ee.FeatureCollection(holdridge_gdf_wgs84.__geo_interface__['features'])

    print('Zonas de vida de Holdridge convertidas a ee.FeatureCollection:')
    print(ee_holdridge_zones.limit(5).getInfo()) # Mostrar los primeros 5 elementos
else:
    print('Error: El GeoDataFrame `holdridge_gdf` no está disponible. Asegúrate de haber cargado el Shapefile de Holdridge previamente.')

"""### Recortar las Zonas de Vida de Holdridge a la Cuenca 'Quebrada la Honda'

Ahora, recortaremos la colección global de zonas de vida de Holdridge a la extensión geográfica de nuestra cuenca de interés (`roi_quebrada_honda`). Esto nos permitirá analizar solo las zonas de vida presentes dentro de la microcuenca.
"""

if 'ee_holdridge_zones' in locals() and ee_holdridge_zones is not None and \
   'roi_quebrada_honda' in locals() and roi_quebrada_honda is not None:

    # Recortar las zonas de vida a la geometría de la cuenca
    holdridge_zones_quebrada_honda = ee_holdridge_zones.filterBounds(roi_quebrada_honda)

    print('Zonas de vida de Holdridge recortadas a la cuenca Quebrada la Honda:')
    print(holdridge_zones_quebrada_honda.getInfo())

    # Convertir a una imagen para visualización (si es necesario un ráster) o dejar como FeatureCollection para superposición vectorial
    # Para la visualización, a menudo es útil convertir la FeatureCollection a una imagen si queremos colorear las zonas
    # o mantenerla como vector para un overlay con folium. Aquí la usaremos directamente como vector.

else:
    print('Error: `ee_holdridge_zones` o `roi_quebrada_honda` no están definidos.')

"""### Visualización de las Zonas de Vida de Holdridge sobre el DEM de la Cuenca

Finalmente, crearemos un mapa interactivo para visualizar el Modelo de Elevación Digital (DEM) de la cuenca 'Quebrada la Honda' y superponer las zonas de vida de Holdridge presentes en ella. Esto nos dará una perspectiva espacial de cómo se distribuyen estas zonas en relación con la topografía.
"""

import folium
import ee

# Asegurarse de que `dem_quebrada_honda`, `holdridge_zones_quebrada_honda`, `roi_quebrada_honda` y `watershed_gdf` estén definidos
if 'dem_quebrada_honda' not in locals() or dem_quebrada_honda is None:
    print('Error: La imagen DEM recortada para Quebrada la Honda (`dem_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'holdridge_zones_quebrada_honda' not in locals() or holdridge_zones_quebrada_honda is None:
    print('Error: Las zonas de vida de Holdridge recortadas (`holdridge_zones_quebrada_honda`) no están definidas. Por favor, ejecuta las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'watershed_gdf' not in locals() or watershed_gdf is None:
    print('Error: El GeoDataFrame de la cuenca (`watershed_gdf`) no está disponible. Por favor, ejecuta las celdas anteriores.')
else:
    # Parámetros de visualización para el DEM (reutilizamos los definidos anteriormente)
    dem_vis = {
        'min': 0,        # Altitud mínima
        'max': 3000,     # Altitud máxima (ajustar según el rango real de tu DEM)
        'palette': ['#000000', '#555555', '#AAAAAA', '#FFFFFF'] # Escala de grises para el DEM
    }

    # Paleta de colores para las zonas de vida de Holdridge.
    # Las zonas de vida tienen un campo 'ZV_Holdrid' o 'grid_code'. Necesitamos mapear colores a estos valores.
    # Por simplicidad, podemos asignar colores aleatorios o una paleta discreta si no hay un mapeo estándar específico.
    # En el ejemplo de head(), hay 'bs-T', 'bh-A', 'bs-BA', 'grid_code' (11, 6, 5).
    # Definiremos un mapeo de colores para 'grid_code' si está disponible, o simplemente usaremos una paleta.
    # Para una visualización básica, podemos usar un color diferente para cada Feature.

    # Obtener el centroide de la cuenca para centrar el mapa (reutilizamos centroid_quebrada_honda)
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    # Crear un mapa Folium base
    m_holdridge_dem = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # Añadir la capa del DEM como base
    map_id_dem = ee.Image(dem_quebrada_honda).getMapId(dem_vis)
    folium.TileLayer(
        tiles=map_id_dem['tile_fetcher'].url_format,
        attr='Google Earth Engine - DEM',
        overlay=True,
        name='DEM de Altitud'
    ).add_to(m_holdridge_dem)

    # Añadir las zonas de vida de Holdridge como una capa vectorial (GeoJSON)
    # Para colorear por un atributo, necesitamos un estilo dinámico.
    # Podemos usar un mapeo de colores basado en 'grid_code' o 'ZV_Holdrid'.
    holdridge_info = holdridge_zones_quebrada_honda.getInfo()
    if holdridge_info and holdridge_info['features']:
        # Crear un mapa de colores para las Zonas de Vida basado en 'grid_code'
        unique_codes = sorted(list(set([f['properties'].get('grid_code') for f in holdridge_info['features'] if f['properties'].get('grid_code') is not None])))
        num_unique_codes = len(unique_codes)

        # Generar una paleta de colores diversa
        import matplotlib.cm as cm
        import matplotlib.colors as mcolors
        import matplotlib.pyplot as plt # Importar pyplot para colormaps

        if num_unique_codes > 0:
            # Usar una paleta de colores para clasificaciones discretas
            cmap = plt.colormaps.get_cmap('tab20').resampled(num_unique_codes) # 'tab20' es bueno para hasta 20 clases
            colors_holdridge = [mcolors.to_hex(cmap(i)) for i in range(num_unique_codes)]
            color_map_holdridge = {code: colors_holdridge[i] for i, code in enumerate(unique_codes)}
        else:
            color_map_holdridge = {}

        folium.GeoJson(
            holdridge_info,
            name='Zonas de Vida de Holdridge',
            style_function=lambda x: {
                'fillColor': color_map_holdridge.get(x['properties'].get('grid_code'), '#808080'), # Gris por defecto si no se encuentra
                'color': 'black',
                'weight': 1,
                'fillOpacity': 0.7
            },
            tooltip=folium.GeoJsonTooltip(fields=['ZV_Holdrid', 'grid_code'], aliases=['Zona de Vida:', 'Código:'])
        ).add_to(m_holdridge_dem)

    # Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'red', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_holdridge_dem)

    # Añadir control de capas
    m_holdridge_dem.add_child(folium.LayerControl())

    display(m_holdridge_dem)
