import ee
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

# Asegurarse de que `holdridge_zones_quebrada_honda` y `roi_quebrada_honda` estén definidos
if 'holdridge_zones_quebrada_honda' not in locals() or holdridge_zones_quebrada_honda is None:
    print('Error: Las zonas de vida de Holdridge recortadas (`holdridge_zones_quebrada_honda`) no están definidas. Por favor, ejecuta las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
else:
    # 1. Calcular el área de cada zona de vida de Holdridge dentro de la cuenca
    # Usamos .map() para aplicar una función a cada Feature en la FeatureCollection.
    # La función calcula el área de la geometría en metros cuadrados.
    def calculate_area(feature):
        return feature.set({'area_sq_m': feature.geometry().area()})

    holdridge_zones_with_area = holdridge_zones_quebrada_honda.map(calculate_area)

    # 2. Convertir la FeatureCollection a una lista de diccionarios Python para Pandas
    holdridge_list = holdridge_zones_with_area.getInfo()['features']

    data = []
    for f in holdridge_list:
        properties = f['properties']
        # Asegurarse de que 'ZV_Holdrid' existe
        if 'ZV_Holdrid' in properties:
            data.append({
                'ZV_Holdrid': properties['ZV_Holdrid'],
                'area_sq_m': properties['area_sq_m']
            })

    holdridge_area_df = pd.DataFrame(data)

    # 3. Agrupar por zona de vida y sumar las áreas
    holdridge_area_summary = holdridge_area_df.groupby('ZV_Holdrid')['area_sq_m'].sum().reset_index()

    # Convertir a hectáreas
    holdridge_area_summary['area_ha'] = holdridge_area_summary['area_sq_m'] / 10000

    # 4. Calcular el área total de la cuenca (para porcentajes)
    # Se usa el valor de 'watershed_area_sq_m' calculado previamente en un CRS proyectado
    if 'watershed_area_sq_m' not in locals():
        print('Error: La variable `watershed_area_sq_m` no está definida. Por favor, asegúrate de que la celda `330ce82f` que calcula el área proyectada de la cuenca haya sido ejecutada.')
    else:
        watershed_total_area_sq_m = watershed_area_sq_m
        watershed_total_area_ha = watershed_total_area_sq_m / 10000

        # 5. Calcular el porcentaje del área total de la cuenca
        holdridge_area_summary['percentage'] = (holdridge_area_summary['area_ha'] / watershed_total_area_ha * 100).round(2)

        print('Distribución de Área por Zonas de Vida de Holdridge en Quebrada la Honda:')
        display(holdridge_area_summary.round(2))

        # 6. Visualizar la distribución
        plt.figure(figsize=(12, 7))
        sns.barplot(x='ZV_Holdrid', y='area_ha', data=holdridge_area_summary, palette='viridis', hue='ZV_Holdrid', legend=False)
        plt.title('Área por Zona de Vida de Holdridge en la Cuenca Quebrada la Honda')
        plt.xlabel('Zona de Vida de Holdridge')
        plt.ylabel('Área (hectáreas)')
        plt.xticks(rotation=45, ha='right')
        plt.grid(axis='y', linestyle='--', alpha=0.7)
        plt.tight_layout()
        plt.show()

        print('Visualización de la distribución de áreas por zona de vida completada.')

