"""Ahora que las zonas de vida de Holdridge están cargadas en `holdridge_gdf`, podremos usarlas. **Una vez que Earth Engine esté inicializado correctamente**, procederemos a superponerlas en el DEM de la cuenca 'Quebrada la Honda'."""

import matplotlib.pyplot as plt
import numpy as np
from matplotlib import colors as mcolors
import rasterio

# Asegúrate de que 'reclassified_dem' y 'watershed_gdf' estén disponibles
if 'reclassified_dem' not in locals() or reclassified_dem is None or reclassified_dem.size == 0:
    print("Error: La variable 'reclassified_dem' no está disponible o está vacía. Asegúrate de haber ejecutado la celda de reclasificación previamente.")
elif 'watershed_gdf' not in locals() or watershed_gdf is None:
    print("Error: La variable 'watershed_gdf' no está disponible. Asegúrate de haber cargado el GeoDataFrame previamente.")
else:
    # Definir los rangos de altitud y los valores de reclasificación (para las etiquetas)
    reclassification_bins = [
        (0, 500, 1),      # 0-499 metros -> Clase 1
        (500, 1000, 2),   # 500-999 metros -> Clase 2
        (1000, 1500, 3),  # 1000-1499 metros -> Clase 3
        (1500, 2000, 4),  # 1500-1999 metros -> Clase 4
        (2000, np.inf, 5) # 2000 metros en adelante -> Clase 5
    ]

    # Crear un colormap y normalización para las clases discretas
    cmap = plt.colormaps.get_cmap('terrain').resampled(len(reclassification_bins))

    bounds = np.array([rb[2] for rb in reclassification_bins]) # Obtener los valores de las clases
    min_val = np.min(bounds) # Valor mínimo de clase
    max_val = np.max(bounds) # Valor máximo de clase
    norm_bounds = np.arange(min_val - 0.5, max_val + 1.5, 1) # e.g., [-0.5, 0.5, 1.5, ..., 5.5]
    norm = mcolors.BoundaryNorm(norm_bounds, cmap.N)

    # Crear la figura y los ejes
    fig, ax = plt.subplots(1, 1, figsize=(12, 10))

    # Obtener el `transform` y `crs` del raster original o reclasificado para `imshow`
    # Usaremos `out_meta` que contiene esta información del raster recortado.
    if 'out_meta' in locals() and out_meta is not None:
        extent = rasterio.transform.array_bounds(out_meta['height'], out_meta['width'], out_meta['transform'])
        # extent: [left, bottom, right, top]
    else:
        # Fallback if out_meta is not available, try to open the saved reclassified tif
        reclassified_tif_path = '/content/reclassified_dem_watershed.tif'
        try:
            with rasterio.open(reclassified_tif_path) as src_reclassified:
                extent = rasterio.transform.array_bounds(src_reclassified.height, src_reclassified.width, src_reclassified.transform)
        except Exception as e:
            print(f"Could not get raster extent: {e}. Plotting without explicit extent.")
            extent = None

    # Visualizar el raster reclasificado
    if extent:
        img = ax.imshow(reclassified_dem, cmap=cmap, norm=norm, extent=[extent[0], extent[2], extent[1], extent[3]])
    else:
        img = ax.imshow(reclassified_dem, cmap=cmap, norm=norm)

    ax.set_title('Distribución Espacial de Clases de Altitud en la Cuenca')
    ax.set_xlabel('Longitud')
    ax.set_ylabel('Latitud')

    # Superponer el límite de la cuenca (watershed_gdf)
    # Asegúrate de que el CRS de watershed_gdf coincida con el CRS del raster para la visualización
    # Asumimos que el raster está en EPSG:4326 (lat/lon) y watershed_gdf también lo está
    # Si no, watershed_gdf.to_crs(raster_crs) sería necesario
    watershed_gdf.boundary.plot(ax=ax, color='black', linewidth=1)

    # Configurar la barra de color
    cbar = fig.colorbar(img, ax=ax, ticks=bounds, format='%d', shrink=0.7)
    cbar_labels = []
    for lower, upper, class_val in reclassification_bins:
        if upper == np.inf:
            cbar_labels.append(f'Clase {class_val}: >= {lower} m')
        else:
            cbar_labels.append(f'Clase {class_val}: {lower}-{upper-1} m')
    cbar.set_ticklabels(cbar_labels)
    cbar.set_label('Clase de Altitud e Interpretación')

    plt.show()

    print("Visualización espacial de clases de altitud completada.")

