"""### Calcular Estadísticas Descriptivas de la Temperatura Exportada

Una vez que el archivo `ERA5_Land_Temp_Quebrada_La_Honda_20200701.tif` haya sido descargado de Google Drive y subido a tu sesión de Colab, puedes usar el siguiente código para leerlo y calcular sus estadísticas descriptivas.
"""

import rasterio
import numpy as np
import os

# Asegúrate de que el archivo TIFF exportado esté disponible en esta ruta
# Por ejemplo, si lo subiste manualmente a /content/
# El archivo esperado era 'ERA5_Land_Temp_Quebrada_La_Honda_20200701.tif',
# pero al no encontrarse, usaremos el archivo '/content/QUEBRADA LA HONDA.tif' que has puesto a disposición.
exported_tif_path = '/content/QUEBRADA LA HONDA.tif'

if os.path.exists(exported_tif_path):
    try:
        with rasterio.open(exported_tif_path) as src:
            temperature_data = src.read(1) # Leer la primera banda (temperatura)

            # Filtrar los valores 'no data' si los hay (pueden ser -9999 o un valor similar)
            # Por simplicidad, asumimos que los ceros o valores muy bajos son 'no data' si no se especificó un nodata en la exportación.
            # O puedes usar src.nodata si está definido en el GeoTIFF.
            if src.nodata is not None:
                valid_data = temperature_data[temperature_data != src.nodata]
            else:
                # Si no hay nodata definido, intentamos filtrar valores muy bajos/cero que suelen ser inválidos
                # Dado que este es un DEM (altitud) y no temperatura, el rango de valores será diferente.
                # Asumimos valores > 0 son válidos para altitud.
                valid_data = temperature_data[temperature_data > 0] # Asumimos altitudes > 0m son válidas

            if valid_data.size > 0:
                min_val = np.min(valid_data)
                max_val = np.max(valid_data)
                mean_val = np.mean(valid_data)
                std_val = np.std(valid_data)

                print(f"Estadísticas Descriptivas para '{os.path.basename(exported_tif_path)}':")
                print(f"  Valor Mínimo: {min_val:.2f}")
                print(f"  Valor Máximo: {max_val:.2f}")
                print(f"  Valor Medio: {mean_val:.2f}")
                print(f"  Desviación Estándar: {std_val:.2f}")
            else:
                print("No se encontraron datos válidos en el archivo TIFF para calcular estadísticas.")

    except rasterio.errors.RasterioIOError as e:
        print(f"Error al abrir o leer el archivo GeoTIFF '{exported_tif_path}': {e}")
    except Exception as e:
        print(f"Ocurrió un error inesperado: {e}")
else:
    print(f"Error: El archivo '{exported_tif_path}' no se encontró. Por favor, asegúrate de que el nombre del archivo sea correcto y esté en la ubicación esperada.")

import rasterio
import numpy as np
import os

# Ruta al archivo GeoTIFF de temperatura ERA5-Land exportado.
# Se espera que el archivo tenga este nombre, según la tarea de exportación previa.
exported_temperature_tif_path = '/content/ERA5_Land_Temp_Quebrada_La_Honda_20200701.tif'

if os.path.exists(exported_temperature_tif_path):
    try:
        with rasterio.open(exported_temperature_tif_path) as src:
            temperature_data = src.read(1) # Leer la primera banda (temperatura)

            # Filtrar los valores 'no data' si los hay. Si src.nodata no está definido, se asumirá que es 0.
            if src.nodata is not None:
                valid_temperature_data = temperature_data[temperature_data != src.nodata]
            else:
                # Si no hay nodata definido, y asumimos que la temperatura no es 0 Kelvin (absoluto),
                # podemos filtrar valores atípicos o no válidos para la temperatura en Celsius.
                # Por ejemplo, temperaturas muy bajas o muy altas que no son realistas.
                # Aquí asumimos que los valores válidos de temperatura en Celsius están por encima de un umbral razonable.
                valid_temperature_data = temperature_data[temperature_data > -50] # Ejemplo: filtrar valores muy por debajo de -50 C

            if valid_temperature_data.size > 0:
                min_temp = np.min(valid_temperature_data)
                max_temp = np.max(valid_temperature_data)
                mean_temp = np.mean(valid_temperature_data)
                std_temp = np.std(valid_temperature_data)

                print(f"Estadísticas Descriptivas para la Imagen de Temperatura ERA5-Land ('{os.path.basename(exported_temperature_tif_path)}'):")
                print(f"  Temperatura Mínima: {min_temp:.2f} °C")
                print(f"  Temperatura Máxima: {max_temp:.2f} °C")
                print(f"  Temperatura Media: {mean_temp:.2f} °C")
                print(f"  Desviación Estándar de Temperatura: {std_temp:.2f} °C")
            else:
                print("No se encontraron datos de temperatura válidos en el archivo TIFF para calcular estadísticas.")

    except rasterio.errors.RasterioIOError as e:
        print(f"Error al abrir o leer el archivo GeoTIFF de temperatura '{exported_temperature_tif_path}': {e}")
    except Exception as e:
        print(f"Ocurrió un error inesperado al procesar el archivo de temperatura: {e}")
else:
    print(f"Error: El archivo de temperatura esperado '{exported_temperature_tif_path}' no se encontró.")
    print("Por favor, asegúrate de que el archivo se haya exportado correctamente a Google Drive y luego se haya subido a la sesión de Colab en la ruta esperada.")
    print("Si el archivo se renombró o se encuentra en otra ubicación, actualiza la variable `exported_temperature_tif_path`.")

