import rasterio
from rasterio.mask import mask
import matplotlib.pyplot as plt
import fiona
import json

# Ruta al archivo TIFF y al shapefile
tif_file_path = '/content/QUEBRADA LA HONDA.tif'
shp_file_path = '/content/watershed_extracted/watershed.shp' # Reutilizamos la ruta del shapefile

# Abrir el raster
with rasterio.open(tif_file_path) as src:
    raster_crs = src.crs
    raster_transform = src.transform

    # Cargar la geometría de la cuenca (watershed_gdf ya está cargado, pero la obtenemos para consistencia)
    # Asegurarse de que la geometría de la cuenca esté en el mismo CRS que el raster
    watershed_geometry_reprojected = watershed_gdf.to_crs(raster_crs).geometry

    # Convertir la geometría a un formato que `rasterio.mask.mask` pueda usar (lista de diccionarios GeoJSON)
    geometries = [json.loads(watershed_geometry_reprojected.to_json())['features'][0]['geometry']]

    # Recortar el raster usando la geometría de la cuenca
    out_image, out_transform = mask(src, geometries, crop=True)
    out_meta = src.meta.copy()

    # Actualizar los metadatos para el raster recortado
    out_meta.update(
        {
            "driver": "GTiff",
            "height": out_image.shape[1],
            "width": out_image.shape[2],
            "transform": out_transform,
        }
    )

    # Visualizar el raster recortado
    plt.figure(figsize=(10, 10))
    plt.imshow(
        out_image[0], cmap='viridis'
    ) # Usamos 'viridis' para un mapa de calor para valores
    plt.title('Raster Recortado por la Cuenca')
    plt.xlabel('Píxeles X')
    plt.ylabel('Píxeles Y')
    plt.colorbar(label='Valor del píxel')
    plt.show()

    print("Raster recortado y visualizado exitosamente.")

"""### Álgebra de Mapas con el Raster Recortado

El álgebra de mapas permite realizar operaciones matemáticas y lógicas sobre los rásteres, píxel a píxel. Por ejemplo, podemos:

*   **Suma/Resta/Multiplicación/División** por un escalar o por otro raster.
*   **Operaciones lógicas** (ej. `raster > 1000`).
*   **Funciones estadísticas**.

Aquí, demostraremos una operación simple: sumar un valor constante a cada píxel del raster recortado.
"""

import numpy as np
import matplotlib.pyplot as plt

# El raster recortado está en la variable `out_image` (es un array numpy)
# Asegúrate de que `out_image` no esté vacío o sea None
if out_image is not None and out_image.size > 0:

    # Ejemplo de operación de álgebra de mapas: sumar un valor constante
    constant_value = 100
    raster_sumado = out_image[0] + constant_value

    print("Valores del raster recortado (primeros 5x5 píxeles):")
    print(out_image[0][:5, :5])
    print(f"Valores del raster sumado con {constant_value} (primeros 5x5 píxeles):")
    print(raster_sumado[:5, :5])

    # Visualizar el raster resultante de la operación
    plt.figure(figsize=(10, 10))
    plt.imshow(raster_sumado, cmap='hot') # Usamos un cmap diferente para resaltar el cambio
    plt.title(f'Raster Recortado + {constant_value} (Álgebra de Mapas)')
    plt.xlabel('Píxeles X')
    plt.ylabel('Píxeles Y')
    plt.colorbar(label='Valor del píxel + constante')
    plt.show()

    print("Operación de álgebra de mapas y visualización exitosa.")
else:
    print("Error: El raster recortado (`out_image`) está vacío o no ha sido definido correctamente.")

