"""### Reclasificación del DEM por Rangos de Altitud

Vamos a reclasificar el DEM (Digital Elevation Model) recortado en diferentes rangos de altitud. Esto es útil para categorizar el terreno y puede ser el primer paso para análisis como la identificación de zonas con diferentes características de vegetación o riesgo de inundación.

Para ello, definiremos una serie de rangos y asignaremos un nuevo valor (o una categoría) a cada píxel que caiga dentro de esos rangos.
"""

import numpy as np
import matplotlib.pyplot as plt

# Asegúrate de que out_image contenga el raster recortado
if 'out_image' not in locals() or out_image is None or out_image.size == 0:
    print("Error: 'out_image' no está disponible o está vacío. Asegúrate de haber ejecutado las celdas de recorte del raster previamente.")
else:
    dem_clipped = out_image[0]

    # Definir los rangos de altitud y los valores de reclasificación
    # Ejemplo: [min_alt, max_alt) -> valor_reclasificado
    # Aquí usamos un valor entero para cada rango que representará la categoría.
    reclassification_bins = [
        (0, 500, 1),      # 0-499 metros -> Clase 1
        (500, 1000, 2),   # 500-999 metros -> Clase 2
        (1000, 1500, 3),  # 1000-1499 metros -> Clase 3
        (1500, 2000, 4),  # 1500-1999 metros -> Clase 4
        (2000, np.inf, 5) # 2000 metros en adelante -> Clase 5
    ]

    # Crear un raster de reclasificación inicializado a cero
    reclassified_dem = np.zeros_like(dem_clipped, dtype=int)

    # Aplicar la reclasificación
    for lower_bound, upper_bound, new_value in reclassification_bins:
        reclassified_dem[(dem_clipped >= lower_bound) & (dem_clipped < upper_bound)] = new_value

    print("DEM reclasificado exitosamente. Primeros 5x5 píxeles del resultado:")
    print(reclassified_dem[:5, :5])

    # Visualizar el raster reclasificado
    plt.figure(figsize=(10, 10))
    cmap = plt.colormaps.get_cmap('viridis').resampled(len(reclassification_bins))
    # Usamos Boundaries para asegurarnos de que la colorbar muestre las etiquetas correctas de clase
    bounds = np.arange(1, len(reclassification_bins) + 2) - 0.5
    norm = plt.cm.colors.BoundaryNorm(bounds, cmap.N)

    img = plt.imshow(reclassified_dem, cmap=cmap, norm=norm)
    plt.title('DEM Reclasificado por Rangos de Altitud')
    plt.xlabel('Píxeles X')
    plt.ylabel('Píxeles Y')

    # Configurar la barra de color para mostrar los rangos/clases
    cbar = plt.colorbar(img, ticks=np.arange(1, len(reclassification_bins) + 1))
    cbar.set_label('Clase de Altitud')

    plt.show()

    print("DEM reclasificado y visualizado exitosamente.")

"""### Guardar el Raster Reclasificado como GeoTIFF

Ahora que hemos reclasificado el DEM, es útil guardar este resultado en un nuevo archivo GeoTIFF. Esto te permitirá usar el raster reclasificado en otro software GIS o análisis posterior sin tener que recalcularlo.
"""

import rasterio
import os

# Asegúrate de que reclassified_dem y out_meta estén disponibles
if 'reclassified_dem' not in locals() or reclassified_dem is None:
    print("Error: 'reclassified_dem' no está disponible. Asegúrate de haber ejecutado la celda de reclasificación previamente.")
elif 'out_meta' not in locals() or out_meta is None:
    print("Error: 'out_meta' no está disponible. Asegúrate de haber ejecutado la celda de recorte del raster previamente.")
else:
    # Definir la ruta de salida para el nuevo GeoTIFF
    output_tif_path = '/content/reclassified_dem_watershed.tif'

    # Actualizar los metadatos para el nuevo raster reclasificado
    # Es importante que el dtype coincida con el tipo de datos de `reclassified_dem`
    output_meta = out_meta.copy()
    output_meta.update({
        "dtype": reclassified_dem.dtype.name, # Actualizar el tipo de dato (ej. 'int64')
        "count": 1 # Asumimos que el raster reclasificado tendrá 1 banda
    })

    # Escribir el nuevo GeoTIFF
    with rasterio.open(output_tif_path, 'w', **output_meta) as dst:
        dst.write(reclassified_dem, 1) # Escribir la banda 1

    print(f"Raster reclasificado guardado exitosamente en: {output_tif_path}")

    # Opcional: Verificar el nuevo archivo abriéndolo y mostrando sus propiedades
    with rasterio.open(output_tif_path) as src_reclassified:
        print("\nVerificando propiedades del archivo guardado:")
        print(src_reclassified.profile)

