    unique_classes, counts = np.unique(reclassified_dem, return_counts=True)

    # Crear un DataFrame para una mejor visualización
    frequency_df = pd.DataFrame({
        'Clase de Altitud': unique_classes,
        'Número de Píxeles': counts
    })

    # Calcular el porcentaje de píxeles
    total_pixels = reclassified_dem.size
    frequency_df['Porcentaje (%)'] = (frequency_df['Número de Píxeles'] / total_pixels * 100).round(2)

