"""### Cálculo del Área por Clase de Altitud en Hectáreas

Conocemos el número de píxeles por cada clase de altitud y el área total de la cuenca en metros cuadrados. Utilizaremos esta información para calcular el área que ocupa cada clase en hectáreas.
"""

# Asegurarse de que 'reclassified_dem', 'watershed_area_sq_m' y 'frequency_df' estén disponibles
if 'reclassified_dem' in locals() and reclassified_dem is not None and reclassified_dem.size > 0 and \
   'watershed_area_sq_m' in locals() and watershed_area_sq_m is not None and \
   'frequency_df' in locals() and frequency_df is not None:

    # Calcular el área de un solo píxel en metros cuadrados
    total_pixels_in_reclassified_dem = reclassified_dem.size
    pixel_area_sq_m = watershed_area_sq_m / total_pixels_in_reclassified_dem

    # Calcular el área por clase en metros cuadrados y luego en hectáreas
    frequency_df['Área (m²)'] = frequency_df['Número de Píxeles'] * pixel_area_sq_m
    frequency_df['Área (ha)'] = frequency_df['Área (m²)'] / 10000  # 1 hectárea = 10,000 m²

    print("Área total en hectáreas por clase de altitud:")
    display(frequency_df.round(2))

else:
    print("Error: Faltan variables necesarias ('reclassified_dem', 'watershed_area_sq_m' o 'frequency_df'). Asegúrate de haber ejecutado las celdas previas correctamente.")



