"""### Clasificación de la Pendiente en Clases de Terreno

Vamos a reclasificar la imagen de pendiente (`slope_image`) en diferentes clases de terreno, basadas en rangos de grados de pendiente. Esta clasificación es útil para entender la geomorfología y para análisis de aptitud del terreno.

Definiremos las siguientes clases:

*   **Clase 1: Plano** (0-2 grados)
*   **Clase 2: Suave** (2-5 grados)
*   **Clase 3: Moderado** (5-10 grados)
*   **Clase 4: Empinado** (10-25 grados)
*   **Clase 5: Muy Empinado** (>25 grados)
"""

import ee
import folium

# Asegurarse de que `roi_quebrada_honda` esté definido
if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores que la definen.')
else:
    # Cargar el activo de la cuenca de Earth Engine
    # Asumimos que es una FeatureCollection o Image, aunque el contexto sugiere que es una FeatureCollection (vectorial)
    # Si 'projects/studious-camp-486620-m3/assets/watershed' es una Image, el enfoque de visualización debería ser ligeramente diferente.
    # Por ahora, intentaremos cargarlo como FeatureCollection.
    try:
        ee_watershed_asset = ee.FeatureCollection('projects/studious-camp-486620-m3/assets/watershed')
        print('Activo de la cuenca de Earth Engine cargado exitosamente.')

        # Filtrar el activo por la geometría de Quebrada la Honda
        ee_watershed_asset_filtered = ee_watershed_asset.filterBounds(roi_quebrada_honda)

        # Obtener el centroide de la cuenca para centrar el mapa (reutilizamos centroid_quebrada_honda)
        if 'centroid_quebrada_honda' in locals() and centroid_quebrada_honda is not None:
            lon_qh, lat_qh = centroid_quebrada_honda['coordinates']
        else:
            # Calcular si no está disponible (para robustez)
            centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
            lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

        # Crear un mapa interactivo con folium
        m_ee_asset = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

        # Añadir el activo filtrado de Earth Engine al mapa como una capa GeoJSON
        # Necesitamos convertir la FeatureCollection a GeoJSON para folium
        folium.GeoJson(
            ee_watershed_asset_filtered.getInfo(),
            name='Activo de Cuenca de EE',
            style_function=lambda x: {'fillColor': '#ff000000', 'color': 'red', 'weight': 3} # Rojo, sin relleno
        ).add_to(m_ee_asset)

        # Añadir la geometría de la cuenca (original) como un contorno para referencia
        # Esto ayuda a comparar el activo de EE con la geometría local cargada previamente
        if 'watershed_gdf' in locals() and watershed_gdf is not None:
            folium.GeoJson(
                watershed_gdf.geometry.iloc[0].__geo_interface__,
                name='Límite de Cuenca Local',
                style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
            ).add_to(m_ee_asset)

        m_ee_asset.add_child(folium.LayerControl())

        display(m_ee_asset)

    except Exception as e:
        print(f"Error al cargar o visualizar el activo de Earth Engine: {e}")
        print("Por favor, verifica que el ID del activo sea correcto y que tenga los permisos adecuados.")



"""### Frecuencia de Píxeles por Clase de Pendiente

Ahora, calcularemos la frecuencia de píxeles para cada una de las clases de pendiente definidas en el raster reclasificado. Esto nos dará una idea de la distribución de las diferentes categorías de terreno dentro de la cuenca.
"""

import ee
import pandas as pd

# Calcular estadísticas de las clases de pendiente para la región de Colombia
# Usaremos un reducer para obtener los conteos de píxeles por clase.

# Definir el reducer para obtener el histograma de las clases
# El histograma nos dará la frecuencia de cada valor (clase)
reducer_hist = ee.Reducer.frequencyHistogram()

# Reducir la región para obtener el histograma
slope_class_counts = reclassified_slope.reduceRegion(**{
    'reducer': reducer_hist,
    'geometry': roi_colombia,
    'scale': 100, # Misma escala que para las estadísticas de pendiente
    'maxPixels': 1e13,
    'bestEffort': True
})

# Obtener los resultados del histograma
histogram_data = slope_class_counts.getInfo().get('slope_class')

if histogram_data:
    # Convertir el histograma a un DataFrame de pandas para mejor visualización
    frequency_df_slope = pd.DataFrame(histogram_data.items(), columns=['Clase de Pendiente', 'Número de Píxeles'])

    # Convertir la columna 'Clase de Pendiente' a tipo numérico y ordenar
    frequency_df_slope['Clase de Pendiente'] = frequency_df_slope['Clase de Pendiente'].astype(int)
    frequency_df_slope = frequency_df_slope.sort_values(by='Clase de Pendiente').reset_index(drop=True)

    # Calcular el porcentaje de píxeles
    total_pixels_slope = frequency_df_slope['Número de Píxeles'].sum()
    frequency_df_slope['Porcentaje (%)'] = (frequency_df_slope['Número de Píxeles'] / total_pixels_slope * 100).round(2)

    print("Frecuencia de píxeles por clase de pendiente:")
    display(frequency_df_slope)
else:
    print("No se pudieron calcular las frecuencias de píxeles para las clases de pendiente.")

"""### Cálculo de la Pendiente Media para la Cuenca 'Quebrada la Honda'

Ahora, calcularemos la pendiente media para toda la cuenca 'Quebrada la Honda' utilizando la imagen de pendiente que ya hemos derivado.
"""

import ee

# Asegurarse de que 'slope_image_quebrada_honda' y 'roi_quebrada_honda' estén disponibles
if 'slope_image_quebrada_honda' in locals() and slope_image_quebrada_honda is not None and \
   'roi_quebrada_honda' in locals() and roi_quebrada_honda is not None:

    # Calcular la pendiente media para la cuenca
    mean_slope_quebrada_honda = slope_image_quebrada_honda.reduceRegion(**{
        'reducer': ee.Reducer.mean(),
        'geometry': roi_quebrada_honda,
        'scale': 10, # Usar la misma escala que para los cálculos de frecuencia/área
        'maxPixels': 1e13,
        'bestEffort': True
    }).getInfo().get('slope') # 'slope' es el nombre de la banda por defecto de ee.Terrain.slope()

    if mean_slope_quebrada_honda is not None:
        print(f"La pendiente media de la cuenca 'Quebrada la Honda' es: {mean_slope_quebrada_honda:.2f} grados")
    else:
        print("No se pudo calcular la pendiente media para Quebrada la Honda.")
else:
    print('Error: Las variables necesarias (slope_image_quebrada_honda o roi_quebrada_honda) no están definidas.')

"""### Cálculo del Área por Clase de Pendiente en Hectáreas

Conocemos el número de píxeles por cada clase de pendiente. Utilizaremos esta información y el área total de la región de interés para calcular el área que ocupa cada clase de terreno en hectáreas.
"""

import ee
import pandas as pd

# Asegurarse de que 'frequency_df_slope' y 'roi_colombia' estén disponibles
if 'frequency_df_slope' in locals() and frequency_df_slope is not None and \
   'roi_colombia' in locals() and roi_colombia is not None:

    # Calcular el área total de la región de interés en metros cuadrados
    # La función .area() para ee.Geometry no toma 'scale' como argumento directo.
    # Utilizará la proyección predeterminada del objeto y un maxError.
    # Para mayor consistencia con el cálculo de frecuencia, es mejor calcular el área total
    # de la imagen reclasificada usando pixelArea y reduciéndola a la misma escala.

    total_image_area_sq_m = reclassified_slope.pixelArea().reduceRegion(**{
        'reducer': ee.Reducer.sum(),
        'geometry': roi_colombia,
        'scale': 100, # La misma escala que se usó para calcular el histograma
        'maxPixels': 1e13,
        'bestEffort': True
    }).getInfo().get('area') # 'area' es el nombre de la banda por defecto de pixelArea()

    if total_image_area_sq_m is None:
        print("Error: No se pudo calcular el área total de la imagen reclasificada.")
    else:
        # Calcular el número total de píxeles utilizados en el análisis del histograma
        total_pixels_in_analysis = frequency_df_slope['Número de Píxeles'].sum()

        # Calcular el área por píxel basándose en el área total de la imagen y el número total de píxeles.
        pixel_area_sq_m = total_image_area_sq_m / total_pixels_in_analysis

        # Calcular el área por clase en metros cuadrados y luego en hectáreas
        frequency_df_slope['Área (m²)'] = frequency_df_slope['Número de Píxeles'] * pixel_area_sq_m
        frequency_df_slope['Área (ha)'] = frequency_df_slope['Área (m²)'] / 10000  # 1 hectárea = 10,000 m²

        print("Área total en hectáreas por clase de pendiente:")
        display(frequency_df_slope.round(2))

else:
    print("Error: Faltan variables necesarias ('frequency_df_slope' o 'roi_colombia'). Asegúrate de haber ejecutado las celdas previas correctamente.")

