import matplotlib.pyplot as plt
import numpy as np
from matplotlib import colors as mcolors

# Asegúrate de que 'reclassified_dem' esté disponible desde la celda de reclasificación
if 'reclassified_dem' not in locals() or reclassified_dem is None or reclassified_dem.size == 0:
    print("Error: La variable 'reclassified_dem' no está disponible o está vacía. Asegúrate de haber ejecutado la celda de reclasificación previamente.")
else:
    # Definir los rangos de altitud y los valores de reclasificación (para las etiquetas)
    reclassification_bins = [
        (0, 500, 1),      # 0-499 metros -> Clase 1
        (500, 1000, 2),   # 500-999 metros -> Clase 2
        (1000, 1500, 3),  # 1000-1499 metros -> Clase 3
        (1500, 2000, 4),  # 1500-1999 metros -> Clase 4
        (2000, np.inf, 5) # 2000 metros en adelante -> Clase 5
    ]

    # Crear un colormap y normalización para las clases discretas
    # Usamos 'terrain' como un colormap que puede representar bien las altitudes
    cmap = plt.colormaps.get_cmap('terrain').resampled(len(reclassification_bins))

    # Las clases son 1, 2, 3, 4, 5. Los límites para la normalización deben centrar los colores
    # en estos valores discretos para la barra de color.
    bounds = np.array([rb[2] for rb in reclassification_bins]) # Obtener los valores de las clases
    min_val = np.min(bounds) # Valor mínimo de clase
    max_val = np.max(bounds) # Valor máximo de clase

    # Crear los límites para la normalización de la barra de color
    # Esto asegura que cada tick de la barra de color corresponda a una clase
    norm_bounds = np.arange(min_val - 0.5, max_val + 1.5, 1) # Ejemplo: [-0.5, 0.5, 1.5, ..., 5.5]
    norm = mcolors.BoundaryNorm(norm_bounds, cmap.N)

    # Visualizar el raster reclasificado
    plt.figure(figsize=(12, 10))
    img = plt.imshow(reclassified_dem, cmap=cmap, norm=norm)
    plt.title('DEM Reclasificado por Rangos de Altitud en la Cuenca')
    plt.xlabel('Píxeles X')
    plt.ylabel('Píxeles Y')

    # Configurar la barra de color para mostrar los rangos/clases con su interpretación
    cbar = plt.colorbar(img, ticks=bounds, format='%d') # Ticks en los valores de las clases

    # Crear las etiquetas de la barra de color con la interpretación
    cbar_labels = []
    for lower, upper, class_val in reclassification_bins:
        if upper == np.inf:
            cbar_labels.append(f'Clase {class_val}: >= {lower} m')
        else:
            cbar_labels.append(f'Clase {class_val}: {lower}-{upper-1} m')
    cbar.set_ticklabels(cbar_labels)
    cbar.set_label('Clase de Altitud e Interpretación')

    plt.show()

    print("Visualización del DEM reclasificado con colores y tabla de interpretación completada.")

