import folium
import numpy as np

# Asegurarse de que `dem_quebrada_honda` y `roi_quebrada_honda` estén definidos
if 'dem_quebrada_honda' not in locals() or dem_quebrada_honda is None:
    print('Error: La imagen DEM recortada para Quebrada la Honda (`dem_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'reclassified_slope_quebrada_honda' not in locals() or reclassified_slope_quebrada_honda is None:
    print('Error: La imagen de pendiente reclasificada (`reclassified_slope_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
else:
    # 1. Reclasificar el DEM de Quebrada la Honda en Earth Engine
    # Definir los rangos de altitud y los valores de reclasificación (igual que para el numpy)
    reclassification_bins_altitude_ee = [
        (0, 500, 1),      # 0-499 metros -> Clase 1
        (500, 1000, 2),   # 500-999 metros -> Clase 2
        (1000, 1500, 3),  # 1000-1499 metros -> Clase 3
        (1500, 2000, 4),  # 1500-1999 metros -> Clase 4
        (2000, np.inf, 5) # 2000 metros en adelante -> Clase 5
    ]

    # Crear una imagen vacía para la reclasificación de altitud
    reclassified_dem_ee = ee.Image(0).rename('altitude_class')

    # Aplicar la reclasificación usando operaciones de Earth Engine
    for lower, upper, class_val in reclassification_bins_altitude_ee:
        # Convertir np.inf a un número muy grande si es necesario para la comparación en EE
        upper_val = upper if upper != np.inf else 1000000 # Un valor suficientemente grande para altitud
        condition = dem_quebrada_honda.gte(lower).And(dem_quebrada_honda.lt(upper_val))
        reclassified_dem_ee = reclassified_dem_ee.where(condition, ee.Image(class_val))

    print('Imagen de Altitud Reclasificada para Quebrada la Honda (Earth Engine Image):')
    print(reclassified_dem_ee.getInfo())

    # 2. Definir parámetros de visualización para ambas capas
    altitude_class_vis = {
      'min': 1,
      'max': 5,
      'palette': ['#ffffcc', '#a1dab4', '#41b6c4', '#2c7fb8', '#253494'] # Colores para clases de altitud
    }

    # Los parámetros de visualización para la pendiente ya están definidos en `slope_class_vis` de celdas previas
    # Re-definimos para robustez si esta celda se ejecuta de forma independiente.
    slope_class_vis = {
      'min': 1,
      'max': 5,
      'palette': ['#d7191c', '#fdae61', '#ffffbf', '#a6d96a', '#1a9641'] # Colores para las clases de terreno
    }

    # Obtener el centroide de la cuenca para centrar el mapa (reutilizamos centroid_quebrada_honda)
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    # 3. Crear un mapa Folium base
    m_combined = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # 4. Añadir la capa de Altitud Reclasificada
    map_id_altitude = ee.Image(reclassified_dem_ee).getMapId(altitude_class_vis)
    folium.TileLayer(
        tiles=map_id_altitude['tile_fetcher'].url_format,
        attr='Google Earth Engine - Clases de Altitud',
        overlay=True,
        name='Clases de Altitud'
    ).add_to(m_combined)

    # 5. Añadir la capa de Pendiente Reclasificada
    map_id_slope = ee.Image(reclassified_slope_quebrada_honda).getMapId(slope_class_vis)
    folium.TileLayer(
        tiles=map_id_slope['tile_fetcher'].url_format,
        attr='Google Earth Engine - Clases de Pendiente',
        overlay=True,
        name='Clases de Pendiente'
    ).add_to(m_combined)

    # 6. Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2}
    ).add_to(m_combined)

    # 7. Añadir control de capas
    m_combined.add_child(folium.LayerControl())

    display(m_combined)
    print('\nMapa interactivo combinado de clases de altitud y pendiente completado.')

"""### Comparación de Precipitación con Clases de Altitud

Ahora vamos a analizar la relación entre la precipitación y las clases de altitud predefinidas para la cuenca 'Quebrada la Honda'. Para ello, cargaremos datos de precipitación, los recortaremos a la cuenca y calcularemos la precipitación media para cada clase de altitud.
"""

import ee
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

# Asegurarse de que `roi_quebrada_honda` y `reclassified_dem_ee` estén definidos
if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'reclassified_dem_ee' not in locals() or reclassified_dem_ee is None:
    print('Error: La imagen de clases de altitud (`reclassified_dem_ee`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'precipitation_quebrada_honda_analysis' not in locals() or precipitation_quebrada_honda_analysis is None:
    print('Error: La imagen de precipitación media de análisis (`precipitation_quebrada_honda_analysis`) no está definida. Por favor, ejecuta las celdas anteriores que la definen.')
else:
    # Usar la imagen de precipitación media calculada previamente para un período más representativo
    # `precipitation_quebrada_honda_analysis` ya contiene la precipitación media para 2020-01-01 a 2035-12-31
    precipitation_quebrada_honda = precipitation_quebrada_honda_analysis

    print(f'Imagen de precipitación media para Quebrada la Honda ({new_start_date_analysis} a {new_end_date_analysis}):')
    print(precipitation_quebrada_honda.getInfo())

    # 2. Combinar la imagen de precipitación con la imagen de clases de altitud
    # Necesitamos las clases de altitud como una banda en la imagen de precipitación para agrupar.
    # La imagen `reclassified_dem_ee` ya está recortada a la cuenca.
    combined_image = precipitation_quebrada_honda.addBands(reclassified_dem_ee)

    # 3. Calcular estadísticas zonales: precipitación media por clase de altitud
    # Usamos reduceRegion con un reducer de grupo para obtener la media por cada clase.
    precipitation_by_altitude_class = combined_image.reduceRegion(**{
        'reducer': ee.Reducer.mean().group(
            groupField=1, # El índice de la banda de clases de altitud (0 para precip, 1 para altitud)
            groupName='altitude_class' # Nombre de la columna para las clases
        ),
        'geometry': roi_quebrada_honda,
        'scale': 100, # Escala a la que se realizará el cálculo (ej. 100 metros)
        'maxPixels': 1e13,
        'bestEffort': True
    })

    # Obtener los resultados y convertirlos a un DataFrame de pandas
    results = precipitation_by_altitude_class.getInfo()
    if results and 'groups' in results:
        data = []
        for group in results['groups']:
            altitude_class = group['altitude_class']
            # FIX: Acceder a 'mean' en lugar de 'mean_precipitation'
            mean_prec = group['mean']
            data.append({'Clase de Altitud': altitude_class, 'Precipitación Media (mm)': mean_prec})

        precipitation_altitude_df = pd.DataFrame(data)
        precipitation_altitude_df = precipitation_altitude_df.sort_values(by='Clase de Altitud').reset_index(drop=True)

        print('Precipitación Media por Clase de Altitud en la cuenca Quebrada la Honda:')
        display(precipitation_altitude_df.round(2))

        # 4. Visualizar los resultados en un gráfico de barras
        plt.figure(figsize=(10, 6))
        sns.barplot(x='Clase de Altitud', y='Precipitación Media (mm)', data=precipitation_altitude_df, palette='GnBu')
        plt.title(f'Precipitación Media por Clase de Altitud en Quebrada la Honda ({new_start_date_analysis} a {new_end_date_analysis})')
        plt.xlabel('Clase de Altitud')
        plt.ylabel('Precipitación Media (mm)')
        plt.grid(axis='y', linestyle='--', alpha=0.7)
        plt.show()

    else:
        print('No se pudieron obtener resultados de precipitación por clase de altitud.')

