"""### Correlación entre Temperatura Media y Clases de Altitud

Vamos a analizar cómo varía la temperatura media en función de las clases de altitud dentro de la cuenca 'Quebrada la Honda'. Para ello, calcularemos la temperatura media para cada clase de altitud y visualizaremos esta relación.
"""

import ee
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

# Asegurarse de que `temperature_quebrada_honda`, `reclassified_dem_ee` y `roi_quebrada_honda` estén definidos
if 'temperature_quebrada_honda' not in locals() or temperature_quebrada_honda is None:
    print('Error: La imagen de temperatura (`temperature_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'reclassified_dem_ee' not in locals() or reclassified_dem_ee is None:
    print('Error: La imagen de clases de altitud (`reclassified_dem_ee`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
else:
    # 1. Combinar la imagen de temperatura con la imagen de clases de altitud
    # Ambas imágenes deben estar recortadas a la misma región.
    combined_temp_altitude_image = temperature_quebrada_honda.addBands(reclassified_dem_ee)

    # 2. Calcular la temperatura media por clase de altitud
    # Usamos reduceRegion con un reducer de grupo para obtener la media de 'temperature_celsius' por cada 'altitude_class'.
    temperature_by_altitude_class = combined_temp_altitude_image.reduceRegion(**{
        'reducer': ee.Reducer.mean().group(
            groupField=1, # El índice de la banda de clases de altitud (0 para temp, 1 para altitud)
            groupName='altitude_class' # Nombre de la columna para las clases
        ),
        'geometry': roi_quebrada_honda,
        'scale': 30, # Usar una escala adecuada para los datos de temperatura y DEM
        'maxPixels': 1e13,
        'bestEffort': True
    })

    # Obtener los resultados y convertirlos a un DataFrame de pandas
    results_temp_altitude = temperature_by_altitude_class.getInfo()
    if results_temp_altitude and 'groups' in results_temp_altitude:
        data_temp_altitude = []
        for group in results_temp_altitude['groups']:
            altitude_class = group['altitude_class']
            mean_temp = group['mean'] # 'mean' es el nombre de la salida del reducer
            data_temp_altitude.append({'Clase de Altitud': altitude_class, 'Temperatura Media (°C)': mean_temp})

        temperature_altitude_df = pd.DataFrame(data_temp_altitude)
        temperature_altitude_df = temperature_altitude_df.sort_values(by='Clase de Altitud').reset_index(drop=True)

        print('Temperatura Media por Clase de Altitud en la cuenca Quebrada la Honda:')
        display(temperature_altitude_df.round(2))

        # 3. Visualizar los resultados en un gráfico de barras
        plt.figure(figsize=(10, 6))
        sns.barplot(x='Clase de Altitud', y='Temperatura Media (°C)', data=temperature_altitude_df, palette='coolwarm', hue='Clase de Altitud', legend=False)
        plt.title('Temperatura Media por Clase de Altitud en Quebrada la Honda')
        plt.xlabel('Clase de Altitud')
        plt.ylabel('Temperatura Media (°C)')
        plt.grid(axis='y', linestyle='--', alpha=0.7)
        plt.xticks(rotation=0)
        plt.show()

    else:
        print('No se pudieron obtener resultados de temperatura por clase de altitud.')

"""### Cálculo de la Correlación de Pearson entre Altitud, Temperatura y Precipitación

Para entender las relaciones entre estas variables, combinaremos los resultados de la precipitación y la temperatura media por clase de altitud, y luego calcularemos el coeficiente de correlación de Pearson. Utilizaremos una altitud representativa para cada clase para el cálculo de la correlación.
"""

import pandas as pd
import numpy as np
import seaborn as sns
import matplotlib.pyplot as plt

# Asegurarse de que los DataFrames estén disponibles
if 'precipitation_altitude_df' not in locals() or precipitation_altitude_df is None or \
   'temperature_altitude_df' not in locals() or temperature_altitude_df is None:
    print('Error: DataFrames necesarios para el cálculo de correlación no están disponibles.')
else:
    # 1. Fusionar los DataFrames de precipitación y temperatura por clase de altitud
    # Usamos merge para combinar los dos DataFrames en 'Clase de Altitud'
    combined_df = pd.merge(precipitation_altitude_df, temperature_altitude_df, on='Clase de Altitud', how='inner')

    # 2. Añadir una columna de altitud representativa para cada clase
    # Usaremos los puntos medios de los rangos de altitud definidos previamente.
    # El mapa 'altitude_map' está disponible en el kernel si se definió.
    # Si no, lo definimos aquí para robustez.
    altitude_map_for_correlation = {
        1: 250.0,   # (0, 500) -> 250
        2: 750.0,   # (500, 1000) -> 750
        3: 1250.0,  # (1000, 1500) -> 1250
        4: 1750.0,  # (1500, 2000) -> 1750
        5: 2450.5   # (2000, np.inf) -> Se usa un valor representativo basado en el DEM máximo
    }

    combined_df['Altitud Representativa (m)'] = combined_df['Clase de Altitud'].map(altitude_map_for_correlation)

    print('DataFrame combinado con altitud representativa:')
    display(combined_df)

    # 3. Calcular la matriz de correlación de Pearson
    # Seleccionamos las columnas de interés para la correlación
    correlation_matrix = combined_df[['Altitud Representativa (m)', 'Temperatura Media (°C)', 'Precipitación Media (mm)']].corr(method='pearson')

    print('\nMatriz de Correlación de Pearson:')
    display(correlation_matrix.round(2))

    # 4. Visualizar la matriz de correlación como un mapa de calor
    plt.figure(figsize=(8, 6))
    sns.heatmap(correlation_matrix, annot=True, cmap='coolwarm', fmt=".2f", linewidths=.5)
    plt.title('Matriz de Correlación de Pearson (Altitud, Temperatura, Precipitación)')
    plt.show()

    print('\nAnálisis de correlación completado.')

