"""Recortar el DEM de HydroSHEDS a la cuenca 'Quebrada la Honda' y calcular la imagen de pendiente reclasificada."""

import numpy as np

if 'roi_quebrada_honda' in locals() and roi_quebrada_honda is not None:
    # Cargar hydrosheds_dem_image si no está definida o si Earth Engine acaba de ser inicializado
    # Asegurarse de que ee.Initialize() haya sido llamada antes de esto.
    if 'hydrosheds_dem_image' not in locals() or hydrosheds_dem_image is None:
        try:
            hydrosheds_dem_image = ee.Image('WWF/HydroSHEDS/03VFDEM')
        except Exception as e:
            print(f"Error cargando hydrosheds_dem_image: {e}")
            hydrosheds_dem_image = None

    if hydrosheds_dem_image is not None:
        dem_quebrada_honda = hydrosheds_dem_image.clip(roi_quebrada_honda)
        print('DEM de HydroSHEDS recortado para Quebrada la Honda:')
        print(dem_quebrada_honda.getInfo())

        # Reclasificar el DEM de Quebrada la Honda en Earth Engine
        reclassification_bins_altitude_ee = [
            (0, 500, 1),
            (500, 1000, 2),
            (1000, 1500, 3),
            (1500, 2000, 4),
            (2000, np.inf, 5)
        ]
        reclassified_dem_ee = ee.Image(0).rename('altitude_class')
        for lower, upper, class_val in reclassification_bins_altitude_ee:
            upper_val = upper if upper != np.inf else 1000000
            condition = dem_quebrada_honda.gte(lower).And(dem_quebrada_honda.lt(upper_val))
            reclassified_dem_ee = reclassified_dem_ee.where(condition, ee.Image(class_val))
        print('Imagen de Altitud Reclasificada para Quebrada la Honda (Earth Engine Image):')
        print(reclassified_dem_ee.getInfo())

        # También generar la imagen de pendiente reclasificada
        slope_image_quebrada_honda = ee.Terrain.slope(dem_quebrada_honda)
        reclassification_bins_slope = [
            [0, 2, 1],    # Plano
            [2, 5, 2],    # Suave
            [5, 10, 3],   # Moderado
            [10, 25, 4],  # Empinado
            [25, 100, 5]  # Muy Empinado
        ]
        reclassified_slope_quebrada_honda = ee.Image(0).rename('slope_class')
        for lower, upper, class_val in reclassification_bins_slope:
            condition = slope_image_quebrada_honda.gte(lower).And(slope_image_quebrada_honda.lt(upper))
            reclassified_slope_quebrada_honda = reclassified_slope_quebrada_honda.where(condition, ee.Image(class_val))
        print('Imagen de Pendiente Reclasificada para Quebrada la Honda (Earth Engine Image):')
        print(reclassified_slope_quebrada_honda.getInfo())


    else:
        print('Error: hydrosheds_dem_image no está cargado. No se puede proceder con el DEM ni la reclasificación.')

else:
    print('Error: roi_quebrada_honda no está definido. No se puede proceder con el DEM ni la reclasificación.')

"""Cargar la imagen de temperatura ERA5-Land para la cuenca."""

import ee

if 'roi_quebrada_honda' in locals() and roi_quebrada_honda is not None:
    era5_land_hourly = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    start_date = '2020-07-01T00:00:00'
    end_date = '2020-07-01T23:59:59'
    temperature_collection = era5_land_hourly.filterDate(start_date, end_date)
    daily_temperature = temperature_collection.select('temperature_2m').mean()
    temperature_quebrada_honda = daily_temperature.subtract(273.15).rename('temperature_celsius').clip(roi_quebrada_honda)
    print('Imagen de temperatura para Quebrada la Honda (en Celsius) cargada:')
    print(temperature_quebrada_honda.getInfo())
else:
    print('Error: roi_quebrada_honda no está definida para cargar la temperatura.')

"""Cargar la imagen de precipitación CHIRPS para la cuenca."""

import ee

if 'roi_quebrada_honda' in locals() and roi_quebrada_honda is not None:
    new_start_date_analysis = '2020-01-01'
    new_end_date_analysis = '2035-12-31'
    chirps_daily_analysis = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY').filterDate(new_start_date_analysis, new_end_date_analysis)
    mean_precipitation_analysis = chirps_daily_analysis.select('precipitation').mean().rename('mean_precipitation_2020_2035')
    precipitation_quebrada_honda_analysis = mean_precipitation_analysis.clip(roi_quebrada_honda)
    print(f'Imagen de precipitación media para Quebrada la Honda ({new_start_date_analysis} a {new_end_date_analysis}) cargada:')
    print(precipitation_quebrada_honda_analysis.getInfo())
else:
    print('Error: roi_quebrada_honda no está definida para cargar la precipitación.')

"""Recalcular `precipitation_altitude_df` y `temperature_altitude_df`."""

import pandas as pd

# Recalcular precipitation_altitude_df
if 'roi_quebrada_honda' in locals() and roi_quebrada_honda is not None and \
   'reclassified_dem_ee' in locals() and reclassified_dem_ee is not None and \
   'precipitation_quebrada_honda_analysis' in locals() and precipitation_quebrada_honda_analysis is not None:

    precipitation_quebrada_honda = precipitation_quebrada_honda_analysis
    combined_image = precipitation_quebrada_honda.addBands(reclassified_dem_ee)
    precipitation_by_altitude_class = combined_image.reduceRegion(**{
        'reducer': ee.Reducer.mean().group(
            groupField=1,
            groupName='altitude_class'
        ),
        'geometry': roi_quebrada_honda,
        'scale': 100,
        'maxPixels': 1e13,
        'bestEffort': True
    })
    results = precipitation_by_altitude_class.getInfo()
    if results and 'groups' in results:
        data = []
        for group in results['groups']:
            altitude_class = group['altitude_class']
            mean_prec = group['mean']
            data.append({'Clase de Altitud': altitude_class, 'Precipitación Media (mm)': mean_prec})
        precipitation_altitude_df = pd.DataFrame(data)
        precipitation_altitude_df = precipitation_altitude_df.sort_values(by='Clase de Altitud').reset_index(drop=True)
        print('Precipitación Media por Clase de Altitud en la cuenca Quebrada la Honda:')
        display(precipitation_altitude_df.round(2))
    else:
        print('No se pudieron obtener resultados de precipitación por clase de altitud.')
else:
    print('Error: Variables necesarias para calcular precipitation_altitude_df no están definidas.')

# Recalcular temperature_altitude_df
if 'temperature_quebrada_honda' in locals() and temperature_quebrada_honda is not None and \
   'reclassified_dem_ee' in locals() and reclassified_dem_ee is not None and \
   'roi_quebrada_honda' in locals() and roi_quebrada_honda is not None:

    combined_temp_altitude_image = temperature_quebrada_honda.addBands(reclassified_dem_ee)
    temperature_by_altitude_class = combined_temp_altitude_image.reduceRegion(**{
        'reducer': ee.Reducer.mean().group(
            groupField=1,
            groupName='altitude_class'
        ),
        'geometry': roi_quebrada_honda,
        'scale': 30,
        'maxPixels': 1e13,
        'bestEffort': True
    })
    results_temp_altitude = temperature_by_altitude_class.getInfo()
    if results_temp_altitude and 'groups' in results_temp_altitude:
        data_temp_altitude = []
        for group in results_temp_altitude['groups']:
            altitude_class = group['altitude_class']
            mean_temp = group['mean']
            data_temp_altitude.append({'Clase de Altitud': altitude_class, 'Temperatura Media (°C)': mean_temp})
        temperature_altitude_df = pd.DataFrame(data_temp_altitude)
        temperature_altitude_df = temperature_altitude_df.sort_values(by='Clase de Altitud').reset_index(drop=True)
        print('\nTemperatura Media por Clase de Altitud en la cuenca Quebrada la Honda:')
        display(temperature_altitude_df.round(2))
    else:
        print('No se pudieron obtener resultados de temperatura por clase de altitud.')
else:
    print('Error: Variables necesarias para calcular temperature_altitude_df no están definidas.')

