"""Visualizar el modelo de regresión lineal en un gráfico de dispersión."""

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.linear_model import LinearRegression
from sklearn.model_selection import train_test_split
from sklearn.metrics import r2_score

if 'combined_df' in locals() and combined_df is not None:
    X = combined_df[['Temperatura Media (°C)']].values
    y = combined_df['Precipitación Media (mm)'].values

    model = LinearRegression()
    model.fit(X, y)
    y_pred = model.predict(X)

    intercept = model.intercept_
    slope = model.coef_[0]
    r_squared = r2_score(y, y_pred)

    print(f"Resultados de la Regresión Lineal:")
    print(f"  Intercepto: {intercept:.2f}")
    print(f"  Pendiente (coeficiente de temperatura): {slope:.2f}")
    print(f"  Coeficiente R-cuadrado (R²): {r_squared:.2f}")

    plt.figure(figsize=(10, 7))
    sns.scatterplot(x='Temperatura Media (°C)', y='Precipitación Media (mm)', hue='Clase de Altitud', data=combined_df, s=100, palette='viridis', legend='full')
    plt.plot(X, y_pred, color='red', linewidth=2, label=f'Línea de Regresión (y = {slope:.2f}x + {intercept:.2f})')
    plt.title('Regresión Lineal Simple: Temperatura Media vs. Precipitación Media')
    plt.xlabel('Temperatura Media (°C)')
    plt.ylabel('Precipitación Media (mm)')
    plt.grid(True, linestyle='--', alpha=0.7)
    plt.legend()
    plt.show()

    print('\nAnálisis de regresión lineal y visualización completados.')
else:
    print('Error: El DataFrame combinado (`combined_df`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')

import pandas as pd
from sklearn.linear_model import LinearRegression
import statsmodels.api as sm # Para un resumen estadístico más detallado

# Asegurarse de que `combined_df` esté disponible
if 'combined_df' not in locals() or combined_df is None:
    print('Error: El DataFrame combinado (`combined_df`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
else:
    # Definir las variables dependiente e independiente
    # Variable dependiente (y): Precipitación Media (mm)
    # Variables independientes (X): Altitud Representativa (m), Temperatura Media (°C)
    X = combined_df[['Altitud Representativa (m)', 'Temperatura Media (°C)']]
    y = combined_df['Precipitación Media (mm)']

    # Añadir una constante a las variables independientes para el cálculo del intercepto con statsmodels
    X_sm = sm.add_constant(X)

    # Crear y ajustar el modelo de regresión lineal múltiple con statsmodels
    # statsmodels proporciona un resumen estadístico más completo
    model_sm = sm.OLS(y, X_sm)
    results_sm = model_sm.fit()

    print("Resultados de la Regresión Lineal Múltiple (Precipitación ~ Altitud + Temperatura):")
    print(results_sm.summary())

    # También podemos usar sklearn para obtener solo los coeficientes y R-cuadrado de forma más directa
    model_sk = LinearRegression()
    model_sk.fit(X, y)
    y_pred = model_sk.predict(X)

    print("\nResultados del Modelo sklearn.linear_model.LinearRegression:")
    print(f"  Intercepto: {model_sk.intercept_:.2f}")
    print(f"  Coeficientes (Altitud, Temperatura): {model_sk.coef_[0]:.2f}, {model_sk.coef_[1]:.2f}")
    print(f"  Coeficiente R-cuadrado (R²): {model_sk.score(X, y):.2f}")

