import zipfile
import os
import geopandas as gpd

zip_file_path_rivers = '/content/rivers.zip'
unzip_dir_rivers = '/content/rivers_extracted'

# Create the directory if it doesn't exist
os.makedirs(unzip_dir_rivers, exist_ok=True)

# Unzip the file
try:
    with zipfile.ZipFile(zip_file_path_rivers, 'r') as zip_ref:
        zip_ref.extractall(unzip_dir_rivers)
    print(f"Archivo '{zip_file_path_rivers}' descomprimido en '{unzip_dir_rivers}'.")

    # List the contents of the unzipped directory
    print("\nContenido del directorio descomprimido de ríos:")
    for root, dirs, files in os.walk(unzip_dir_rivers):
        for name in files:
            print(os.path.join(root, name))
        for name in dirs:
            print(os.path.join(root, name))

    # Identify the .shp file within the unzipped directory
    shp_file_rivers = None
    for root, dirs, files in os.walk(unzip_dir_rivers):
        for file in files:
            if file.endswith('.shp'):
                shp_file_rivers = os.path.join(root, file)
                break
        if shp_file_rivers:
            break

    if shp_file_rivers:
        # Load the Shapefile into a GeoDataFrame
        try:
            rivers_gdf = gpd.read_file(shp_file_rivers)
            print('\nShapefile de la red hídrica cargado exitosamente en un GeoDataFrame:')
            display(rivers_gdf.head())
            print(f'Sistema de Coordenadas (CRS): {rivers_gdf.crs}')
            print(f'Número de geometrías: {len(rivers_gdf)}')
        except Exception as e:
            print(f'Error al cargar el Shapefile de ríos: {e}')
    else:
        print(f'Error: No se encontró ningún archivo .shp en el directorio {unzip_dir_rivers}.')

except FileNotFoundError:
    print(f"Error: El archivo ZIP '{zip_file_path_rivers}' no se encontró. Asegúrate de que el archivo esté presente en la ruta especificada.")
except Exception as e:
    print(f"Ocurrió un error inesperado al descomprimir o cargar el archivo de ríos: {e}")

import ee
import folium
import numpy as np
import matplotlib.colors as mcolors
import matplotlib.pyplot as plt
from sklearn.cluster import KMeans
import geopandas as gpd
import os
import zipfile

print('Generando umbrales de pendiente y precipitación usando IA (KMeans) para la cuenca Quebrada la Honda...')

# --- Asegurar la disponibilidad de variables clave --- (para robustez)
# Re-inicializar Earth Engine para asegurar el contexto
try:
    ee.Initialize(project='studious-camp-486620-m3')
    print('Earth Engine inicializado.')
except Exception as e:
    print(f'Error al inicializar Earth Engine: {e}. Por favor, asegúrate de haber ejecutado ee.Authenticate() y ee.Initialize() con un Project ID válido.')

# 1. Asegurar watershed_gdf y roi_quebrada_honda
if 'watershed_gdf' not in locals() or watershed_gdf is None or watershed_gdf.empty:
    print('`watershed_gdf` no encontrada o vacía. Intentando cargarla...')
    zip_file_path = '/content/watershed.zip'
    unzip_dir = '/content/watershed_extracted'
    shp_file_path = os.path.join(unzip_dir, 'watershed.shp')
    try:
        if not os.path.exists(shp_file_path): # Check if shp is already extracted
            os.makedirs(unzip_dir, exist_ok=True)
            with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:
                zip_ref.extractall(unzip_dir)
            print(f"Archivo '{zip_file_path}' descomprimido en '{unzip_dir}'.")
        watershed_gdf = gpd.read_file(shp_file_path)
        print('`watershed_gdf` cargada exitosamente.')
    except Exception as e:
        print(f'Error al cargar `watershed_gdf`: {e}')
        watershed_gdf = None

if watershed_gdf is not None and not watershed_gdf.empty:
    if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
        roi_quebrada_honda = ee.Geometry(watershed_gdf.geometry.iloc[0].__geo_interface__)
        print('`roi_quebrada_honda` creada.')
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
        print('`centroid_quebrada_honda` creada.')
else:
    print('Error crítico: `watershed_gdf` no está disponible, no se puede definir `roi_quebrada_honda`.')
    roi_quebrada_honda = None
    centroid_quebrada_honda = None

# 2. Asegurar dem_quebrada_honda y slope_image_quebrada_honda
if roi_quebrada_honda is not None:
    if 'dem_quebrada_honda' not in locals() or dem_quebrada_honda is None:
        print('`dem_quebrada_honda` no encontrada. Intentando recrearla...')
        try:
            hydrosheds_dem_image = ee.Image('WWF/HydroSHEDS/03VFDEM')
            dem_quebrada_honda = hydrosheds_dem_image.clip(roi_quebrada_honda)
            print('`dem_quebrada_honda` recreada.')
        except Exception as e:
            print(f'Error recreando `dem_quebrada_honda`: {e}')
            dem_quebrada_honda = None
    if 'slope_image_quebrada_honda' not in locals() or slope_image_quebrada_honda is None:
        print('`slope_image_quebrada_honda` no encontrada. Intentando recrearla...')
        if dem_quebrada_honda is not None:
            try:
                slope_image_quebrada_honda = ee.Terrain.slope(dem_quebrada_honda)
                print('`slope_image_quebrada_honda` recreada.')
            except Exception as e:
                print(f'Error recreando `slope_image_quebrada_honda`: {e}')
                slope_image_quebrada_honda = None
        else:
            print('Error: `dem_quebrada_honda` no está definida, no se puede recrear `slope_image_quebrada_honda`.')
            slope_image_quebrada_honda = None
else:
    print('Error crítico: `roi_quebrada_honda` no está definida, no se pueden recrear imágenes relacionadas con DEM.')
    dem_quebrada_honda = None
    slope_image_quebrada_honda = None

# 3. Asegurar precipitation_quebrada_honda_analysis
if 'precipitation_quebrada_honda_analysis' not in locals() or precipitation_quebrada_honda_analysis is None:
    print('`precipitation_quebrada_honda_analysis` no encontrada. Intentando recrearla...')
    if roi_quebrada_honda is not None:
        try:
            new_start_date_analysis = '2020-01-01'
            new_end_date_analysis = '2035-12-31'
            chirps_daily_analysis = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY').filterDate(new_start_date_analysis, new_end_date_analysis)
            mean_precipitation_analysis = chirps_daily_analysis.select('precipitation').mean().rename('mean_precipitation_2020_2035')
            precipitation_quebrada_honda_analysis = mean_precipitation_analysis.clip(roi_quebrada_honda)
            print('`precipitation_quebrada_honda_analysis` recreada.')
        except Exception as e:
            print(f'Error recreando `precipitation_quebrada_honda_analysis`: {e}')
            precipitation_quebrada_honda_analysis = None
    else:
        print('Error: `roi_quebrada_honda` no está definida, no se puede recrear `precipitation_quebrada_honda_analysis`.')
        precipitation_quebrada_honda_analysis = None

# 4. Asegurar rivers_gdf (debe haber sido cargado por la celda 22521824)
if 'rivers_gdf' not in locals() or rivers_gdf is None or rivers_gdf.empty:
    print('Error crítico: `rivers_gdf` no está disponible o vacía. Asegúrate de ejecutar la celda que carga la red hídrica.')
    rivers_gdf = None # Asegurar que sea None si no está disponible

print('Verificación de variables clave completada.')

# --- Proceder solo si todas las variables críticas están disponibles ---
if all(v is not None for v in [roi_quebrada_honda, watershed_gdf, dem_quebrada_honda,
                               slope_image_quebrada_honda, precipitation_quebrada_honda_analysis,
                               rivers_gdf, centroid_quebrada_honda]):

    # --- 1. Generar Umbrales de Pendiente usando IA (KMeans) ---
    print('''\nGenerando umbrales de pendiente con IA...''')
    slope_sample_points = slope_image_quebrada_honda.sample(
        region=roi_quebrada_honda,
        scale=10,  # Usar una escala más fina para la pendiente
        numPixels=1000,
        seed=10,
        dropNulls=True
    )
    slope_values = np.array([f['properties']['slope'] for f in slope_sample_points.getInfo()['features']]).reshape(-1, 1)

    if slope_values.size > 0:
        kmeans_slope = KMeans(n_clusters=4, random_state=0, n_init=10)
        kmeans_slope.fit(slope_values)
        slope_centroids = sorted(kmeans_slope.cluster_centers_.flatten())

        ai_slope_thresholds = []
        # Define a color palette for slope (e.g., from green to red for increasing slope/risk)
        slope_colors = ['#a6d96a', '#ffffbf', '#fdae61', '#d7191c'] # Green (flat) to Red (steep)

        for i in range(len(slope_centroids)):
            lower_bound = slope_centroids[i] if i == 0 else (slope_centroids[i-1] + slope_centroids[i]) / 2
            upper_bound = slope_centroids[i] if i == len(slope_centroids) - 1 else (slope_centroids[i] + slope_centroids[i+1]) / 2
            ai_slope_thresholds.append({
                'clase': i + 1,
                'min': lower_bound,
                'max': upper_bound,
                'color': slope_colors[i] # Add color to the threshold dictionary
            })
        ai_slope_thresholds[-1]['max'] = np.inf

        print('''\nUmbrales de Pendiente Generados por IA (KMeans):''')
        for umbral in ai_slope_thresholds:
            print(f"  Clase {umbral['clase']}: {umbral['min']:.2f}° - {umbral['max']:.2f}° (Color: {umbral['color']})")

        # Reclasificar la imagen de pendiente con los umbrales AI
        reclassified_slope_ai = ee.Image(0).rename('slope_class_ai')
        for threshold in ai_slope_thresholds:
            lower = threshold['min']
            upper = threshold['max']
            class_val = threshold['clase']
            upper_val_ee = upper if upper != np.inf else 100 # Máximo teórico para pendiente en grados es 90
            condition = slope_image_quebrada_honda.gte(lower).And(slope_image_quebrada_honda.lt(upper_val_ee))
            reclassified_slope_ai = reclassified_slope_ai.where(condition, ee.Image(class_val))
        print('Imagen de Pendiente Reclasificada con Umbrales AI creada.')
    else:
        print('No se pudieron extraer suficientes valores de pendiente para aplicar KMeans.')
        reclassified_slope_ai = None

    # --- 2. Generar Umbrales de Precipitación usando IA (KMeans) ---
    print('''\nGenerando umbrales de precipitación con IA...''')
    precipitation_sample_points = precipitation_quebrada_honda_analysis.sample(
        region=roi_quebrada_honda,
        scale=30,  # Usar una escala adecuada para la precipitación
        numPixels=1000,
        seed=11,
        dropNulls=True
    )
    precipitation_values = np.array([f['properties']['mean_precipitation_2020_2035'] for f in precipitation_sample_points.getInfo()['features']]).reshape(-1, 1)

    if precipitation_values.size > 0:
        kmeans_precipitation = KMeans(n_clusters=4, random_state=0, n_init=10)
        kmeans_precipitation.fit(precipitation_values)
        precipitation_centroids = sorted(kmeans_precipitation.cluster_centers_.flatten())

        ai_precipitation_thresholds = []
        # Define a color palette for precipitation (e.g., from light blue to dark blue for increasing precipitation)
        precipitation_colors = ['#deebf7', '#9ecae1', '#4292c6', '#08519c'] # Light blue (low) to Dark blue (high)

        for i in range(len(precipitation_centroids)):
            lower_bound = precipitation_centroids[i] if i == 0 else (precipitation_centroids[i-1] + precipitation_centroids[i]) / 2
            upper_bound = precipitation_centroids[i] if i == len(precipitation_centroids) - 1 else (precipitation_centroids[i] + precipitation_centroids[i+1]) / 2
            ai_precipitation_thresholds.append({
                'clase': i + 1,
                'min': lower_bound,
                'max': upper_bound,
                'color': precipitation_colors[i] # Add color to the threshold dictionary
            })
        ai_precipitation_thresholds[-1]['max'] = np.inf

        print('''\nUmbrales de Precipitación Generados por IA (KMeans):''')
        for umbral in ai_precipitation_thresholds:
            print(f"  Clase {umbral['clase']}: {umbral['min']:.2f}mm - {umbral['max']:.2f}mm (Color: {umbral['color']})")

        # Reclasificar la imagen de precipitación con los umbrales AI
        reclassified_precipitation_ai = ee.Image(0).rename('precipitation_class_ai')
        for threshold in ai_precipitation_thresholds:
            lower = threshold['min']
            upper = threshold['max']
            class_val = threshold['clase']
            upper_val_ee = upper if upper != np.inf else 1000 # Un valor grande para precipitación
            condition = precipitation_quebrada_honda_analysis.gte(lower).And(precipitation_quebrada_honda_analysis.lt(upper_val_ee))
            reclassified_precipitation_ai = reclassified_precipitation_ai.where(condition, ee.Image(class_val))
        print('Imagen de Precipitación Reclasificada con Umbrales AI creada.')
    else:
        print('No se pudieron extraer suficientes valores de precipitación para aplicar KMeans.')
        reclassified_precipitation_ai = None

    # --- 3. Crear el mapa interactivo combinado ---
    if reclassified_slope_ai is not None and reclassified_precipitation_ai is not None:
        lon_qh, lat_qh = centroid_quebrada_honda['coordinates']
        m_combined_ai_map = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

        # Parámetros de visualización para la pendiente (verde a rojo)
        slope_ai_vis = {
            'min': 1, 'max': 4,
            'palette': [t['color'] for t in ai_slope_thresholds] # Use colors from the thresholds
        }

        # Parámetros de visualización para la precipitación (azul claro a oscuro)
        precipitation_ai_vis = {
            'min': 1, 'max': 4,
            'palette': [t['color'] for t in ai_precipitation_thresholds] # Use colors from the thresholds
        }

        # Añadir la capa de Pendiente Reclasificada por IA
        map_id_slope_ai = reclassified_slope_ai.getMapId(slope_ai_vis)
        folium.TileLayer(
            tiles=map_id_slope_ai['tile_fetcher'].url_format,
            attr='Google Earth Engine - Pendiente AI',
            overlay=True,
            name='Clases de Pendiente (IA)',
            show=True # Visible por defecto
        ).add_to(m_combined_ai_map)

        # Añadir la capa de Precipitación Reclasificada por IA
        map_id_precipitation_ai = reclassified_precipitation_ai.getMapId(precipitation_ai_vis)
        folium.TileLayer(
            tiles=map_id_precipitation_ai['tile_fetcher'].url_format,
            attr='Google Earth Engine - Precipitación AI',
            overlay=True,
            name='Clases de Precipitación (IA)',
            show=True # Visible por defecto
        ).add_to(m_combined_ai_map)

        # Añadir la capa de Red Hídrica
        folium.GeoJson(
            rivers_gdf.to_json(),
            name='Red Hídrica por Orden de Corriente',
            style_function=lambda x: {
                'color': '#0000ff', # Azul para ríos
                'weight': x['properties']['sorder'] * 0.75,
                'tooltip': f"Orden de Corriente: {x['properties']['sorder']}"
            },
            tooltip=folium.GeoJsonTooltip(fields=['sorder'], aliases=['Orden de Corriente:'], localize=True),
            popup=folium.GeoJsonPopup(fields=['sorder'], aliases=['Orden de Corriente:'], localize=True)
        ).add_to(m_combined_ai_map)

        # Añadir el límite de la cuenca
        folium.GeoJson(
            watershed_gdf.geometry.iloc[0].__geo_interface__,
            name='Límite de Cuenca Quebrada la Honda',
            style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
        ).add_to(m_combined_ai_map)

        # Añadir control de capas
        m_combined_ai_map.add_child(folium.LayerControl())

        # --- Crear y añadir la leyenda HTML combinada ---
        def get_threshold_legend_html(title, thresholds, class_key='clase', min_key='min', max_key='max', color_key='color', unit=''):
            html = f'<p style="font-weight: bold; margin-bottom: 5px;">{title}</p>'
            html += '<ul style="list-style:none; padding:0; margin:0;">'
            for threshold in thresholds:
                min_val = f"{threshold[min_key]:.2f}" if threshold[min_key] != -np.inf else "< "
                max_val = f"{threshold[max_key]:.2f}" if threshold[max_key] != np.inf else "> "

                if threshold[min_key] == -np.inf:
                    range_str = f"{max_val}{unit}"
                elif threshold[max_key] == np.inf:
                    range_str = f">= {min_val}{unit}"
                else:
                    range_str = f"{min_val}{unit} - {max_val}{unit}"

                html += f'''
                    <li style="display:flex; align-items:center; margin-bottom:3px;">
                      <span style="background:{threshold[color_key]}; width:20px; height:15px; display:inline-block; margin-right:5px; border:1px solid black;"></span>
                      <span>Clase {threshold[class_key]}: {range_str}</span>
                    </li>
                '''
            html += '</ul>'
            return html

        legend_html_ai = f'''
        <div style="position: fixed;
                    bottom: 50px; left: 50px; width: 280px; height: auto;
                    border:2px solid grey; z-index:9999; font-size:14px;
                    background-color:white; opacity:0.9; padding:10px;">
          <h4 style="margin-top:0;">Leyenda (IA)</h4>
          {get_threshold_legend_html('Pendiente', ai_slope_thresholds, unit='°')}
          <br>
          {get_threshold_legend_html('Precipitación', ai_precipitation_thresholds, unit=' mm')}
          <br>
          <p style="font-weight: bold; margin-bottom: 5px;">Red Hídrica</p>
          <ul style="list-style:none; padding:0; margin:0;">
            <li style="display:flex; align-items:center; margin-bottom:3px;">
              <span style="background:#0000ff; width:20px; height:15px; display:inline-block; margin-right:5px; border:1px solid black;"></span>
              <span>Corrientes de Agua</span>
            </li>
          </ul>
          <br>
          <p style="font-weight: bold; margin-bottom: 5px;">Límite de Cuenca</p>
          <ul style="list-style:none; padding:0; margin:0;">
            <li style="display:flex; align-items:center; margin-bottom:3px;">
              <span style="background:#00000000; border:2px dashed black; width:20px; height:15px; display:inline-block; margin-right:5px;"></span>
              <span>Quebrada la Honda</span>
            </li>
          </ul>
        </div>
        '''

        m_combined_ai_map.get_root().html.add_child(folium.Element(legend_html_ai))

        display(m_combined_ai_map)
        print('''\nMapa interactivo de red hídrica, pendiente (IA) y precipitación (IA) con leyenda completado.''')

    else:
        print('Error crítico: Las imágenes reclasificadas (pendiente o precipitación) no están disponibles para generar el mapa combinado.')

else:
    print('Error crítico: No se pudieron asegurar todas las variables necesarias para generar los umbrales AI y el mapa.')

import os

# Asegurarse de que `m_combined_ai_map` esté disponible
if 'm_combined_ai_map' in locals() and m_combined_ai_map is not None:
    # Definir la ruta del archivo HTML local
    output_html_path = '/content/mapa_cuenca_ai.html'

    # Guardar el mapa como archivo HTML
    m_combined_ai_map.save(output_html_path)

