"""Ahora que tenemos cargados los datos de la red hídrica, podemos inspeccionar las columnas disponibles para determinar cómo categorizar los ríos. Buscaremos atributos como 'ORDER', 'STREAM_ORDER', 'CLASS', 'TYPE' o similar que indiquen la jerarquía o tipo de los cuerpos de agua."""

