"""El atributo 'sorder' parece ser adecuado para categorizar la red hídrica. Ahora procederemos a visualizar esta red, utilizando este atributo para diferenciar las corrientes. Luego podremos analizar cómo se relaciona con la información de precipitación y temperatura."""

import folium

# Asegurarse de que `rivers_gdf` y `watershed_gdf` estén disponibles
if 'rivers_gdf' not in locals() or rivers_gdf is None:
    print('Error: El GeoDataFrame de ríos (`rivers_gdf`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
elif 'watershed_gdf' not in locals() or watershed_gdf is None:
    print('Error: El GeoDataFrame de la cuenca (`watershed_gdf`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
else:
    # Obtener el centroide de la cuenca para centrar el mapa (reutilizamos centroid_quebrada_honda)
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    # Crear un mapa Folium centrado en la cuenca
    m_rivers = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # Definir una paleta de colores para las órdenes de corriente
    # Se pueden ajustar los colores y el número de órdenes si hay más variedad en los datos
    # Ejemplo de paleta: del azul claro para órdenes bajas al azul oscuro para órdenes altas
    colors = ['#deebf7', '#c6dbef', '#9ecae1', '#6baed6', '#4292c6', '#2171b5', '#084594']

    # Iterar sobre las órdenes de corriente únicas y añadir cada una como una capa GeoJson
    unique_sorders = sorted(rivers_gdf['sorder'].unique())

    # Crear un GeoJSON que combine todas las geometrías de ríos con sus propiedades
    # y aplicar la coloración basada en 'sorder'
    folium.GeoJson(
        rivers_gdf.to_json(),
        name='Red Hídrica por Orden de Corriente',
        style_function=lambda x: {
            'color': colors[x['properties']['sorder'] - 1] if x['properties']['sorder'] <= len(colors) else 'black',
            'weight': x['properties']['sorder'] * 0.75, # Ríos de orden superior más anchos
            'tooltip': f"Orden de Corriente: {x['properties']['sorder']}"
        },
        tooltip=folium.GeoJsonTooltip(fields=['sorder'], aliases=['Orden de Corriente:'], localize=True),
        popup=folium.GeoJsonPopup(fields=['sorder'], aliases=['Orden de Corriente:'], localize=True)
    ).add_to(m_rivers)

    # Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_rivers)

    # Añadir control de capas
    m_rivers.add_child(folium.LayerControl())

    display(m_rivers)
    print('\nVisualización de la red hídrica categorizada por orden de corriente completada.')

"""### Análisis de la Red Hídrica en relación con Altitud, Precipitación y Temperatura

Ahora que hemos visualizado la red hídrica categorizada, el siguiente paso es analizar cómo se relaciona esta categorización (orden de corriente) con los datos de altitud, precipitación y temperatura ya calculados para la cuenca 'Quebrada la Honda'.

Primero, vamos a calcular las estadísticas de altitud (media, min, max) para cada orden de corriente presente en la red hídrica. Esto nos permitirá entender cómo varía la altitud a lo largo de los diferentes órdenes de los ríos.
"""

import ee
import pandas as pd

# Asegurarse de que `rivers_gdf`, `dem_quebrada_honda` y `roi_quebrada_honda` estén definidos
if 'rivers_gdf' not in locals() or rivers_gdf is None:
    print('Error: El GeoDataFrame de ríos (`rivers_gdf`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
elif 'dem_quebrada_honda' not in locals() or dem_quebrada_honda is None:
    print('Error: La imagen DEM recortada para Quebrada la Honda (`dem_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
else:
    # Convertir rivers_gdf a ee.FeatureCollection
    # Solo necesitamos las geometrías de los ríos y su atributo 'sorder'
    ee_rivers = ee.FeatureCollection(rivers_gdf.__geo_interface__)

    # Calcular estadísticas zonales (media, min, max) del DEM para cada orden de corriente
    # Usamos reduceRegions para aplicar el reductor a cada Feature (río)
    # y luego un reducer de grupo en el GeoJSON resultante para agrupar por 'sorder'.

    # Primero, recortar el DEM a la extensión de los ríos para optimizar el cálculo si los ríos son una sub-parte de la cuenca.
    # Aunque en este caso los ríos ya están dentro de la cuenca, y el DEM ya está recortado a la cuenca.
    # Aseguramos que el DEM sea la imagen de entrada para el cálculo.

    # Aplicar reduceRegions a cada Feature de río para obtener estadísticas de altitud
    # Aseguramos que la banda del DEM se llame 'elevation' o similar para identificarla
    dem_quebrada_honda_renamed = dem_quebrada_honda.rename('elevation')

    # Calcular estadísticas de altitud para cada río
    river_altitude_stats = dem_quebrada_honda_renamed.reduceRegions(**{
        'collection': ee_rivers,
        'reducer': ee.Reducer.mean().combine(ee.Reducer.min(), '', True).combine(ee.Reducer.max(), '', True),
        'scale': 10, # Escala de muestreo para el cálculo (ej. 10m)
        'crs': dem_quebrada_honda_renamed.projection().crs() # Usar el CRS del DEM
        # 'bestEffort': True # Eliminado, ya que causa TypeError
    })

    # Convertir los resultados a una lista de diccionarios de Python
    altitude_data = []
    for feature in river_altitude_stats.getInfo()['features']:
        properties = feature['properties']
        altitude_data.append({
            'sorder': properties['sorder'],
            'mean_elevation': properties['mean'], # Corregido: 'mean' en lugar de 'elevation_mean'
            'min_elevation': properties['min'],   # Corregido: 'min' en lugar de 'elevation_min'
            'max_elevation': properties['max']    # Corregido: 'max' en lugar de 'elevation_max'
        })

    altitude_by_sorder_df = pd.DataFrame(altitude_data)

    # Agrupar por 'sorder' y calcular la media de las estadísticas (si un sorder tiene múltiples geometrías)
    altitude_summary_df = altitude_by_sorder_df.groupby('sorder').agg({
        'mean_elevation': 'mean',
        'min_elevation': 'min',
        'max_elevation': 'max'
    }).reset_index()

    print('Estadísticas de Altitud por Orden de Corriente en Quebrada la Honda:')
    display(altitude_summary_df.round(2))

