"""### Correlación entre la Red Hídrica y la Precipitación

Ahora, analizaremos cómo la precipitación media varía a lo largo de los diferentes órdenes de corriente de la red hídrica. Esto nos permitirá identificar si los ríos de órdenes superiores o inferiores tienden a estar asociados con mayores o menores precipitaciones.
"""

import ee
import pandas as pd

# Asegurarse de que `rivers_gdf`, `precipitation_quebrada_honda_analysis` y `roi_quebrada_honda` estén definidos
if 'rivers_gdf' not in locals() or rivers_gdf is None:
    print('Error: El GeoDataFrame de ríos (`rivers_gdf`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
elif 'precipitation_quebrada_honda_analysis' not in locals() or precipitation_quebrada_honda_analysis is None:
    print('Error: La imagen de precipitación media (`precipitation_quebrada_honda_analysis`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
else:
    # Convertir rivers_gdf a ee.FeatureCollection
    ee_rivers = ee.FeatureCollection(rivers_gdf.__geo_interface__)

    # Renombrar la banda de precipitación para una fácil identificación
    precipitation_quebrada_honda_renamed = precipitation_quebrada_honda_analysis.rename('precipitation')

    # Calcular estadísticas de precipitación para cada río
    river_precipitation_stats = precipitation_quebrada_honda_renamed.reduceRegions(**{
        'collection': ee_rivers,
        'reducer': ee.Reducer.mean(),
        'scale': 100, # Escala de muestreo para el cálculo (ajustar a la resolución de CHIRPS si es necesario)
        'crs': precipitation_quebrada_honda_renamed.projection().crs() # Usar el CRS de la precipitación
        # 'bestEffort': True # Eliminado, ya que causa TypeError
    })

    # Convertir los resultados a una lista de diccionarios de Python
    precipitation_data = []
    for feature in river_precipitation_stats.getInfo()['features']:
        properties = feature['properties']
        precipitation_data.append({
            'sorder': properties['sorder'],
            'mean_precipitation': properties['mean'] # Corregido: 'mean' en lugar de 'precipitation_mean'
        })

    precipitation_by_sorder_df = pd.DataFrame(precipitation_data)

    # Agrupar por 'sorder' y calcular la media de las precipitaciones
    precipitation_summary_df = precipitation_by_sorder_df.groupby('sorder').agg({
        'mean_precipitation': 'mean'
    }).reset_index()

    print('Precipitación Media por Orden de Corriente en Quebrada la Honda:')
    display(precipitation_summary_df.round(2))

