"""### Integración y Visualización de Correlaciones

Finalmente, integraremos las estadísticas de altitud, precipitación y temperatura por orden de corriente en un único DataFrame y visualizaremos estas correlaciones para obtener una comprensión holística de cómo estos factores interactúan en la red hídrica.

### Matriz de Correlación de Pearson para Variables Ambientales por Orden de Corriente

Vamos a calcular la matriz de correlación de Pearson entre la altitud media, la precipitación media y la temperatura media de los ríos, agrupados por su orden de corriente. Esto nos ayudará a entender cómo estas variables se relacionan entre sí en la red hídrica de la cuenca 'Quebrada la Honda'.
"""

import pandas as pd
import numpy as np
import seaborn as sns
import matplotlib.pyplot as plt

# Asegurarse de que `combined_rivers_df` esté disponible
if 'combined_rivers_df' not in locals() or combined_rivers_df is None:
    print('Error: El DataFrame combinado de ríos (`combined_rivers_df`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
else:
    # Seleccionar las columnas numéricas de interés para la correlación
    # Excluimos 'min_elevation' y 'max_elevation' para mantener el enfoque en las medias
    # y evitar redundancia, pero se podrían incluir si se desea un análisis más detallado.
    correlation_data = combined_rivers_df[['mean_elevation', 'mean_precipitation', 'mean_temperature']]

    # Calcular la matriz de correlación de Pearson
    correlation_matrix_rivers = correlation_data.corr(method='pearson')

    print('Matriz de Correlación de Pearson para variables ambientales por orden de corriente:')
    display(correlation_matrix_rivers.round(2))

    # Visualizar la matriz de correlación como un mapa de calor
    plt.figure(figsize=(8, 6))
    sns.heatmap(correlation_matrix_rivers, annot=True, cmap='coolwarm', fmt=".2f", linewidths=.5)
    plt.title('Matriz de Correlación de Pearson (Altitud Media, Precipitación Media, Temperatura Media)')
    plt.show()

    print('\nAnálisis de correlación adicional completado.')

