    map_id_dem_new = ee.Image(dem_quebrada_honda).getMapId(dem_vis)
    folium.TileLayer(
        tiles=map_id_dem_new['tile_fetcher'].url_format,
        attr='Google Earth Engine - DEM',
        overlay=True,
        name='DEM de Altitud',
        show=True # Hacerlo visible por defecto
    ).add_to(m_combined_all_new)

    # 2. Añadir la capa de Clases de Pendiente (Riesgos de Suelo)
    map_id_slope_risk_new = ee.Image(reclassified_slope_quebrada_honda).getMapId(slope_risk_vis)
    folium.TileLayer(
        tiles=map_id_slope_risk_new['tile_fetcher'].url_format,
        attr='Google Earth Engine - Clases de Pendiente (Riesgo de Suelo)',
        overlay=True,
        name='Clases de Riesgo de Suelo (Pendiente)',
        show=False # Inicialmente oculto
    ).add_to(m_combined_all_new)

    # 3. Añadir la capa de Precipitación Media
    map_id_prec_qh_new = ee.Image(precipitation_quebrada_honda_analysis).getMapId(precipitation_vis)
    folium.TileLayer(
        tiles=map_id_prec_qh_new['tile_fetcher'].url_format,
        attr='Google Earth Engine - Precipitación Media',
        overlay=True,
        name='Precipitación Media (mm)',
        show=False # Inicialmente oculto
    ).add_to(m_combined_all_new)

    # 4. Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_combined_all_new)

    # 5. Añadir control de capas
    m_combined_all_new.add_child(folium.LayerControl())

    display(m_combined_all_new)
    print('\nMapa interactivo combinado de DEM, clases de riesgo de suelo (pendientes) y precipitación completado.')

