import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

# Fusionar los DataFrames de altitud, precipitación y temperatura por 'sorder'
if 'altitude_summary_df' in locals() and altitude_summary_df is not None and \
   'precipitation_summary_df' in locals() and precipitation_summary_df is not None and \
   'temperature_summary_df' in locals() and temperature_summary_df is not None:

    # Unir altitud y precipitación
    combined_rivers_df = pd.merge(altitude_summary_df, precipitation_summary_df, on='sorder', how='outer')
    # Unir el resultado con temperatura
    combined_rivers_df = pd.merge(combined_rivers_df, temperature_summary_df, on='sorder', how='outer')

    print('DataFrame combinado de estadísticas de ríos:')
    display(combined_rivers_df.round(2))

    # Visualizar las relaciones (ej. Orden de corriente vs. Precipitación/Temperatura)
    plt.figure(figsize=(12, 6))

    plt.subplot(1, 2, 1) # Subplot para Precipitación
    sns.barplot(x='sorder', y='mean_precipitation', data=combined_rivers_df, palette='viridis', hue='sorder', legend=False)
    plt.title('Precipitación Media por Orden de Corriente')
    plt.xlabel('Orden de Corriente')
    plt.ylabel('Precipitación Media (mm)')
    plt.grid(axis='y', linestyle='--', alpha=0.7)

    plt.subplot(1, 2, 2) # Subplot para Temperatura
    sns.barplot(x='sorder', y='mean_temperature', data=combined_rivers_df, palette='coolwarm', hue='sorder', legend=False)
    plt.title('Temperatura Media por Orden de Corriente')
    plt.xlabel('Orden de Corriente')
    plt.ylabel('Temperatura Media (°C)')
    plt.grid(axis='y', linestyle='--', alpha=0.7)

    plt.tight_layout()
    plt.show()

    # También podemos visualizar la altitud vs precipitación/temperatura (si hay suficientes puntos)
    if len(combined_rivers_df) > 1:
        plt.figure(figsize=(10, 6))
        sns.scatterplot(x='mean_elevation', y='mean_precipitation', hue='sorder', size='sorder', data=combined_rivers_df, palette='viridis', sizes=(50, 400))
        plt.title('Precipitación Media vs. Altitud Media por Orden de Corriente')
        plt.xlabel('Altitud Media (m)')
        plt.ylabel('Precipitación Media (mm)')
        plt.grid(True, linestyle='--', alpha=0.7)
        plt.show()

        plt.figure(figsize=(10, 6))
        sns.scatterplot(x='mean_elevation', y='mean_temperature', hue='sorder', size='sorder', data=combined_rivers_df, palette='coolwarm', sizes=(50, 400))
        plt.title('Temperatura Media vs. Altitud Media por Orden de Corriente')
        plt.xlabel('Altitud Media (m)')
        plt.ylabel('Temperatura Media (°C)')
        plt.grid(True, linestyle='--', alpha=0.7)
        plt.show()

    print('''
Análisis y visualización de la correlación de la red hídrica con precipitación y temperatura completados.''')

else:
    print('Error: Uno o más DataFrames de resumen (altitud, precipitación o temperatura por orden de corriente) no están disponibles.')

