    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    # Crear un mapa Folium centrado en la cuenca
    m_rivers_re_display = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # Definir una paleta de colores para las órdenes de corriente
    # Se pueden ajustar los colores y el número de órdenes si hay más variedad en los datos
    # Ejemplo de paleta: del azul claro para órdenes bajas al azul oscuro para órdenes altas
    colors = ['#deebf7', '#c6dbef', '#9ecae1', '#6baed6', '#4292c6', '#2171b5', '#084594']

    # Crear un GeoJSON que combine todas las geometrías de ríos con sus propiedades
    # y aplicar la coloración basada en 'sorder'
    folium.GeoJson(
        rivers_gdf.to_json(),
        name='Red Hídrica por Orden de Corriente',
        style_function=lambda x: {
            'color': colors[x['properties']['sorder'] - 1] if x['properties']['sorder'] <= len(colors) else 'black',
            'weight': x['properties']['sorder'] * 0.75, # Ríos de orden superior más anchos
            'tooltip': f"Orden de Corriente: {x['properties']['sorder']}"
        },
        tooltip=folium.GeoJsonTooltip(fields=['sorder'], aliases=['Orden de Corriente:'], localize=True),
        popup=folium.GeoJsonPopup(fields=['sorder'], aliases=['Orden de Corriente:'], localize=True)
    ).add_to(m_rivers_re_display)

    # Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_rivers_re_display)

    # Añadir control de capas
    m_rivers_re_display.add_child(folium.LayerControl())

    display(m_rivers_re_display)
    print('\nVisualización de la red hídrica categorizada por orden de corriente completada.')

