import folium
import ee
import matplotlib.colors as mcolors
import matplotlib.pyplot as plt # Necesario para plt.colormaps.get_cmap

# Asegurarse de que `rivers_gdf`, `pomca_clipped_gdf`, `watershed_gdf`, `roi_quebrada_honda` estén definidos
if 'rivers_gdf' not in locals() or rivers_gdf is None:
    print('Error: El GeoDataFrame de ríos (`rivers_gdf`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
elif 'pomca_clipped_gdf' not in locals() or pomca_clipped_gdf is None:
    print('Error: El GeoDataFrame de POMCA (`pomca_clipped_gdf`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
elif 'watershed_gdf' not in locals() or watershed_gdf is None:
    print('Error: El GeoDataFrame de la cuenca (`watershed_gdf`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'category_column' not in locals() or category_column is None:
    print('Error: La variable `category_column` (para categorización del POMCA) no está definida. Asegúrate de ejecutar las celdas anteriores.')
else:
    # Paleta de colores para las órdenes de corriente (re-definida para robustez)
    colors_rivers = ['#deebf7', '#c6dbef', '#9ecae1', '#6baed6', '#4292c6', '#2171b5', '#084594']

    # Crear un mapa de colores para las categorías únicas del POMCA (re-creada para robustez)
    # Aseguramos que pomca_area_summary y unique_categories estén disponibles
    if 'pomca_area_summary' in locals() and pomca_area_summary is not None and \
       'unique_categories' in locals() and unique_categories is not None:
        cmap_pomca = plt.colormaps.get_cmap('tab20').resampled(len(unique_categories))
        colors_map_pomca = {cat: mcolors.to_hex(cmap_pomca(i)) for i, cat in enumerate(unique_categories)}
    else:
        # Fallback si no se encuentran las variables, usar un color simple
        colors_map_pomca = {pomca_clipped_gdf[category_column].iloc[0]: '#808080'}

    # Obtener el centroide de la cuenca para centrar el mapa (reutilizamos centroid_quebrada_honda)
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    # Crear un mapa Folium base
    m_rivers_pomca = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # 1. Añadir la capa de Zonificación Ambiental del POMCA
    # Convertir el GeoDataFrame de POMCA a WGS84 para visualización en Folium
    pomca_clipped_gdf_wgs84 = pomca_clipped_gdf.to_crs(epsg=4326)

    folium.GeoJson(
        pomca_clipped_gdf_wgs84.to_json(),
        name=f'Zonificación Ambiental POMCA ({category_column})',
        style_function=lambda x: {
            'fillColor': colors_map_pomca.get(x['properties'].get(category_column), '#808080'), # Gris por defecto
            'color': 'black',
            'weight': 1,
            'fillOpacity': 0.6
        },
        tooltip=folium.GeoJsonTooltip(fields=[category_column], aliases=[f'{category_column}:'], localize=True)
    ).add_to(m_rivers_pomca)

    # 2. Añadir la capa de Red Hídrica por Orden de Corriente
    folium.GeoJson(
        rivers_gdf.to_json(),
        name='Red Hídrica por Orden de Corriente',
        style_function=lambda x: {
            'color': colors_rivers[x['properties']['sorder'] - 1] if x['properties']['sorder'] <= len(colors_rivers) else 'black',
            'weight': x['properties']['sorder'] * 0.75,
            'tooltip': f"Orden de Corriente: {x['properties']['sorder']}"
        },
        tooltip=folium.GeoJsonTooltip(fields=['sorder'], aliases=['Orden de Corriente:'], localize=True),
        popup=folium.GeoJsonPopup(fields=['sorder'], aliases=['Orden de Corriente:'], localize=True)
    ).add_to(m_rivers_pomca)

    # 3. Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'red', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_rivers_pomca)

    # 4. Añadir control de capas
    m_rivers_pomca.add_child(folium.LayerControl())

    display(m_rivers_pomca)
    print('\nMapa interactivo combinado de red hídrica y zonificación ambiental POMCA completado.')

