"""### Resumen del Análisis de la Red Hídrica Categorizada y su Relación con el Entorno

Como se mostró en la visualización anterior y se detalló en los análisis previos, la red hídrica de la cuenca 'Quebrada la Honda' ha sido categorizada exitosamente por su orden de corriente. Se obtuvieron las siguientes estadísticas y relaciones clave:

*   **Estadísticas por Orden de Corriente:** Se calcularon y tabularon las estadísticas de altitud (media, mínima, máxima), precipitación media y temperatura media para cada orden de corriente presente en la cuenca. Esto reveló que la cuenca 'Quebrada la Honda' contiene principalmente ríos de **orden 1**, con una **altitud media de 1158.92m**, una **precipitación media de 3.95mm** y una **temperatura media de 19.14°C** para esta categoría.

*   **Correlaciones Clave:**
    *   Existe una **correlación positiva** entre la **altitud media y la precipitación media** en los ríos, lo que sugiere que las zonas más elevadas tienden a recibir mayores precipitaciones.
    *   Se observa una **correlación negativa** entre la **altitud media y la temperatura media**, indicando que las áreas de mayor altitud presentan temperaturas más bajas, un patrón geográfico esperado.

Estos resultados proporcionan una comprensión integral de la interconexión entre la red hídrica, la topografía y las condiciones climáticas dentro de la cuenca 'Quebrada la Honda'.

### Regeneración de DataFrames Faltantes para el Resumen

Las siguientes celdas se ejecutan para asegurar que todos los DataFrames necesarios para el resumen final estén disponibles. Esto incluye la frecuencia de píxeles por clase de altitud y pendiente, la precipitación y temperatura media por clase de altitud, y las estadísticas ambientales por orden de corriente de la red hídrica.
"""

import numpy as np
import pandas as pd

# Asegurarse de que `reclassified_dem` esté disponible y no esté vacío
if 'reclassified_dem' in locals() and reclassified_dem is not None and reclassified_dem.size > 0:
    # Obtener los valores únicos (clases) y sus conteos (frecuencia)
    unique_classes, counts = np.unique(reclassified_dem, return_counts=True)

    # Crear un DataFrame para una mejor visualización
    frequency_df = pd.DataFrame({
        'Clase de Altitud': unique_classes,
        'Número de Píxeles': counts
    })

    # Calcular el porcentaje de píxeles
    total_pixels = reclassified_dem.size
    frequency_df['Porcentaje (%)'] = (frequency_df['Número de Píxeles'] / total_pixels * 100).round(2)

    print("Frecuencia de píxeles por clase de altitud:")
    display(frequency_df)

else:
    print("Error: La variable 'reclassified_dem' no está disponible o está vacía. Asegúrate de que la celda de reclasificación se haya ejecutado exitosamente.")


# Asegurarse de que 'reclassified_dem', 'watershed_area_sq_m' y 'frequency_df' estén disponibles
if 'reclassified_dem' in locals() and reclassified_dem is not None and reclassified_dem.size > 0 and \
   'watershed_area_sq_m' in locals() and watershed_area_sq_m is not None and \
   'frequency_df' in locals() and frequency_df is not None:

    # Calcular el área de un solo píxel en metros cuadrados
    total_pixels_in_reclassified_dem = reclassified_dem.size
    pixel_area_sq_m = watershed_area_sq_m / total_pixels_in_reclassified_dem

    # Calcular el área por clase en metros cuadrados y luego en hectáreas
    frequency_df['Área (m²)'] = frequency_df['Número de Píxeles'] * pixel_area_sq_m
    frequency_df['Área (ha)'] = frequency_df['Área (m²)'] / 10000  # 1 hectárea = 10,000 m²

    print("Área total en hectáreas por clase de altitud:")
    display(frequency_df.round(2))

else:
    print("Error: Faltan variables necesarias ('reclassified_dem', 'watershed_area_sq_m' o 'frequency_df'). Asegúrate de haber ejecutado las celdas previas correctamente.")


# Asegúrate de que 'frequency_df' esté disponible y contenga la columna 'Porcentaje (%)'
if 'frequency_df' in locals() and frequency_df is not None and 'Porcentaje (%)' in frequency_df.columns:
    # Ordenar por 'Clase de Altitud' para asegurar que el acumulado sea correcto
    frequency_df_sorted = frequency_df.sort_values(by='Clase de Altitud').reset_index(drop=True)

    # Calcular el porcentaje acumulado
    frequency_df_sorted['Porcentaje Acumulado (%)'] = frequency_df_sorted['Porcentaje (%)'].cumsum().round(2)

    print("Porcentaje acumulado de área por clase de altitud:")
    display(frequency_df_sorted)
else:
    print("Error: La variable 'frequency_df' no está disponible o no contiene la columna 'Porcentaje (%)'. Asegúrate de que las celdas previas se hayan ejecutado correctamente.")

import ee
import pandas as pd

if 'reclassified_slope_quebrada_honda' in locals() and reclassified_slope_quebrada_honda is not None and roi_quebrada_honda is not None:
    # Definir el reducer para obtener el histograma de las clases
    reducer_hist_qh = ee.Reducer.frequencyHistogram()

    # Reducir la región para obtener el histograma (usando la geometría de la cuenca)
    slope_class_counts_qh = reclassified_slope_quebrada_honda.reduceRegion(**{
        'reducer': reducer_hist_qh,
        'geometry': roi_quebrada_honda,
        'scale': 10, # Usar una escala más fina (10m) para mayor precisión dentro de la cuenca pequeña
        'maxPixels': 1e13,
        'bestEffort': True
    })

    histogram_data_qh = slope_class_counts_qh.getInfo().get('slope_class')

    if histogram_data_qh:
        frequency_df_slope_qh = pd.DataFrame(histogram_data_qh.items(), columns=['Clase de Pendiente', 'Número de Píxeles'])
        frequency_df_slope_qh['Clase de Pendiente'] = frequency_df_slope_qh['Clase de Pendiente'].astype(int)
        frequency_df_slope_qh = frequency_df_slope_qh.sort_values(by='Clase de Pendiente').reset_index(drop=True)

        total_pixels_slope_qh = frequency_df_slope_qh['Número de Píxeles'].sum()
        frequency_df_slope_qh['Porcentaje (%)'] = (frequency_df_slope_qh['Número de Píxeles'] / total_pixels_slope_qh * 100).round(2)

        # Calcular el área en m² y ha usando la misma lógica que para Colombia
        total_image_area_sq_m_qh = reclassified_slope_quebrada_honda.pixelArea().reduceRegion(**{
            'reducer': ee.Reducer.sum(),
            'geometry': roi_quebrada_honda,
            'scale': 10, # Misma escala
            'maxPixels': 1e13,
            'bestEffort': True
        }).getInfo().get('area')

        if total_image_area_sq_m_qh is None:
            print("Error: No se pudo calcular el área total de la imagen reclasificada para Quebrada la Honda.")
        else:
            pixel_area_sq_m_qh = total_image_area_sq_m_qh / total_pixels_slope_qh
            frequency_df_slope_qh['Área (m²)'] = frequency_df_slope_qh['Número de Píxeles'] * pixel_area_sq_m_qh
            frequency_df_slope_qh['Área (ha)'] = frequency_df_slope_qh['Área (m²)'] / 10000

            print("Frecuencia y Área por clase de pendiente para Quebrada la Honda:")
            display(frequency_df_slope_qh.round(2))
    else:
        print("No se pudieron calcular las frecuencias de píxeles para las clases de pendiente en Quebrada la Honda.")
else:
    print('Error: Variables necesarias (reclassified_slope_quebrada_honda o roi_quebrada_honda) no están definidas.')


