import pandas as pd
import numpy as np

# Asegurarse de que los DataFrames estén disponibles
if 'precipitation_altitude_df' not in locals() or precipitation_altitude_df is None or \
   'temperature_altitude_df' not in locals() or temperature_altitude_df is None:
    print('Error: DataFrames necesarios para el cálculo de correlación no están disponibles.')
else:
    # 1. Fusionar los DataFrames de precipitación y temperatura por clase de altitud
    # Usamos merge para combinar los dos DataFrames en 'Clase de Altitud'
    combined_df = pd.merge(precipitation_altitude_df, temperature_altitude_df, on='Clase de Altitud', how='inner')

    # 2. Añadir una columna de altitud representativa para cada clase
    # Usaremos los puntos medios de los rangos de altitud definidos previamente.
    # El mapa 'altitude_map' está disponible en el kernel si se definió.
    # Si no, lo definimos aquí para robustez.
    altitude_map_for_correlation = {
        1: 250.0,   # (0, 500) -> 250
        2: 750.0,   # (500, 1000) -> 750
        3: 1250.0,  # (1000, 1500) -> 1250
        4: 1750.0,  # (1500, 2000) -> 1750
        5: 2450.5   # (2000, np.inf) -> Se usa un valor representativo basado en el DEM máximo
    }

    combined_df['Altitud Representativa (m)'] = combined_df['Clase de Altitud'].map(altitude_map_for_correlation)

    print('DataFrame combinado con altitud representativa:')
    display(combined_df)

    # 3. Calcular la matriz de correlación de Pearson
    # Seleccionamos las columnas de interés para la correlación
    correlation_matrix = combined_df[['Altitud Representativa (m)', 'Temperatura Media (°C)', 'Precipitación Media (mm)']].corr(method='pearson')

    print('\nMatriz de Correlación de Pearson:')
    display(correlation_matrix.round(2))

import ee
import pandas as pd

# Asegurarse de que `rivers_gdf`, `dem_quebrada_honda` y `roi_quebrada_honda` estén definidos
if 'rivers_gdf' not in locals() or rivers_gdf is None:
    print('Error: El GeoDataFrame de ríos (`rivers_gdf`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
elif 'dem_quebrada_honda' not in locals() or dem_quebrada_honda is None:
    print('Error: La imagen DEM recortada para Quebrada la Honda (`dem_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
else:
    # Convertir rivers_gdf a ee.FeatureCollection
    # Solo necesitamos las geometrías de los ríos y su atributo 'sorder'
    ee_rivers = ee.FeatureCollection(rivers_gdf.__geo_interface__)

    # Aplicar reduceRegions a cada Feature de río para obtener estadísticas de altitud
    # Aseguramos que la banda del DEM se llame 'elevation' o similar para identificarla
    dem_quebrada_honda_renamed = dem_quebrada_honda.rename('elevation')

    # Calcular estadísticas de altitud para cada río
    river_altitude_stats = dem_quebrada_honda_renamed.reduceRegions(**{
        'collection': ee_rivers,
        'reducer': ee.Reducer.mean().combine(ee.Reducer.min(), '', True).combine(ee.Reducer.max(), '', True),
        'scale': 10, # Escala de muestreo para el cálculo (ej. 10m)
        'crs': dem_quebrada_honda_renamed.projection().crs() # Usar el CRS del DEM
    })

    # Convertir los resultados a una lista de diccionarios de Python
    altitude_data = []
    for feature in river_altitude_stats.getInfo()['features']:
        properties = feature['properties']
        altitude_data.append({
            'sorder': properties['sorder'],
            'mean_elevation': properties['mean'],
            'min_elevation': properties['min'],
            'max_elevation': properties['max']
        })

    altitude_by_sorder_df = pd.DataFrame(altitude_data)

    # Agrupar por 'sorder' y calcular la media de las estadísticas (si un sorder tiene múltiples geometrías)
    altitude_summary_df = altitude_by_sorder_df.groupby('sorder').agg({
        'mean_elevation': 'mean',
        'min_elevation': 'min',
        'max_elevation': 'max'
    }).reset_index()

    print('Estadísticas de Altitud por Orden de Corriente en Quebrada la Honda:')
    display(altitude_summary_df.round(2))

