"""### Corrección y Recálculo del Área de las Zonas de Vida de Holdridge

El porcentaje incorrecto para la zona 'bh-A' en el resumen anterior se debe a que el método `filterBounds()` de Earth Engine únicamente filtra las geometrías que se superponen con la cuenca, pero no las recorta a su extensión precisa dentro de ella. Para obtener las áreas correctas, es fundamental realizar una operación de intersección explícita de cada zona de vida con la geometría de la cuenca.

A continuación, se recalculará el área de las zonas de vida de Holdridge dentro de la cuenca 'Quebrada la Honda' utilizando la función `intersection()` para asegurar que solo se considere el área que realmente cae dentro de los límites de la cuenca. Luego, se presentará el resumen de áreas y porcentajes corregidos.
"""

import ee
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

# Asegurarse de que `ee_holdridge_zones` y `roi_quebrada_honda` estén definidos
if 'ee_holdridge_zones' not in locals() or ee_holdridge_zones is None:
    print('Error: La FeatureCollection de zonas de vida de Holdridge (`ee_holdridge_zones`) no está definida. Asegúrate de ejecutar las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca (`roi_quebrada_honda`) no está definida. Asegúrate de ejecutar las celdas anteriores.')
elif 'watershed_area_sq_m' not in locals() or watershed_area_sq_m is None:
    print('Error: La variable `watershed_area_sq_m` no está definida. Por favor, asegúrate de que la celda que calcula el área proyectada de la cuenca haya sido ejecutada.')
else:
    # Función para intersectar cada zona de vida con la cuenca y calcular su área
    def clip_and_calculate_area(feature):
        clipped_feature = feature.intersection(roi_quebrada_honda, ee.ErrorMargin(1)) # Usar ErrorMargin para evitar problemas de topología
        return clipped_feature.set({'area_sq_m': clipped_feature.area()})

    # Aplicar la función a la colección de zonas de vida
    # Primero, filtramos para reducir el número de features a procesar, aunque luego se intersecta.
    # Es importante que el resultado de intersection sea una Feature válida.
    holdridge_zones_quebrada_honda_clipped = ee_holdridge_zones.filterBounds(roi_quebrada_honda).map(clip_and_calculate_area)

    # Convertir la FeatureCollection a una lista de diccionarios Python para Pandas
    holdridge_list_clipped = holdridge_zones_quebrada_honda_clipped.getInfo()['features']

    data_clipped = []
    for f in holdridge_list_clipped:
        properties = f['properties']
        # Asegurarse de que 'ZV_Holdrid' y 'area_sq_m' existan y 'area_sq_m' sea > 0
        if 'ZV_Holdrid' in properties and 'area_sq_m' in properties and properties['area_sq_m'] > 0:
            data_clipped.append({
                'ZV_Holdrid': properties['ZV_Holdrid'],
                'area_sq_m': properties['area_sq_m']
            })

    holdridge_area_df_corrected = pd.DataFrame(data_clipped)

    if not holdridge_area_df_corrected.empty:
        # 3. Agrupar por zona de vida y sumar las áreas
        holdridge_area_summary_corrected = holdridge_area_df_corrected.groupby('ZV_Holdrid')['area_sq_m'].sum().reset_index()

        # Convertir a hectáreas
        holdridge_area_summary_corrected['area_ha'] = holdridge_area_summary_corrected['area_sq_m'] / 10000

        # 4. Calcular el área total de la cuenca en hectáreas (reutilizamos watershed_area_sq_m)
        watershed_total_area_ha = watershed_area_sq_m / 10000

        # 5. Calcular el porcentaje del área total de la cuenca
        holdridge_area_summary_corrected['percentage'] = (holdridge_area_summary_corrected['area_ha'] / watershed_total_area_ha * 100).round(2)

        print('Distribución de Área por Zonas de Vida de Holdridge en Quebrada la Honda (CORREGIDA):')
        display(holdridge_area_summary_corrected.round(2))

        # 6. Visualizar la distribución
        plt.figure(figsize=(12, 7))
        sns.barplot(x='ZV_Holdrid', y='area_ha', data=holdridge_area_summary_corrected, palette='viridis', hue='ZV_Holdrid', legend=False)
        plt.title('Área por Zona de Vida de Holdridge en la Cuenca Quebrada la Honda (CORREGIDA)')
        plt.xlabel('Zona de Vida de Holdridge')
        plt.ylabel('Área (hectáreas)')
        plt.xticks(rotation=45, ha='right')
        plt.grid(axis='y', linestyle='--', alpha=0.7)
        plt.tight_layout()
        plt.show()

        print('Visualización de la distribución de áreas por zona de vida completada (CORREGIDA).')
    else:
        print('No se encontraron zonas de vida de Holdridge válidas después de la intersección con la cuenca.')

