    # Crear un mapa Folium base
    m_final_holdridge = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # Añadir la capa del DEM como base
    map_id_dem = ee.Image(dem_quebrada_honda).getMapId(dem_vis)
    folium.TileLayer(
        tiles=map_id_dem['tile_fetcher'].url_format,
        attr='Google Earth Engine - DEM',
        overlay=True,
        name='DEM de Altitud'
    ).add_to(m_final_holdridge)

    # Preparar los datos de las zonas de vida para la visualización con la información corregida
    holdridge_info_clipped = holdridge_zones_quebrada_honda_clipped.getInfo()
    if holdridge_info_clipped and holdridge_info_clipped['features']:
        # Crear un mapa de colores para las Zonas de Vida basado en 'ZV_Holdrid'
        unique_zones = sorted(list(set([f['properties'].get('ZV_Holdrid') for f in holdridge_info_clipped['features'] if f['properties'].get('ZV_Holdrid') is not None])))
        num_unique_zones = len(unique_zones)

        if num_unique_zones > 0:
            cmap = plt.colormaps.get_cmap('tab20').resampled(num_unique_zones) # 'tab20' es bueno para hasta 20 clases
            colors_holdridge_map = {zone: mcolors.to_hex(cmap(i)) for i, zone in enumerate(unique_zones)}
        else:
            colors_holdridge_map = {}

        # Unir los datos corregidos de área y porcentaje al GeoJSON para los tooltips
        features_with_corrected_data = []
        for feature in holdridge_info_clipped['features']:
            zone_name = feature['properties'].get('ZV_Holdrid')
            if zone_name and zone_name in holdridge_area_summary_corrected['ZV_Holdrid'].values:
                corrected_data = holdridge_area_summary_corrected[holdridge_area_summary_corrected['ZV_Holdrid'] == zone_name].iloc[0]
                feature['properties']['corrected_area_ha'] = f"{corrected_data['area_ha']:.2f}"
                feature['properties']['corrected_percentage'] = f"{corrected_data['percentage']:.2f}"
            features_with_corrected_data.append(feature)

        folium.GeoJson(
            {'type': 'FeatureCollection', 'features': features_with_corrected_data},
            name='Zonas de Vida de Holdridge (Corregidas)',
            style_function=lambda x: {
                'fillColor': colors_holdridge_map.get(x['properties'].get('ZV_Holdrid'), '#808080'), # Gris por defecto si no se encuentra
                'color': 'black',
                'weight': 1,
                'fillOpacity': 0.7
            },
            tooltip=folium.GeoJsonTooltip(fields=['ZV_Holdrid', 'corrected_area_ha', 'corrected_percentage'], aliases=['Zona de Vida:', 'Área (ha):', 'Porcentaje (%):'])
        ).add_to(m_final_holdridge)

        # Crear leyenda dinámica
        legend_html =   '''
                        <div style="position: fixed;
                                    bottom: 50px; left: 50px; width: 200px; height: auto;
                                    border:2px solid grey; z-index:9999; font-size:14px;
                                    background-color:white; opacity:0.9; padding:10px;">
                          <h4 style="margin-top:0;">Zonas de Vida Holdridge</h4>
                          <ul style="list-style:none; padding:0;">
                        '''
        for zone, color in colors_holdridge_map.items():
            legend_html += f'''
                                <li style="display:flex; align-items:center; margin-bottom:5px;">
                                  <span style="background:{color}; width:20px; height:15px; display:inline-block; margin-right:5px; border:1px solid black;"></span>
                                  <span>{zone}</span>
                                </li>
                            '''
        legend_html +=  '''
                          </ul>
                        </div>
                        '''

        m_final_holdridge.get_root().html.add_child(folium.Element(legend_html))

    # Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'red', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_final_holdridge)

    # Añadir control de capas
    m_final_holdridge.add_child(folium.LayerControl())

    display(m_final_holdridge)
    print('\nMapa interactivo final de Zonas de Vida de Holdridge (corregidas) sobre el DEM completado.')

