"""### Carga y Visualización de la Zonificación Ambiental del POMCA Río Bogotá

Ahora, vamos a cargar el archivo `Zonificación_Ambiental_POMCA_Río_Bogotá` que has proporcionado. Este archivo contiene información sobre la zonificación ambiental, la cual es crucial para entender las restricciones y usos del suelo en la cuenca. Lo descomprimiremos, cargaremos en un GeoDataFrame, lo recortaremos a la extensión de la cuenca 'Quebrada la Honda' y lo superpondremos en el DEM.
"""

import zipfile
import os
import geopandas as gpd

# Ruta al archivo zip de zonificación ambiental
zip_file_path_pomca = '/content/xn--Zonificacin_Ambiental_POMCA_Ro_Bogot_-_2120_ao_2019-shp-iqe09dzh0c.zip'
unzip_dir_pomca = '/content/pomca_extracted'

# Crear el directorio si no existe
os.makedirs(unzip_dir_pomca, exist_ok=True)

# Descomprimir el archivo
with zipfile.ZipFile(zip_file_path_pomca, 'r') as zip_ref:
    zip_ref.extractall(unzip_dir_pomca)

print(f"Archivo '{zip_file_path_pomca}' descomprimido en '{unzip_dir_pomca}'.")

# Listar el contenido del directorio descomprimido para encontrar el .shp
print("\nContenido del directorio descomprimido de POMCA:")
shp_file_pomca = None
for root, dirs, files in os.walk(unzip_dir_pomca):
    for file in files:
        if file.endswith('.shp'):
            shp_file_pomca = os.path.join(root, file)
            print(shp_file_pomca)
            break
    if shp_file_pomca:
        break

if shp_file_pomca:
    # Cargar el Shapefile en un GeoDataFrame
    try:
        pomca_gdf = gpd.read_file(shp_file_pomca)
        print('\nShapefile de Zonificación Ambiental POMCA cargado exitosamente en un GeoDataFrame:')
        display(pomca_gdf.head())
        print(f'Sistema de Coordenadas (CRS): {pomca_gdf.crs}')
        print(f'Número de geometrías: {len(pomca_gdf)}')
    except Exception as e:
        print(f'Error al cargar el Shapefile de POMCA: {e}')
else:
    print(f'Error: No se encontró ningún archivo .shp en el directorio {unzip_dir_pomca}.')

"""### Reproyección y Recorte de la Zonificación Ambiental a la Cuenca

Ahora, reproyectaremos la zonificación ambiental del POMCA al CRS de la cuenca (`EPSG:3116`) y la recortaremos a la extensión de `roi_quebrada_honda`. Esto nos permitirá visualizar solo las áreas relevantes dentro de nuestra cuenca de interés.
"""

import ee
import folium

# Asegurarse de que `pomca_gdf`, `watershed_gdf` y `roi_quebrada_honda` estén definidos
if 'pomca_gdf' not in locals() or pomca_gdf is None:
    print('Error: El GeoDataFrame de POMCA (`pomca_gdf`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
elif 'watershed_gdf' not in locals() or watershed_gdf is None:
    print('Error: El GeoDataFrame de la cuenca (`watershed_gdf`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'dem_quebrada_honda' not in locals() or dem_quebrada_honda is None:
    print('Error: La imagen DEM recortada para Quebrada la Honda (`dem_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
else:
    # Reproyectar `pomca_gdf` al CRS de la cuenca (`watershed_gdf`) para operaciones espaciales
    pomca_gdf_reprojected = pomca_gdf.to_crs(watershed_gdf.crs)

    # Recortar la zonificación ambiental a la geometría de la cuenca 'Quebrada la Honda'
    # Usamos la primera geometría del watershed_gdf para el recorte
    pomca_clipped_gdf = gpd.clip(pomca_gdf_reprojected, watershed_gdf.geometry.iloc[0])

    print('\nZonificación Ambiental POMCA recortada a la cuenca Quebrada la Honda:')
    if not pomca_clipped_gdf.empty:
        display(pomca_clipped_gdf.head())
        print(f'Número de geometrías recortadas: {len(pomca_clipped_gdf)}')
    else:
        print('No se encontró ninguna geometría de zonificación ambiental dentro de la cuenca.')

    # Convertir el GeoDataFrame recortado a ee.FeatureCollection para visualización en Earth Engine si se requiere, o directamente con Folium
    # Para este caso, lo usaremos directamente con Folium, pero lo convertimos a WGS84 para compatibilidad con el mapa base.
    pomca_clipped_gdf_wgs84 = pomca_clipped_gdf.to_crs(epsg=4326)

    # Parámetros de visualización para el DEM (reutilizamos los definidos anteriormente)
    dem_vis = {
        'min': 0,        # Altitud mínima
        'max': 3000,     # Altitud máxima (ajustar según el rango real de tu DEM)
        'palette': ['#000000', '#555555', '#AAAAAA', '#FFFFFF'] # Escala de grises para el DEM
    }

    # Obtener el centroide de la cuenca para centrar el mapa
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    # Crear un mapa Folium base
    m_pomca_dem = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # Añadir la capa del DEM como base
    map_id_dem = ee.Image(dem_quebrada_honda).getMapId(dem_vis)
    folium.TileLayer(
        tiles=map_id_dem['tile_fetcher'].url_format,
        attr='Google Earth Engine - DEM',
        overlay=True,
        name='DEM de Altitud'
    ).add_to(m_pomca_dem)

    # Añadir la zonificación ambiental recortada al mapa
    if not pomca_clipped_gdf_wgs84.empty:
        # Necesitamos un esquema de color para las zonas. Si hay una columna de clasificación, la usamos.
        # Asumiendo que 'CATEGORY' o similar es el nombre de la columna de zonificación
        # Si no hay una columna obvia, podemos usar un color simple o generar uno basado en algún atributo.

        # Intentar identificar una columna con categorías para la zonificación
        category_col = None
        for col in ['CATEGORIA', 'CATEGORY', 'zona', 'nombre_zona']:
            if col in pomca_clipped_gdf_wgs84.columns:
                category_col = col
                break

        if category_col:
            unique_categories = pomca_clipped_gdf_wgs84[category_col].unique()
            import matplotlib.pyplot as plt
            import matplotlib.colors as mcolors

            # Generar una paleta de colores para las categorías únicas
            cmap = plt.colormaps.get_cmap('tab20').resampled(len(unique_categories))
            colors_map = {cat: mcolors.to_hex(cmap(i)) for i, cat in enumerate(unique_categories)}

            folium.GeoJson(
                pomca_clipped_gdf_wgs84.to_json(),
                name='Zonificación Ambiental POMCA',
                style_function=lambda x: {
                    'fillColor': colors_map.get(x['properties'].get(category_col), '#808080'), # Gris por defecto
                    'color': 'black',
                    'weight': 1,
                    'fillOpacity': 0.6
                },
                tooltip=folium.GeoJsonTooltip(fields=[category_col], aliases=['Categoría:'], localize=True)
            ).add_to(m_pomca_dem)
            print(f"Visualizando Zonificación Ambiental por la columna '{category_col}'.")
        else:
            # Si no se encuentra una columna de categoría, usar un color simple
            folium.GeoJson(
                pomca_clipped_gdf_wgs84.to_json(),
                name='Zonificación Ambiental POMCA',
                style_function=lambda x: {
                    'fillColor': '#8c564b', # Color por defecto
                    'color': 'black',
                    'weight': 1,
                    'fillOpacity': 0.6
                },
                tooltip=folium.GeoJsonTooltip(fields=pomca_clipped_gdf_wgs84.columns.drop('geometry').tolist(), aliases=[col.replace('_', ' ').title() + ':' for col in pomca_clipped_gdf_wgs84.columns.drop('geometry').tolist()], localize=True)
            ).add_to(m_pomca_dem)
            print('Visualizando Zonificación Ambiental con un color único (no se encontró columna de categoría).')


    # Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'red', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_pomca_dem)

    # Añadir control de capas
    m_pomca_dem.add_child(folium.LayerControl())

    display(m_pomca_dem)
    print('\nMapa interactivo de Zonificación Ambiental POMCA sobre el DEM completado.')

