"""### Análisis y Visualización Detallada de la Zonificación Ambiental del POMCA

Vamos a realizar un análisis de las áreas de cada categoría de la zonificación ambiental dentro de la cuenca 'Quebrada la Honda' y mejoraremos la visualización en el mapa, asignando un color distinto a cada tipo de zona e incluyendo una leyenda.
"""

import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.colors as mcolors
import folium

# Asegurarse de que `pomca_clipped_gdf` y `watershed_area_sq_m` estén definidos
if 'pomca_clipped_gdf' not in locals() or pomca_clipped_gdf is None:
    print('Error: El GeoDataFrame recortado de POMCA (`pomca_clipped_gdf`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
elif 'watershed_area_sq_m' not in locals() or watershed_area_sq_m is None:
    print('Error: La variable `watershed_area_sq_m` (área total de la cuenca) no está definida. Por favor, asegúrate de que la celda de cálculo de área de la cuenca haya sido ejecutada.')
else:
    # Identificar la columna de categorización (basado en el head() anterior, 'NOMENCLAT' o 'CAT_ORD' parecen buenos candidatos)
    category_column = None
    potential_columns = ['NOMENCLAT', 'CAT_ORD', 'ZO_US_MA', 'SZO_US_M', 'DESCRIP']
    for col in potential_columns:
        if col in pomca_clipped_gdf.columns and not pomca_clipped_gdf[col].isnull().all():
            category_column = col
            break

    if category_column is None:
        print('Advertencia: No se encontró una columna adecuada para categorizar las zonas ambientales. Se usará un color único.')
        # Si no se encuentra una columna de categoría, asignar un nombre genérico para el cálculo
        pomca_clipped_gdf['Categoría_Zonificacion'] = 'Zona Ambiental'
        category_column = 'Categoría_Zonificacion'

    # REPROYECTAR a un CRS proyectado (e.g., EPSG:3116) antes de calcular el área para obtener resultados correctos
    pomca_clipped_gdf_projected = pomca_clipped_gdf.to_crs(epsg=3116)

    # Calcular el área de cada geometría en el GeoDataFrame recortado y proyectado
    pomca_clipped_gdf_projected['area_sq_m'] = pomca_clipped_gdf_projected.geometry.area
    pomca_clipped_gdf_projected['area_ha'] = pomca_clipped_gdf_projected['area_sq_m'] / 10000 # Convertir a hectáreas

    # Agrupar por la columna de categoría y sumar las áreas
    pomca_area_summary = pomca_clipped_gdf_projected.groupby(category_column)['area_ha'].sum().reset_index()

    # Calcular el porcentaje del área total de la cuenca
    watershed_total_area_ha = watershed_area_sq_m / 10000
    pomca_area_summary['percentage'] = (pomca_area_summary['area_ha'] / watershed_total_area_ha * 100).round(2)

    print('Distribución de Área por Zonas Ambientales del POMCA en Quebrada la Honda:')
    display(pomca_area_summary.round(2))

    # Visualizar la distribución en un gráfico de barras
    plt.figure(figsize=(14, 8))
    # 'hue' se establece igual a 'x' para que cada barra tenga un color distinto según la categoría
    # 'legend=False' para evitar la leyenda duplicada ya que la leyenda se creará dinámicamente en el mapa
    sns.barplot(x=category_column, y='area_ha', data=pomca_area_summary, palette='tab20', hue=category_column, legend=False)
    plt.title('Área por Zona Ambiental del POMCA en la Cuenca Quebrada la Honda')
    plt.xlabel('Zona Ambiental')
    plt.ylabel('Área (hectáreas)')
    plt.xticks(rotation=45, ha='right')
    plt.grid(axis='y', linestyle='--', alpha=0.7)
    plt.tight_layout()
    plt.show()

    print('Visualización de la distribución de áreas por zona ambiental completada.')

    # --- Generar el mapa actualizado con colores por categoría y leyenda ---

    # Obtener el centroide de la cuenca para centrar el mapa (reutilizamos centroid_quebrada_honda)
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    # Crear un mapa Folium base
    m_pomca_final = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # Añadir la capa del DEM como base
    dem_vis = {
        'min': 0,        # Altitud mínima
        'max': 3000,     # Altitud máxima (ajustar según el rango real de tu DEM)
        'palette': ['#000000', '#555555', '#AAAAAA', '#FFFFFF'] # Escala de grises para el DEM
    }
    map_id_dem = ee.Image(dem_quebrada_honda).getMapId(dem_vis)
    folium.TileLayer(
        tiles=map_id_dem['tile_fetcher'].url_format,
        attr='Google Earth Engine - DEM',
        overlay=True,
        name='DEM de Altitud'
    ).add_to(m_pomca_final)

    # Crear un mapa de colores para las categorías únicas
    unique_categories = pomca_area_summary[category_column].unique()
    cmap = plt.colormaps.get_cmap('tab20').resampled(len(unique_categories))
    colors_map_pomca = {cat: mcolors.to_hex(cmap(i)) for i, cat in enumerate(unique_categories)}

    # Unir los datos de resumen de área y porcentaje al GeoDataFrame proyectado
    # Esto es crucial para que el tooltip pueda acceder a 'percentage'
    pomca_clipped_gdf_projected = pd.merge(
        pomca_clipped_gdf_projected,
        pomca_area_summary[[category_column, 'percentage']],
        on=category_column,
        how='left'
    )

    # Añadir la zonificación ambiental recortada y coloreada al mapa
    # Convertir el GeoDataFrame proyectado de nuevo a WGS84 para visualización en Folium
    folium.GeoJson(
        pomca_clipped_gdf_projected.to_crs(epsg=4326).to_json(),
        name=f'Zonificación Ambiental POMCA ({category_column})',
        style_function=lambda x: {
            'fillColor': colors_map_pomca.get(x['properties'].get(category_column), '#808080'), # Gris por defecto
            'color': 'black',
            'weight': 1,
            'fillOpacity': 0.6
        },
        tooltip=folium.GeoJsonTooltip(fields=[category_column, 'area_ha', 'percentage'], aliases=[f'{category_column}:', 'Área (ha):', 'Porcentaje (%):'], localize=True)
    ).add_to(m_pomca_final)

    # Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'red', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_pomca_final)

    # Añadir control de capas
    m_pomca_final.add_child(folium.LayerControl())

    # Añadir leyenda dinámica si hay categorías para mostrar
    if unique_categories.size > 1 or (unique_categories.size == 1 and unique_categories[0] != 'Zona Ambiental'):
        legend_html =   '''
                        <div style="position: fixed;
                                    bottom: 50px; left: 50px; width: 200px; height: auto;
                                    border:2px solid grey; z-index:9999; font-size:14px;
                                    background-color:white; opacity:0.9; padding:10px;">
                          <h4 style="margin-top:0;">Zonas Ambientales</h4>
                          <ul style="list-style:none; padding:0;">
                        '''
        for zone, color in colors_map_pomca.items():
            legend_html += f'''
                                <li style="display:flex; align-items:center; margin-bottom:5px;">
                                  <span style="background:{color}; width:20px; height:15px; display:inline-block; margin-right:5px; border:1px solid black;"></span>
                                  <span>{zone}</span>
                                </li>
                            '''
        legend_html +=  '''
                          </ul>
                        </div>
                        '''
        m_pomca_final.get_root().html.add_child(folium.Element(legend_html))

    print('Mapa interactivo final de Zonificación Ambiental POMCA sobre el DEM completado.')

