import ee
import folium

# Asegurarse de que `roi_quebrada_honda` y `watershed_gdf` estén definidos
# Re-definimos `roi_quebrada_honda` y `centroid_quebrada_honda` por robustez
if 'watershed_gdf' not in locals() or watershed_gdf is None:
    print('Error: El GeoDataFrame de la cuenca (`watershed_gdf`) no está disponible. Por favor, ejecuta las celdas anteriores.')
    roi_quebrada_honda = None
else:
    # Convertir la geometría de la cuenca de GeoDataFrame a ee.Geometry
    # Aseguramos que watershed_gdf tenga al menos una geometría
    if not watershed_gdf.empty:
        roi_quebrada_honda = ee.Geometry(watershed_gdf.geometry.iloc[0].__geo_interface__)
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
        lon_qh, lat_qh = centroid_quebrada_honda['coordinates']
        print('`roi_quebrada_honda` y `centroid_quebrada_honda` definidos.')
    else:
        print('Error: watershed_gdf está vacío o no contiene geometrías. No se puede definir roi_quebrada_honda.')
        roi_quebrada_honda = None


if roi_quebrada_honda is not None:
    # 1. Cargar la colección de imágenes MODIS/061/MOD44B
    modis_tree_cover = ee.ImageCollection('MODIS/061/MOD44B')

    # 2. Filtrar por un año específico (por ejemplo, 2015, es un dataset de un año)
    # El dataset MOD44B (VCF) es una imagen anual. Seleccionaremos una imagen para un año representativo.
    # Por ejemplo, el dataset está disponible desde 2000 hasta 2015.
    # Vamos a tomar la imagen de un año reciente dentro de ese rango, e.g., 2015.
    # Si hay múltiples imágenes, se podría tomar la media, pero para VCF usualmente hay una por año.
    # Este dataset tiene bandas 'Percent_Tree_Cover', 'Percent_NonTree_Vegetation', 'Percent_Nodata', 'Quality'.

    # Seleccionar una imagen de un año específico y la banda 'Percent_Tree_Cover'
    # Filtraremos por la fecha más reciente disponible en la colección para un solo año (2015).
    tree_cover_image = modis_tree_cover.filterDate('2015-01-01', '2015-12-31').select('Percent_Tree_Cover').first()

    # 3. Recortar la imagen de cobertura arbórea a la región de interés (cuenca 'Quebrada la Honda')
    tree_cover_quebrada_honda = tree_cover_image.clip(roi_quebrada_honda)

    print('Imagen de Cobertura Arbórea MODIS recortada para Quebrada la Honda:')
    print(tree_cover_quebrada_honda.getInfo())

    # 4. Definir una paleta de colores para la cobertura arbórea
    # La banda 'Percent_Tree_Cover' va de 0 a 100.
    tree_cover_vis = {
      'min': 0,
      'max': 100,
      'palette': ['red', 'orange', 'yellow', 'lightgreen', 'green', 'darkgreen'] # De bajo a alto porcentaje de cobertura
    }

    # 5. Obtener el MapId y el token de la imagen de cobertura arbórea
    map_id_tree_cover = tree_cover_quebrada_honda.getMapId(tree_cover_vis)

    # 6. Crear un mapa Folium base centrado en la cuenca
    m_tree_cover = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # 7. Añadir la capa de cobertura arbórea al mapa
    folium.TileLayer(
        tiles=map_id_tree_cover['tile_fetcher'].url_format,
        attr='Google Earth Engine - MODIS Tree Cover',
        overlay=True,
        name='Percent Tree Cover (MODIS)'
    ).add_to(m_tree_cover)

    # 8. Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_tree_cover)

    # 9. Añadir control de capas
    m_tree_cover.add_child(folium.LayerControl())

    display(m_tree_cover)
    print('\nVisualización de la capa de Cobertura Arbórea (MODIS) completada.')
else:
    print('Error: `roi_quebrada_honda` no está definida. No se puede visualizar la cobertura arbórea.')

"""### Comparación de la Distribución de Áreas: Zonificación Ambiental del POMCA vs. Zonas de Vida de Holdridge

A continuación, se presentan las tablas resumen de la distribución de áreas en hectáreas y su porcentaje para la cuenca 'Quebrada la Honda', primero para la zonificación ambiental del POMCA y luego para las zonas de vida de Holdridge. Esto permite una comparación directa de ambas clasificaciones del territorio.

### Correlación entre la Cobertura Arbórea y la Precipitación Media

Vamos a investigar la relación entre la cobertura arbórea (obtenida del dataset MODIS) y la precipitación media en la cuenca 'Quebrada la Honda'. Esto nos permitirá entender si existe una correlación espacial entre estas dos variables ambientales.
"""

import ee
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

# Asegurarse de que `roi_quebrada_honda`, `tree_cover_quebrada_honda` y `precipitation_quebrada_honda_analysis` estén definidos
if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca (`roi_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'tree_cover_quebrada_honda' not in locals() or tree_cover_quebrada_honda is None:
    print('Error: La imagen de cobertura arbórea (`tree_cover_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'precipitation_quebrada_honda_analysis' not in locals() or precipitation_quebrada_honda_analysis is None:
    print('Error: La imagen de precipitación media (`precipitation_quebrada_honda_analysis`) no está definida. Por favor, ejecuta las celdas anteriores.')
else:
    # 1. Renombrar las bandas para una fácil referencia
    tree_cover_band = tree_cover_quebrada_honda.rename('Tree_Cover_Percent')
    precipitation_band = precipitation_quebrada_honda_analysis.rename('Mean_Precipitation_mm')

    # Obtener la escala y CRS de la imagen de cobertura arbórea (la más fina)
    target_scale = tree_cover_band.projection().nominalScale().getInfo()
    target_crs = tree_cover_band.projection().crs().getInfo()

    print(f"Escala nominal de Cobertura Arbórea: {tree_cover_band.projection().nominalScale().getInfo()} metros")
    print(f"Escala nominal de Precipitación: {precipitation_band.projection().nominalScale().getInfo()} metros")
    print(f"Escala objetivo para el análisis: {target_scale} metros")

    # Reproyectar ambas imágenes a la escala y CRS objetivo.
    tree_cover_band_reprojected = tree_cover_band.reproject(
        crs=target_crs,
        scale=target_scale
    ).setDefaultProjection(crs=target_crs, scale=target_scale)

    precipitation_band_reprojected = precipitation_band.reproject(
        crs=target_crs,
        scale=target_scale
    ).setDefaultProjection(crs=target_crs, scale=target_scale)

    # Combinar las dos bandas en una sola imagen. Ambas deben tener la misma resolución ahora.
    combined_image_correlation = tree_cover_band_reprojected.addBands(precipitation_band_reprojected)

    # 2. Calcular el coeficiente de correlación de Pearson entre las dos bandas
    correlation_result = combined_image_correlation.reduceRegion(**{
        'reducer': ee.Reducer.pearsonsCorrelation(),
        'geometry': roi_quebrada_honda,
        'scale': target_scale, # Usar la escala común
        'maxPixels': 1e9, # Mantener maxPixels alto para reduceRegion
        'bestEffort': True
    })

    # Obtener el coeficiente de correlación de Pearson
    pearson_correlation = correlation_result.getInfo()

    # El reducer devuelve 'correlation' y 'p_value'
    r_value = pearson_correlation.get('correlation')
    p_value = pearson_correlation.get('p_value')

    print(f'\nCoeficiente de Correlación de Pearson entre Cobertura Arbórea y Precipitación Media:')

    # Modificación: Verificar si los valores son numéricos antes de formatear
    r_value_formatted = None
    if isinstance(r_value, (int, float)) and not pd.isna(r_value):
        r_value_formatted = float(r_value)
        print(f'  R: {r_value_formatted:.2f}')
    else:
        print(f'  R: {r_value}')

    p_value_formatted = None
    if isinstance(p_value, (int, float)) and not pd.isna(p_value):
        p_value_formatted = float(p_value)
        print(f'  P-valor: {p_value_formatted:.3f}')
    else:
        print(f'  P-valor: {p_value}')

    # 3. Extraer valores de píxeles para el scatter plot (muestra aleatoria)
    sample_points = combined_image_correlation.sample(
        region=roi_quebrada_honda,
        scale=target_scale, # Usar la escala común
        numPixels=1000,
        seed=0,
        dropNulls=True
    )

    # Convertir los puntos muestreados a un DataFrame de Pandas
    sample_list = sample_points.getInfo()['features']
    data_for_scatter = []
    for feature in sample_list:
        props = feature['properties']
        tree_cover = props.get('Tree_Cover_Percent')
        precipitation = props.get('Mean_Precipitation_mm')
        # Solo añadir si ambos valores son válidos (no None y no NaN)
        if tree_cover is not None and not pd.isna(tree_cover) and \
           precipitation is not None and not pd.isna(precipitation):
            data_for_scatter.append({
                'Cobertura Arbórea (%)': tree_cover,
                'Precipitación Media (mm)': precipitation
            })

    correlation_df = pd.DataFrame(data_for_scatter)

    # 4. Visualizar la relación en un gráfico de dispersión
    if not correlation_df.empty:
        plt.figure(figsize=(10, 7))
        sns.scatterplot(
            x='Precipitación Media (mm)',
            y='Cobertura Arbórea (%)',
            data=correlation_df,
            alpha=0.6,
            edgecolor='w',
            s=50,
            color='darkgreen'
        )
        plt.title('Dispersión: Cobertura Arbórea vs. Precipitación Media en Quebrada la Honda')
        plt.xlabel('Precipitación Media (mm)')
        plt.ylabel('Cobertura Arbórea (%)')
        plt.grid(True, linestyle='--', alpha=0.7)

        if r_value_formatted is not None:
            plt.text(0.05, 0.95, f'Coeficiente de Pearson (R): {r_value_formatted:.2f}', transform=plt.gca().transAxes, fontsize=12, verticalalignment='top')
        else:
            plt.text(0.05, 0.95, f'Coeficiente de Pearson (R): {r_value}', transform=plt.gca().transAxes, fontsize=12, verticalalignment='top')

        plt.show()
    else:
        print('No hay datos suficientes en la muestra para generar el gráfico de dispersión.')

    print('\nAnálisis de correlación entre cobertura arbórea y precipitación media completado.')

