"""### Mapa Interactivo Combinado: DEM, Clases de Altitud y Precipitación

Este mapa interactivo te permite visualizar simultáneamente el Modelo de Elevación Digital (DEM), las clases de altitud y la precipitación media en la cuenca 'Quebrada la Honda'.

**Instrucciones:**
*   Usa el icono de capas (generalmente en la esquina superior derecha) para activar/desactivar las capas de 'DEM de Altitud', 'Clases de Altitud' y 'Precipitación Media'.
*   La capa 'Límite de Cuenca' siempre estará visible para referencia.
"""

import ee
import folium
import numpy as np

# Asegurarse de que `dem_quebrada_honda`, `reclassified_dem_ee`,
# `roi_quebrada_honda`, `watershed_gdf` y `precipitation_quebrada_honda_analysis` estén definidos
if 'dem_quebrada_honda' not in locals() or dem_quebrada_honda is None:
    print('Error: La imagen DEM recortada para Quebrada la Honda (`dem_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'reclassified_dem_ee' not in locals() or reclassified_dem_ee is None:
    print('Error: La imagen de clases de altitud (`reclassified_dem_ee`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'watershed_gdf' not in locals() or watershed_gdf is None:
    print('Error: El GeoDataFrame de la cuenca (`watershed_gdf`) no está disponible. Por favor, ejecuta las celdas anteriores.')
elif 'precipitation_quebrada_honda_analysis' not in locals() or precipitation_quebrada_honda_analysis is None:
    print('Error: La imagen de precipitación media (`precipitation_quebrada_honda_analysis`) no está definida. Por favor, ejecuta las celdas anteriores.')
else:
    # Parámetros de visualización para el DEM (reutilizamos los definidos anteriormente)
    dem_vis = {
        'min': 0,        # Altitud mínima
        'max': 3000,     # Altitud máxima (ajustar según el rango real de tu DEM)
        'palette': ['#000000', '#555555', '#AAAAAA', '#FFFFFF'] # Escala de grises para el DEM
    }

    # Parámetros de visualización para las Clases de Altitud (reutilizamos los definidos anteriormente)
    altitude_class_vis = {
      'min': 1,
      'max': 5,
      'palette': ['#ffffcc', '#a1dab4', '#41b6c4', '#2c7fb8', '#253494'] # Colores para clases de altitud
    }

    # Parámetros de visualización para la Precipitación (reutilizamos los definidos anteriormente)
    precipitation_vis = {
      'min': 0,    # Valor mínimo de precipitación (mm)
      'max': 10,   # Valor máximo de precipitación (mm) - ajustar según los datos
      'palette': ['#ffffcc', '#a1dab4', '#41b6c4', '#2c7fb8', '#253494'] # Paleta de colores de baja a alta precipitación
    }

    # Obtener el centroide de la cuenca para centrar el mapa (reutilizamos centroid_quebrada_honda)
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    # Crear un mapa Folium base
    m_combined_prec_alt = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # 1. Añadir la capa del DEM
    map_id_dem = ee.Image(dem_quebrada_honda).getMapId(dem_vis)
    folium.TileLayer(
        tiles=map_id_dem['tile_fetcher'].url_format,
        attr='Google Earth Engine - DEM',
        overlay=True,
        name='DEM de Altitud',
        show=True # Visible por defecto
    ).add_to(m_combined_prec_alt)

    # 2. Añadir la capa de Clases de Altitud
    map_id_altitude = ee.Image(reclassified_dem_ee).getMapId(altitude_class_vis)
    folium.TileLayer(
        tiles=map_id_altitude['tile_fetcher'].url_format,
        attr='Google Earth Engine - Clases de Altitud',
        overlay=True,
        name='Clases de Altitud',
        show=True # Visible por defecto
    ).add_to(m_combined_prec_alt)

    # 3. Añadir la capa de Precipitación Media
    map_id_prec_qh = ee.Image(precipitation_quebrada_honda_analysis).getMapId(precipitation_vis)
    folium.TileLayer(
        tiles=map_id_prec_qh['tile_fetcher'].url_format,
        attr='Google Earth Engine - Precipitación Media',
        overlay=True,
        name='Precipitación Media (mm)',
        show=False # Inicialmente oculto, para no sobrecargar la visualización
    ).add_to(m_combined_prec_alt)

    # 4. Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_combined_prec_alt)

    # 5. Añadir control de capas
    m_combined_prec_alt.add_child(folium.LayerControl())

    display(m_combined_prec_alt)
    print('\nMapa interactivo combinado de DEM, clases de altitud y precipitación completado.')

