import ee
import folium
import numpy as np
import matplotlib.colors as mcolors
import matplotlib.pyplot as plt
import geopandas as gpd
import os
import zipfile

print('Asegurando la disponibilidad de variables clave para la visualización combinada...')

# Re-inicializar Earth Engine para asegurar el contexto
try:
    ee.Initialize(project='studious-camp-486620-m3')
    print('Earth Engine inicializado.')
except Exception as e:
    print(f'Error al inicializar Earth Engine: {e}. Por favor, asegúrate de haber ejecutado ee.Authenticate() y ee.Initialize() con un Project ID válido.')

# 1. Asegurar watershed_gdf y roi_quebrada_honda
if 'watershed_gdf' not in locals() or watershed_gdf is None or watershed_gdf.empty:
    print('`watershed_gdf` no encontrada o vacía. Intentando cargarla...')
    zip_file_path = '/content/watershed.zip'
    unzip_dir = '/content/watershed_extracted'
    shp_file_path = os.path.join(unzip_dir, 'watershed.shp')
    try:
        if not os.path.exists(shp_file_path): # Check if shp is already extracted
            os.makedirs(unzip_dir, exist_ok=True)
            with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:
                zip_ref.extractall(unzip_dir)
            print(f"Archivo '{zip_file_path}' descomprimido en '{unzip_dir}'.")
        watershed_gdf = gpd.read_file(shp_file_path)
        print('`watershed_gdf` cargada exitosamente.')
    except Exception as e:
        print(f'Error al cargar `watershed_gdf`: {e}')
        watershed_gdf = None

if watershed_gdf is not None and not watershed_gdf.empty:
    if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
        roi_quebrada_honda = ee.Geometry(watershed_gdf.geometry.iloc[0].__geo_interface__)
        print('`roi_quebrada_honda` creada.')
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
        print('`centroid_quebrada_honda` creada.')
else:
    print('Error crítico: `watershed_gdf` no está disponible, no se puede definir `roi_quebrada_honda`.')
    roi_quebrada_honda = None
    centroid_quebrada_honda = None

# 2. Asegurar dem_quebrada_honda
if 'dem_quebrada_honda' not in locals() or dem_quebrada_honda is None:
    print('`dem_quebrada_honda` no encontrada. Intentando recrearla...')
    if roi_quebrada_honda is not None:
        try:
            hydrosheds_dem_image = ee.Image('WWF/HydroSHEDS/03VFDEM')
            dem_quebrada_honda = hydrosheds_dem_image.clip(roi_quebrada_honda)
            print('`dem_quebrada_honda` recreada.')
        except Exception as e:
            print(f'Error recreando `dem_quebrada_honda`: {e}')
            dem_quebrada_honda = None
    else:
        print('Error: `roi_quebrada_honda` no está definida, no se puede recrear `dem_quebrada_honda`.')
        dem_quebrada_honda = None

# 3. Asegurar precipitation_quebrada_honda_analysis
if 'precipitation_quebrada_honda_analysis' not in locals() or precipitation_quebrada_honda_analysis is None:
    print('`precipitation_quebrada_honda_analysis` no encontrada. Intentando recrearla...')
    if roi_quebrada_honda is not None:
        try:
            new_start_date_analysis = '2020-01-01'
            new_end_date_analysis = '2035-12-31'
            chirps_daily_analysis = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY').filterDate(new_start_date_analysis, new_end_date_analysis)
            mean_precipitation_analysis = chirps_daily_analysis.select('precipitation').mean().rename('mean_precipitation_2020_2035')
            precipitation_quebrada_honda_analysis = mean_precipitation_analysis.clip(roi_quebrada_honda)
            print('`precipitation_quebrada_honda_analysis` recreada.')
        except Exception as e:
            print(f'Error recreando `precipitation_quebrada_honda_analysis`: {e}')
            precipitation_quebrada_honda_analysis = None
    else:
        print('Error: `roi_quebrada_honda` no está definida, no se puede recrear `precipitation_quebrada_honda_analysis`.')
        precipitation_quebrada_honda_analysis = None

print('Verificación de variables clave completada.')

# Proceed only if critical variables are available
if all(v is not None for v in [roi_quebrada_honda, dem_quebrada_honda, precipitation_quebrada_honda_analysis, watershed_gdf, centroid_quebrada_honda]):

    # 4. Definir Umbrales (re-definir para robustez, incluyendo colores)
    altitude_thresholds = [
        {'clase': 1, 'nombre': '0-499 m', 'min': 0, 'max': 500, 'color': '#ffffcc'}, # Amarillo muy claro
        {'clase': 2, 'nombre': '500-999 m', 'min': 500, 'max': 1000, 'color': '#a1dab4'}, # Verde claro
        {'clase': 3, 'nombre': '1000-1499 m', 'min': 1000, 'max': 1500, 'color': '#41b6c4'}, # Azul-verde
        {'clase': 4, 'nombre': '1500-1999 m', 'min': 1500, 'max': 2000, 'color': '#2c7fb8'}, # Azul
        {'clase': 5, 'nombre': '>= 2000 m', 'min': 2000, 'max': np.inf, 'color': '#253494'} # Azul oscuro
    ]

    precipitation_thresholds = [
        {'clase': 1, 'nombre': 'Baja (< 3 mm/día)', 'min': 0, 'max': 3, 'color': '#f0f9e8'}, # Azul muy claro
        {'clase': 2, 'nombre': 'Moderada (3-6 mm/día)', 'min': 3, 'max': 6, 'color': '#7bccc4'}, # Azul medio
        {'clase': 3, 'nombre': 'Alta (> 6 mm/día)', 'min': 6, 'max': np.inf, 'color': '#2b8cbe'} # Azul oscuro
    ]

    # 5. Reclasificar imágenes de Earth Engine
    # Altitud
    reclassified_altitude_ee = ee.Image(0).rename('altitude_class')
    for threshold in altitude_thresholds:
        lower, upper, class_val = threshold['min'], threshold['max'], threshold['clase']
        upper_val = upper if upper != np.inf else 1000000 # Un valor suficientemente grande para altitud
        condition = dem_quebrada_honda.gte(lower).And(dem_quebrada_honda.lt(upper_val))
        reclassified_altitude_ee = reclassified_altitude_ee.where(condition, ee.Image(class_val))

    # Precipitación
    reclassified_precipitation_ee = ee.Image(0).rename('precipitation_class')
    for threshold in precipitation_thresholds:
        lower, upper, class_val = threshold['min'], threshold['max'], threshold['clase']
        upper_val = upper if upper != np.inf else 1000 # Un valor suficientemente grande para precipitación
        condition = precipitation_quebrada_honda_analysis.gte(lower).And(precipitation_quebrada_honda_analysis.lt(upper_val))
        reclassified_precipitation_ee = reclassified_precipitation_ee.where(condition, ee.Image(class_val))

    # 6. Definir parámetros de visualización para cada capa re-clasificada
    altitude_vis = {
        'min': 1, 'max': len(altitude_thresholds),
        'palette': [t['color'] for t in altitude_thresholds]
    }
    precipitation_vis = {
        'min': 1, 'max': len(precipitation_thresholds),
        'palette': [t['color'] for t in precipitation_thresholds]
    }

    # 7. Crear el mapa Folium
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']
    m_combined_alt_prec_thresholds = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # 8. Añadir capas re-clasificadas al mapa
    # Altitud
    map_id_altitude = reclassified_altitude_ee.getMapId(altitude_vis)
    folium.TileLayer(
        tiles=map_id_altitude['tile_fetcher'].url_format,
        attr='Google Earth Engine - Altitud',
        overlay=True,
        name='Clases de Altitud',
        show=True # Visible por defecto
    ).add_to(m_combined_alt_prec_thresholds)

    # Precipitación
    map_id_precipitation = reclassified_precipitation_ee.getMapId(precipitation_vis)
    folium.TileLayer(
        tiles=map_id_precipitation['tile_fetcher'].url_format,
        attr='Google Earth Engine - Precipitación',
        overlay=True,
        name='Clases de Precipitación',
        show=False # Inicialmente oculto
    ).add_to(m_combined_alt_prec_thresholds)

    # Añadir el límite de la cuenca
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_combined_alt_prec_thresholds)

    # Añadir control de capas
    m_combined_alt_prec_thresholds.add_child(folium.LayerControl())

    # 9. Crear y añadir la leyenda HTML combinada
    def get_threshold_legend_html(title, thresholds, class_key='clase', name_key='nombre', color_key='color'):
        html = f'<p style="font-weight: bold; margin-bottom: 5px;">{title}</p>'
        html += '<ul style="list-style:none; padding:0; margin:0;">'
        for threshold in thresholds:
            name = threshold[name_key] if name_key in threshold else f"Clase {threshold[class_key]}"
            color = threshold[color_key]
            html += f'''
                <li style="display:flex; align-items:center; margin-bottom:3px;">
                  <span style="background:{color}; width:20px; height:15px; display:inline-block; margin-right:5px; border:1px solid black;"></span>
                  <span>{name}</span>
                </li>
            '''
        html += '</ul>'
        return html

    legend_html_alt_prec = f'''
    <div style="position: fixed;
                bottom: 50px; left: 50px; width: 280px; height: auto;
                border:2px solid grey; z-index:9999; font-size:14px;
                background-color:white; opacity:0.9; padding:10px;">
      <h4 style="margin-top:0;">Leyenda de Umbrales</h4>
      {get_threshold_legend_html('Altitud (m)', altitude_thresholds, name_key='nombre')}
      <br>
      {get_threshold_legend_html('Precipitación Media', precipitation_thresholds, name_key='nombre')}
    </div>
    '''

    m_combined_alt_prec_thresholds.get_root().html.add_child(folium.Element(legend_html_alt_prec))

    display(m_combined_alt_prec_thresholds)
    print('\nMapa interactivo con umbrales de altitud y precipitación media completado.')

else:
    print('Error crítico: No se pudieron asegurar todas las variables necesarias para generar el mapa combinado.')

