if 'reclassified_slope_quebrada_honda' not in locals() or reclassified_slope_quebrada_honda is None:
    print('Error: La imagen de pendiente reclasificada (`reclassified_slope_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'tree_cover_quebrada_honda' not in locals() or tree_cover_quebrada_honda is None:
    print('Error: La imagen de cobertura arbórea (`tree_cover_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'watershed_gdf' not in locals() or watershed_gdf is None:
    print('Error: El GeoDataFrame de la cuenca (`watershed_gdf`) no está disponible. Por favor, ejecuta las celdas anteriores.')
else:
    # Parámetros de visualización para las clases de pendiente (riesgos de suelo)
    slope_risk_vis = {
      'min': 1,
      'max': 5,
      'palette': ['#d7191c', '#fdae61', '#ffffbf', '#a6d96a', '#1a9641'] # Colores de alto riesgo (rojo) a bajo riesgo (verde)
    }

    # Parámetros de visualización para la Cobertura Arbórea
    tree_cover_vis = {
      'min': 0,
      'max': 100,
      'palette': ['red', 'orange', 'yellow', 'lightgreen', 'green', 'darkgreen'] # De bajo a alto porcentaje de cobertura
    }

    # Obtener el centroide de la cuenca para centrar el mapa
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    # Crear un mapa Folium base
    m_combined_risk_tree = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # 1. Añadir la capa de Clases de Riesgo de Suelo (Pendiente)
    map_id_slope_risk = ee.Image(reclassified_slope_quebrada_honda).getMapId(slope_risk_vis)
    folium.TileLayer(
        tiles=map_id_slope_risk['tile_fetcher'].url_format,
        attr='Google Earth Engine - Clases de Pendiente (Riesgo de Suelo)',
        overlay=True,
        name='Clases de Riesgo de Suelo (Pendiente)',
        show=True # Visible por defecto
    ).add_to(m_combined_risk_tree)

    # 2. Añadir la capa de Cobertura Arbórea
    map_id_tree_cover = ee.Image(tree_cover_quebrada_honda).getMapId(tree_cover_vis)
    folium.TileLayer(
        tiles=map_id_tree_cover['tile_fetcher'].url_format,
        attr='Google Earth Engine - Cobertura Arbórea',
        overlay=True,
        name='Cobertura Arbórea (%)',
        show=False # Inicialmente oculto
    ).add_to(m_combined_risk_tree)

    # 3. Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_combined_risk_tree)

    # 4. Añadir control de capas
    m_combined_risk_tree.add_child(folium.LayerControl())

    display(m_combined_risk_tree)
    print('\nMapa interactivo combinado de riesgo de suelo y cobertura arbórea completado.')

"""### Correlación entre el Riesgo de Suelo (Clases de Pendiente) y la Cobertura Arbórea

Vamos a cuantificar la relación entre las clases de riesgo de suelo (pendientes) y la cobertura arbórea. Esto nos ayudará a entender si las áreas con mayor riesgo de erosión (pendientes más pronunciadas) tienden a tener menor o mayor cobertura vegetal.
"""

import ee
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np

# Asegurarse de que `roi_quebrada_honda`, `reclassified_slope_quebrada_honda` y `tree_cover_quebrada_honda` estén definidos
if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca (`roi_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'reclassified_slope_quebrada_honda' not in locals() or reclassified_slope_quebrada_honda is None:
    print('Error: La imagen de pendiente reclasificada (`reclassified_slope_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'tree_cover_quebrada_honda' not in locals() or tree_cover_quebrada_honda is None:
    print('Error: La imagen de cobertura arbórea (`tree_cover_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
else:
    # 1. Renombrar las bandas para una fácil referencia
    slope_class_band = reclassified_slope_quebrada_honda.rename('Slope_Class')
    tree_cover_band = tree_cover_quebrada_honda.rename('Tree_Cover_Percent')

    # Obtener la escala y CRS de la imagen de cobertura arbórea (la más fina)
    # Aseguramos que ambas imágenes tengan la misma proyección y escala antes de combinarlas para la correlación.
    target_scale = tree_cover_band.projection().nominalScale().getInfo()
    target_crs = tree_cover_band.projection().crs().getInfo()

    # Reproyectar ambas imágenes a la escala y CRS objetivo.
    slope_class_band_reprojected = slope_class_band.reproject(
        crs=target_crs,
        scale=target_scale
    ).setDefaultProjection(crs=target_crs, scale=target_scale)

    tree_cover_band_reprojected = tree_cover_band.reproject(
        crs=target_crs,
        scale=target_scale
    ).setDefaultProjection(crs=target_crs, scale=target_scale)

    # Combinar las dos bandas en una sola imagen.
    combined_image_correlation_risk_tree = slope_class_band_reprojected.addBands(tree_cover_band_reprojected)

    # 2. Calcular el coeficiente de correlación de Pearson entre las dos bandas
    correlation_result_risk_tree = combined_image_correlation_risk_tree.reduceRegion(**{
        'reducer': ee.Reducer.pearsonsCorrelation(),
        'geometry': roi_quebrada_honda,
        'scale': target_scale, # Usar la escala común
        'maxPixels': 1e9,
        'bestEffort': True
    })

    # Obtener el coeficiente de correlación de Pearson
    pearson_correlation_risk_tree = correlation_result_risk_tree.getInfo()

    r_value_risk_tree = pearson_correlation_risk_tree.get('correlation')
    p_value_risk_tree = pearson_correlation_risk_tree.get('p_value')

    r_value_risk_tree_formatted = None # Initialize to None
    p_value_risk_tree_formatted = None # Initialize to None

    print(f'\nCoeficiente de Correlación de Pearson entre Clases de Pendiente y Cobertura Arbórea:')
    if isinstance(r_value_risk_tree, (int, float)) and not pd.isna(r_value_risk_tree):
        r_value_risk_tree_formatted = float(r_value_risk_tree)
        print(f'  R: {r_value_risk_tree_formatted:.2f}')
    else:
        print(f'  R: {r_value_risk_tree}')

    if isinstance(p_value_risk_tree, (int, float)) and not pd.isna(p_value_risk_tree):
        p_value_risk_tree_formatted = float(p_value_risk_tree)
        print(f'  P-valor: {p_value_risk_tree_formatted:.3f}')
    else:
        print(f'  P-valor: {p_value_risk_tree}')

    # 3. Extraer valores de píxeles para el scatter plot (muestra aleatoria)
    sample_points_risk_tree = combined_image_correlation_risk_tree.sample(
        region=roi_quebrada_honda,
        scale=target_scale,
        numPixels=1000,
        seed=1, # Usar una semilla diferente para este muestreo
        dropNulls=True
    )

    # Convertir los puntos muestreados a un DataFrame de Pandas
    sample_list_risk_tree = sample_points_risk_tree.getInfo()['features']
    data_for_scatter_risk_tree = []
    for feature in sample_list_risk_tree:
        props = feature['properties']
        slope_class = props.get('Slope_Class')
        tree_cover = props.get('Tree_Cover_Percent')
        if slope_class is not None and not pd.isna(slope_class) and \
           tree_cover is not None and not pd.isna(tree_cover):
            data_for_scatter_risk_tree.append({
                'Clase de Pendiente': slope_class,
                'Cobertura Arbórea (%)': tree_cover
            })

    correlation_df_risk_tree = pd.DataFrame(data_for_scatter_risk_tree)

    # 4. Visualizar la relación en un gráfico de dispersión
    if not correlation_df_risk_tree.empty:
        plt.figure(figsize=(10, 7))
        sns.scatterplot(
            x='Clase de Pendiente',
            y='Cobertura Arbórea (%)',
            data=correlation_df_risk_tree,
            alpha=0.6,
            edgecolor='w',
            s=50,
            hue='Clase de Pendiente', # Color por clase de pendiente
            palette='viridis' # Una paleta adecuada para valores categóricos/ordinales
        )
        plt.title('Dispersión: Clase de Pendiente vs. Cobertura Arbórea en Quebrada la Honda')
        plt.xlabel('Clase de Pendiente')
        plt.ylabel('Cobertura Arbórea (%)')
        plt.xticks(ticks=sorted(correlation_df_risk_tree['Clase de Pendiente'].unique())) # Mostrar ticks para cada clase
        plt.grid(True, linestyle='--', alpha=0.7)

        if r_value_risk_tree_formatted is not None:
            plt.text(0.05, 0.95, f'Coeficiente de Pearson (R): {r_value_risk_tree_formatted:.2f}', transform=plt.gca().transAxes, fontsize=12, verticalalignment='top')
        else:
            plt.text(0.05, 0.95, f'Coeficiente de Pearson (R): {r_value_risk_tree}', transform=plt.gca().transAxes, fontsize=12, verticalalignment='top')

        plt.show()
    else:
        print('No hay datos suficientes en la muestra para generar el gráfico de dispersión.')

    print('\nAnálisis de correlación entre riesgo de suelo (pendiente) y cobertura arbórea completado.')

"""### Definición de Umbrales para Variables Ambientales

Los umbrales son rangos o valores críticos que nos permiten categorizar variables continuas en clases discretas. Esto es fundamental para análisis espaciales, gestión de recursos y evaluación de riesgos. A continuación, se definen los umbrales para las principales variables ambientales de la cuenca 'Quebrada la Honda' que hemos estado analizando.

#### 1. Umbrales de Altitud (DEM)

La altitud se clasifica en cinco rangos, los cuales ya hemos utilizado para la reclasificación del DEM.
"""

import numpy as np

altitude_thresholds = [
    {'clase': 1, 'rango': '0-499 m', 'min': 0, 'max': 500},
    {'clase': 2, 'rango': '500-999 m', 'min': 500, 'max': 1000},
    {'clase': 3, 'rango': '1000-1499 m', 'min': 1000, 'max': 1500},
    {'clase': 4, 'rango': '1500-1999 m', 'min': 1500, 'max': 2000},
    {'clase': 5, 'rango': '>= 2000 m', 'min': 2000, 'max': np.inf}
]

print('Umbrales de Altitud definidos:')
for umbral in altitude_thresholds:
    print(umbral)

"""#### 2. Umbrales de Pendiente (Riesgo de Suelo)

La pendiente también se ha reclasificado en cinco clases que representan diferentes niveles de riesgo de suelo, desde plano hasta muy empinado.
"""

slope_thresholds = [
    {'clase': 1, 'nombre': 'Plano', 'rango': '0-2°', 'min': 0, 'max': 2},
    {'clase': 2, 'nombre': 'Suave', 'rango': '2-5°', 'min': 2, 'max': 5},
    {'clase': 3, 'nombre': 'Moderado', 'rango': '5-10°', 'min': 5, 'max': 10},
    {'clase': 4, 'nombre': 'Empinado', 'rango': '10-25°', 'min': 10, 'max': 25},
    {'clase': 5, 'nombre': 'Muy Empinado', 'rango': '>25°', 'min': 25, 'max': 100} # Máximo teórico para pendiente en grados es 90
]

print('Umbrales de Pendiente (Riesgo de Suelo) definidos:')
for umbral in slope_thresholds:
    print(umbral)

"""#### 3. Umbrales de Precipitación Media Anual

Para la precipitación media, podemos definir umbrales que clasifiquen las zonas en secas, moderadas y húmedas. Estos son ejemplos y pueden ajustarse según el contexto climático específico de la región.
"""

precipitation_thresholds = [
    {'clase': 'Baja', 'rango': '< 3 mm/día', 'min': 0, 'max': 3},
    {'clase': 'Moderada', 'rango': '3-6 mm/día', 'min': 3, 'max': 6},
    {'clase': 'Alta', 'rango': '> 6 mm/día', 'min': 6, 'max': np.inf}
]

print('Umbrales de Precipitación Media definidos:')
for umbral in precipitation_thresholds:
    print(umbral)

"""#### 4. Umbrales de Temperatura Media Anual

Los umbrales de temperatura pueden indicar zonas frías, templadas o cálidas, lo cual es relevante para la distribución de especies y procesos ecológicos.
"""

temperature_thresholds = [
    {'clase': 'Fría', 'rango': '< 10 °C', 'min': -np.inf, 'max': 10},
    {'clase': 'Templada', 'rango': '10-20 °C', 'min': 10, 'max': 20},
    {'clase': 'Cálida', 'rango': '> 20 °C', 'min': 20, 'max': np.inf}
]

print('Umbrales de Temperatura Media definidos:')
for umbral in temperature_thresholds:
    print(umbral)

"""#### 5. Umbrales de Cobertura Arbórea

La cobertura arbórea puede clasificarse para identificar áreas con bosque denso, cobertura dispersa o zonas sin árboles, lo que es clave para estudios de biodiversidad y planificación del uso del suelo.
"""

tree_cover_thresholds = [
    {'clase': 'Sin Cobertura', 'rango': '0-10%', 'min': 0, 'max': 10},
    {'clase': 'Cobertura Escasa', 'rango': '10-40%', 'min': 10, 'max': 40},
    {'clase': 'Cobertura Moderada', 'rango': '40-70%', 'min': 40, 'max': 70},
    {'clase': 'Cobertura Densa', 'rango': '> 70%', 'min': 70, 'max': 100}
]

print('Umbrales de Cobertura Arbórea definidos:')
for umbral in tree_cover_thresholds:
    print(umbral)

"""### Visualización Interactiva de Niveles de Cobertura Arbórea

Este mapa muestra la distribución de la cobertura arbórea en la cuenca 'Quebrada la Honda', clasificada en diferentes niveles. Incluye una leyenda interactiva para facilitar la interpretación.
"""

import ee
import folium
import numpy as np
import matplotlib.colors as mcolors
import matplotlib.pyplot as plt
import geopandas as gpd
import os
import zipfile

# Re-inicializar Earth Engine para asegurar el contexto
try:
    ee.Initialize(project='studious-camp-486620-m3')
    print('Earth Engine inicializado.')
except Exception as e:
    print(f'Error al inicializar Earth Engine: {e}. Por favor, asegúrate de haber ejecutado ee.Authenticate() y ee.Initialize() con un Project ID válido.')

# 1. Asegurar watershed_gdf y roi_quebrada_honda
if 'watershed_gdf' not in locals() or watershed_gdf is None or watershed_gdf.empty:
    print('`watershed_gdf` no encontrada o vacía. Intentando cargarla...')
    zip_file_path = '/content/watershed.zip'
    unzip_dir = '/content/watershed_extracted'
    shp_file_path = os.path.join(unzip_dir, 'watershed.shp')
    try:
        if not os.path.exists(shp_file_path): # Check if shp is already extracted
            os.makedirs(unzip_dir, exist_ok=True)
            with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:
                zip_ref.extractall(unzip_dir)
            print(f"Archivo '{zip_file_path}' descomprimido en '{unzip_dir}'.")
        watershed_gdf = gpd.read_file(shp_file_path)
        print('`watershed_gdf` cargada exitosamente.')
    except Exception as e:
        print(f'Error al cargar `watershed_gdf`: {e}')
        watershed_gdf = None

if watershed_gdf is not None and not watershed_gdf.empty:
    if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
        roi_quebrada_honda = ee.Geometry(watershed_gdf.geometry.iloc[0].__geo_interface__)
        print('`roi_quebrada_honda` creada.')
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
        print('`centroid_quebrada_honda` creada.')
else:
    print('Error crítico: `watershed_gdf` no está disponible, no se puede definir `roi_quebrada_honda`.')
    roi_quebrada_honda = None
    centroid_quebrada_honda = None

# 2. Cargar MODIS Tree Cover (MOD44B) y recortar a la cuenca
if roi_quebrada_honda is not None:
    modis_tree_cover = ee.ImageCollection('MODIS/061/MOD44B')
    # Seleccionar una imagen de un año específico y la banda 'Percent_Tree_Cover'
    # Para este ejemplo, tomaremos la del 2015, que es común en el dataset
    tree_cover_image = modis_tree_cover.filterDate('2015-01-01', '2015-12-31').select('Percent_Tree_Cover').first()
    tree_cover_quebrada_honda = tree_cover_image.clip(roi_quebrada_honda)

    print('Imagen de Cobertura Arbórea MODIS recortada para Quebrada la Honda.')
else:
    print('Error: `roi_quebrada_honda` no está definida. No se puede cargar la cobertura arbórea.')
    tree_cover_quebrada_honda = None


if roi_quebrada_honda is not None and tree_cover_quebrada_honda is not None:
    # 3. Definir umbrales de cobertura arbórea con colores
    tree_cover_thresholds = [
        {'clase': 1, 'nombre': 'Sin Cobertura', 'rango': '0-10%', 'min': 0, 'max': 10, 'color': '#fef0d9'}, # Amarillo muy claro
        {'clase': 2, 'nombre': 'Cobertura Escasa', 'rango': '10-40%', 'min': 10, 'max': 40, 'color': '#fc8d59'}, # Naranja
        {'clase': 3, 'nombre': 'Cobertura Moderada', 'rango': '40-70%', 'min': 40, 'max': 70, 'color': '#91cf60'}, # Verde claro
        {'clase': 4, 'nombre': 'Cobertura Densa', 'rango': '> 70%', 'min': 70, 'max': 100, 'color': '#1a9641'} # Verde oscuro
    ]

    # 4. Reclasificar la imagen de cobertura arbórea basada en los umbrales
    reclassified_tree_cover = ee.Image(0).rename('Tree_Cover_Level')
    for i, threshold in enumerate(tree_cover_thresholds):
        lower_bound = threshold['min']
        upper_bound = threshold['max']
        class_value = i + 1 # Asignar 1, 2, 3, 4 como valores de clase

        if upper_bound == 100: # Para la última clase (>= 70%)
            condition = tree_cover_quebrada_honda.gte(lower_bound)
        else:
            condition = tree_cover_quebrada_honda.gte(lower_bound).And(tree_cover_quebrada_honda.lt(upper_bound))

        reclassified_tree_cover = reclassified_tree_cover.where(condition, ee.Image(class_value))

    print('Imagen de Cobertura Arbórea Reclasificada para Quebrada la Honda.')

    # 5. Crear el mapa Folium
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']
    m_tree_cover_levels = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # Definir parámetros de visualización para la cobertura arbórea reclasificada
    reclassified_tree_cover_vis = {
      'min': 1,
      'max': len(tree_cover_thresholds),
      'palette': [t['color'] for t in tree_cover_thresholds]
    }

    map_id_reclassified_tree_cover = reclassified_tree_cover.getMapId(reclassified_tree_cover_vis)

    folium.TileLayer(
        tiles=map_id_reclassified_tree_cover['tile_fetcher'].url_format,
        attr='Google Earth Engine - Cobertura Arbórea Reclasificada',
        overlay=True,
        name='Niveles de Cobertura Arbórea'
    ).add_to(m_tree_cover_levels)

    # Añadir el límite de la cuenca
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_tree_cover_levels)

    # Añadir control de capas
    m_tree_cover_levels.add_child(folium.LayerControl())

    # Añadir leyenda personalizada para los niveles de cobertura arbórea
    legend_html_tree_cover =   '''
                            <div style="position: fixed;
                                        bottom: 50px; left: 50px; width: 200px; height: auto;
                                        border:2px solid grey; z-index:9999; font-size:14px;
                                        background-color:white; opacity:0.9; padding:10px;">
                              <h4 style="margin-top:0;">Niveles de Cobertura Arbórea</h4>
                              <ul style="list-style:none; padding:0;">
                            '''
    for threshold in tree_cover_thresholds:
        legend_html_tree_cover += f'''
                                <li style="display:flex; align-items:center; margin-bottom:5px;">
                                  <span style="background:{threshold['color']}; width:20px; height:15px; display:inline-block; margin-right:5px; border:1px solid black;"></span>
                                  <span>{threshold['clase']} ({threshold['rango']})</span>
                                </li>
                            '''
    legend_html_tree_cover +=  '''
                              </ul>
                            </div>
                            '''
    m_tree_cover_levels.get_root().html.add_child(folium.Element(legend_html_tree_cover))

    display(m_tree_cover_levels)
    print('\nMapa interactivo de Niveles de Cobertura Arbórea con leyenda completado.')
else:
    print('Error crítico: No se pudieron asegurar todas las variables necesarias para generar el mapa de cobertura arbórea.')

"""Estos umbrales proporcionan una base para clasificar y analizar las variables ambientales de manera más estructurada, facilitando la identificación de zonas con características específicas para la toma de decisiones."""

import ee
import pandas as pd

print('Recalculando Frecuencia y Área por Clase de Pendiente para Quebrada la Honda...')

if 'reclassified_slope_quebrada_honda' in locals() and reclassified_slope_quebrada_honda is not None and \
   'roi_quebrada_honda' in locals() and roi_quebrada_honda is not None:

    # Definir el reducer para obtener el histograma de las clases
    reducer_hist_qh = ee.Reducer.frequencyHistogram()

    # Reducir la región para obtener el histograma (usando la geometría de la cuenca)
    slope_class_counts_qh = reclassified_slope_quebrada_honda.reduceRegion(**{
        'reducer': reducer_hist_qh,
        'geometry': roi_quebrada_honda,
        'scale': 10, # Usar una escala más fina (10m) para mayor precisión dentro de la cuenca pequeña
        'maxPixels': 1e13,
        'bestEffort': True
    })

    histogram_data_qh = slope_class_counts_qh.getInfo().get('slope_class')

    if histogram_data_qh:
        frequency_df_slope_qh = pd.DataFrame(histogram_data_qh.items(), columns=['Clase de Pendiente', 'Número de Píxeles'])
        frequency_df_slope_qh['Clase de Pendiente'] = frequency_df_slope_qh['Clase de Pendiente'].astype(int)
        frequency_df_slope_qh = frequency_df_slope_qh.sort_values(by='Clase de Pendiente').reset_index(drop=True)

        total_pixels_slope_qh = frequency_df_slope_qh['Número de Píxeles'].sum()
        frequency_df_slope_qh['Porcentaje (%)'] = (frequency_df_slope_qh['Número de Píxeles'] / total_pixels_slope_qh * 100).round(2)

        # Calcular el área en m² y ha usando la misma lógica que para Colombia
        total_image_area_sq_m_qh = reclassified_slope_quebrada_honda.pixelArea().reduceRegion(**{
            'reducer': ee.Reducer.sum(),
            'geometry': roi_quebrada_honda,
            'scale': 10, # Misma escala
            'maxPixels': 1e13,
            'bestEffort': True
        }).getInfo().get('area')

        if total_image_area_sq_m_qh is None:
            print("Error: No se pudo calcular el área total de la imagen reclasificada para Quebrada la Honda.")
        else:
            pixel_area_sq_m_qh = total_image_area_sq_m_qh / total_pixels_slope_qh
            frequency_df_slope_qh['Área (m²)'] = frequency_df_slope_qh['Número de Píxeles'] * pixel_area_sq_m_qh
            frequency_df_slope_qh['Área (ha)'] = frequency_df_slope_qh['Área (m²)'] / 10000

            print("Frecuencia y Área por clase de pendiente para Quebrada la Honda:")
            display(frequency_df_slope_qh.round(2))
    else:
        print("No se pudieron calcular las frecuencias de píxeles para las clases de pendiente en Quebrada la Honda.")
else:
    print('Error: Variables necesarias (reclassified_slope_quebrada_honda o roi_quebrada_honda) no están definidas.')

"""### Análisis de Regresión Lineal: Cobertura Arbórea vs. Altitud

Vamos a investigar la relación entre la cobertura arbórea y la altitud en la cuenca 'Quebrada la Honda' mediante un análisis de regresión lineal. Esto nos permitirá cuantificar cómo la altitud influye en la distribución de la cobertura arbórea y visualizar esta tendencia.
"""

import ee
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.linear_model import LinearRegression
from sklearn.metrics import r2_score
import numpy as np

# Asegurarse de que `roi_quebrada_honda`, `dem_quebrada_honda` y `tree_cover_quebrada_honda` estén definidos
if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca (`roi_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'dem_quebrada_honda' not in locals() or dem_quebrada_honda is None:
    print('Error: La imagen DEM recortada para Quebrada la Honda (`dem_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'tree_cover_quebrada_honda' not in locals() or tree_cover_quebrada_honda is None:
    print('Error: La imagen de cobertura arbórea (`tree_cover_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
else:
    # 1. Renombrar las bandas para una fácil referencia
    altitude_band = dem_quebrada_honda.rename('Altitude_m')
    tree_cover_band = tree_cover_quebrada_honda.rename('Tree_Cover_Percent')

    # Obtener la escala y CRS de la imagen de cobertura arbórea (la más fina)
    # Aseguramos que ambas imágenes tengan la misma proyección y escala antes de combinarlas.
    target_scale = tree_cover_band.projection().nominalScale().getInfo()
    target_crs = tree_cover_band.projection().crs().getInfo()

    print(f"Escala nominal de Altitud: {altitude_band.projection().nominalScale().getInfo()} metros")
    print(f"Escala nominal de Cobertura Arbórea: {tree_cover_band.projection().nominalScale().getInfo()} metros")
    print(f"Escala objetivo para el análisis: {target_scale} metros")

    # Reproyectar ambas imágenes a la escala y CRS objetivo.
    altitude_band_reprojected = altitude_band.reproject(
        crs=target_crs,
        scale=target_scale
    ).setDefaultProjection(crs=target_crs, scale=target_scale)

    tree_cover_band_reprojected = tree_cover_band.reproject(
        crs=target_crs,
        scale=target_scale
    ).setDefaultProjection(crs=target_crs, scale=target_scale)

    # Combinar las dos bandas en una sola imagen.
    combined_image_regression = altitude_band_reprojected.addBands(tree_cover_band_reprojected)

    # 2. Extraer valores de píxeles para el análisis (muestra aleatoria)
    sample_points_regression = combined_image_regression.sample(
        region=roi_quebrada_honda,
        scale=target_scale,
        numPixels=2000, # Aumentar el número de píxeles para una mejor representación
        seed=42, # Para reproducibilidad
        dropNulls=True
    )

    # Convertir los puntos muestreados a un DataFrame de Pandas
    sample_list_regression = sample_points_regression.getInfo()['features']
    data_for_regression = []
    for feature in sample_list_regression:
        props = feature['properties']
        altitude = props.get('Altitude_m')
        tree_cover = props.get('Tree_Cover_Percent')
        # Solo añadir si ambos valores son válidos (no None y no NaN)
        if altitude is not None and not pd.isna(altitude) and \
           tree_cover is not None and not pd.isna(tree_cover):
            data_for_regression.append({
                'Altitud (m)': altitude,
                'Cobertura Arbórea (%)': tree_cover
            })

    regression_df = pd.DataFrame(data_for_regression)

    if not regression_df.empty:
        # 3. Preparar los datos para la regresión lineal
        X = regression_df[['Altitud (m)']].values  # Variable independiente (debe ser 2D)
        y = regression_df['Cobertura Arbórea (%)'].values # Variable dependiente

        # 4. Crear y entrenar el modelo de regresión lineal
        model = LinearRegression()
        model.fit(X, y)

        # 5. Obtener los resultados del modelo
        intercept = model.intercept_
        slope = model.coef_[0]
        y_pred = model.predict(X)
        r_squared = r2_score(y, y_pred)

        print('\nResultados de la Regresión Lineal (Cobertura Arbórea ~ Altitud):')
        print(f'  Intercepto: {intercept:.2f}')
        print(f'  Pendiente (coeficiente de altitud): {slope:.2f}')
        print(f'  Coeficiente R-cuadrado (R²): {r_squared:.2f}')

        # 6. Visualizar los resultados
        plt.figure(figsize=(10, 7))
        sns.scatterplot(x='Altitud (m)', y='Cobertura Arbórea (%)', data=regression_df, alpha=0.6, edgecolor='w', s=50, color='darkgreen')
        plt.plot(X, y_pred, color='red', linewidth=2, label=f'Línea de Regresión (y = {slope:.2f}x + {intercept:.2f})')
        plt.title('Regresión Lineal: Cobertura Arbórea vs. Altitud en Quebrada la Honda')
        plt.xlabel('Altitud (m)')
        plt.ylabel('Cobertura Arbórea (%)')
        plt.grid(True, linestyle='--', alpha=0.7)
        plt.legend()
        plt.show()

        print('\nAnálisis de regresión lineal completado.')
    else:
        print('No hay datos suficientes en la muestra para realizar el análisis de regresión.')

"""### Mapa Interactivo Combinado: Riesgo de Suelo (Pendiente) y Cobertura Arbórea

Este mapa interactivo te permite visualizar simultáneamente las clases de riesgo de suelo (pendientes) y la cobertura arbórea en la cuenca 'Quebrada la Honda'.

**Instrucciones:**
*   Usa el icono de capas (generalmente en la esquina superior derecha) para activar/desactivar las capas de 'Clases de Riesgo de Suelo (Pendiente)' y 'Cobertura Arbórea'.
*   La capa 'Límite de Cuenca' siempre estará visible para referencia.
"""

import ee
import folium

# Asegurarse de que `reclassified_slope_quebrada_honda`, `tree_cover_quebrada_honda`,
# `roi_quebrada_honda` y `watershed_gdf` estén definidos
if 'reclassified_slope_quebrada_honda' not in locals() or reclassified_slope_quebrada_honda is None:
    print('Error: La imagen de pendiente reclasificada (`reclassified_slope_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'tree_cover_quebrada_honda' not in locals() or tree_cover_quebrada_honda is None:
    print('Error: La imagen de cobertura arbórea (`tree_cover_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'watershed_gdf' not in locals() or watershed_gdf is None:
    print('Error: El GeoDataFrame de la cuenca (`watershed_gdf`) no está disponible. Por favor, ejecuta las celdas anteriores.')
else:
    # Parámetros de visualización para las clases de pendiente (riesgos de suelo)
    slope_risk_vis = {
      'min': 1,
      'max': 5,
      'palette': ['#d7191c', '#fdae61', '#ffffbf', '#a6d96a', '#1a9641'] # Colores de alto riesgo (rojo) a bajo riesgo (verde)
    }

    # Parámetros de visualización para la Cobertura Arbórea
    tree_cover_vis = {
      'min': 0,
      'max': 100,
      'palette': ['red', 'orange', 'yellow', 'lightgreen', 'green', 'darkgreen'] # De bajo a alto porcentaje de cobertura
    }

    # Obtener el centroide de la cuenca para centrar el mapa
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    # Crear un mapa Folium base
    m_combined_risk_tree = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # 1. Añadir la capa de Clases de Riesgo de Suelo (Pendiente)
    map_id_slope_risk = ee.Image(reclassified_slope_quebrada_honda).getMapId(slope_risk_vis)
    folium.TileLayer(
        tiles=map_id_slope_risk['tile_fetcher'].url_format,
        attr='Google Earth Engine - Clases de Pendiente (Riesgo de Suelo)',
        overlay=True,
        name='Clases de Riesgo de Suelo (Pendiente)',
        show=True # Visible por defecto
    ).add_to(m_combined_risk_tree)

    # 2. Añadir la capa de Cobertura Arbórea
    map_id_tree_cover = ee.Image(tree_cover_quebrada_honda).getMapId(tree_cover_vis)
    folium.TileLayer(
        tiles=map_id_tree_cover['tile_fetcher'].url_format,
        attr='Google Earth Engine - Cobertura Arbórea',
        overlay=True,
        name='Cobertura Arbórea (%)',
        show=False # Inicialmente oculto
    ).add_to(m_combined_risk_tree)

    # 3. Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_combined_risk_tree)

    # 4. Añadir control de capas
    m_combined_risk_tree.add_child(folium.LayerControl())

    display(m_combined_risk_tree)
    print('\nMapa interactivo combinado de riesgo de suelo y cobertura arbórea completado.')

"""### Correlación entre el Riesgo de Suelo (Clases de Pendiente) y la Cobertura Arbórea

Vamos a cuantificar la relación entre las clases de riesgo de suelo (pendientes) y la cobertura arbórea. Esto nos ayudará a entender si las áreas con mayor riesgo de erosión (pendientes más pronunciadas) tienden a tener menor o mayor cobertura vegetal.
"""

import ee
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np

# Asegurarse de que `roi_quebrada_honda`, `reclassified_slope_quebrada_honda` y `tree_cover_quebrada_honda` estén definidos
if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca (`roi_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'reclassified_slope_quebrada_honda' not in locals() or reclassified_slope_quebrada_honda is None:
    print('Error: La imagen de pendiente reclasificada (`reclassified_slope_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'tree_cover_quebrada_honda' not in locals() or tree_cover_quebrada_honda is None:
    print('Error: La imagen de cobertura arbórea (`tree_cover_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
else:
    # 1. Renombrar las bandas para una fácil referencia
    slope_class_band = reclassified_slope_quebrada_honda.rename('Slope_Class')
    tree_cover_band = tree_cover_quebrada_honda.rename('Tree_Cover_Percent')

    # Obtener la escala y CRS de la imagen de cobertura arbórea (la más fina)
    # Aseguramos que ambas imágenes tengan la misma proyección y escala antes de combinarlas para la correlación.
    target_scale = tree_cover_band.projection().nominalScale().getInfo()
    target_crs = tree_cover_band.projection().crs().getInfo()

    # Reproyectar ambas imágenes a la escala y CRS objetivo.
    slope_class_band_reprojected = slope_class_band.reproject(
        crs=target_crs,
        scale=target_scale
    ).setDefaultProjection(crs=target_crs, scale=target_scale)

    tree_cover_band_reprojected = tree_cover_band.reproject(
        crs=target_crs,
        scale=target_scale
    ).setDefaultProjection(crs=target_crs, scale=target_scale)

    # Combinar las dos bandas en una sola imagen.
    combined_image_correlation_risk_tree = slope_class_band_reprojected.addBands(tree_cover_band_reprojected)

    # 2. Calcular el coeficiente de correlación de Pearson entre las dos bandas
    correlation_result_risk_tree = combined_image_correlation_risk_tree.reduceRegion(**{
        'reducer': ee.Reducer.pearsonsCorrelation(),
        'geometry': roi_quebrada_honda,
        'scale': target_scale, # Usar la escala común
        'maxPixels': 1e9, # Mantener maxPixels alto para reduceRegion
        'bestEffort': True
    })

    # Obtener el coeficiente de correlación de Pearson
    pearson_correlation_risk_tree = correlation_result_risk_tree.getInfo()

    r_value_risk_tree = pearson_correlation_risk_tree.get('correlation')
    p_value_risk_tree = pearson_correlation_risk_tree.get('p_value')

    print(f'\nCoeficiente de Correlación de Pearson entre Clases de Pendiente y Cobertura Arbórea:')
    if isinstance(r_value_risk_tree, (int, float)) and not pd.isna(r_value_risk_tree):
        r_value_risk_tree_formatted = float(r_value_risk_tree)
        print(f'  R: {r_value_risk_tree_formatted:.2f}')
    else:
        print(f'  R: {r_value_risk_tree}')

    if isinstance(p_value_risk_tree, (int, float)) and not pd.isna(p_value_risk_tree):
        p_value_risk_tree_formatted = float(p_value_risk_tree)
        print(f'  P-valor: {p_value_risk_tree_formatted:.3f}')
    else:
        print(f'  P-valor: {p_value_risk_tree}')

    # 3. Extraer valores de píxeles para el scatter plot (muestra aleatoria)
    sample_points_risk_tree = combined_image_correlation_risk_tree.sample(
        region=roi_quebrada_honda,
        scale=target_scale,
        numPixels=1000,
        seed=1, # Usar una semilla diferente para este muestreo
        dropNulls=True
    )

    # Convertir los puntos muestreados a un DataFrame de Pandas
    sample_list_risk_tree = sample_points_risk_tree.getInfo()['features']
    data_for_scatter_risk_tree = []
    for feature in sample_list_risk_tree:
        props = feature['properties']
        slope_class = props.get('Slope_Class')
        tree_cover = props.get('Tree_Cover_Percent')
        if slope_class is not None and not pd.isna(slope_class) and \
           tree_cover is not None and not pd.isna(tree_cover):
            data_for_scatter_risk_tree.append({
                'Clase de Pendiente': slope_class,
                'Cobertura Arbórea (%)': tree_cover
            })

    correlation_df_risk_tree = pd.DataFrame(data_for_scatter_risk_tree)

    # 4. Visualizar la relación en un gráfico de dispersión
    if not correlation_df_risk_tree.empty:
        plt.figure(figsize=(10, 7))
        sns.scatterplot(
            x='Clase de Pendiente',
            y='Cobertura Arbórea (%)',
            data=correlation_df_risk_tree,
            alpha=0.6,
            edgecolor='w',
            s=50,
            hue='Clase de Pendiente', # Color por clase de pendiente
            palette='viridis' # Una paleta adecuada para valores categóricos/ordinales
        )
        plt.title('Dispersión: Clase de Pendiente vs. Cobertura Arbórea en Quebrada la Honda')
        plt.xlabel('Clase de Pendiente')
        plt.ylabel('Cobertura Arbórea (%)')
        plt.xticks(ticks=sorted(correlation_df_risk_tree['Clase de Pendiente'].unique())) # Mostrar ticks para cada clase
        plt.grid(True, linestyle='--', alpha=0.7)

        if r_value_risk_tree_formatted is not None:
            plt.text(0.05, 0.95, f'Coeficiente de Pearson (R): {r_value_risk_tree_formatted:.2f}', transform=plt.gca().transAxes, fontsize=12, verticalalignment='top')
        else:
            plt.text(0.05, 0.95, f'Coeficiente de Pearson (R): {r_value_risk_tree}', transform=plt.gca().transAxes, fontsize=12, verticalalignment='top')

        plt.show()
    else:
        print('No hay datos suficientes en la muestra para generar el gráfico de dispersión.')

    print('\nAnálisis de correlación entre riesgo de suelo (pendiente) y cobertura arbórea completado.')

if 'correlation_df_risk_tree' in locals() and correlation_df_risk_tree is not None:
    print('Resumen estadístico de correlation_df_risk_tree:')
    display(correlation_df_risk_tree.describe().round(2))
else:
    print('Error: El DataFrame `correlation_df_risk_tree` no está disponible. Asegúrate de que las celdas previas que lo generan se hayan ejecutado correctamente.')

