"""### Distribución de Área por Clases de Riesgo de Suelo (Pendiente)

A continuación, se muestra la distribución del área en hectáreas para cada clase de riesgo de suelo (pendiente) dentro de la cuenca 'Quebrada la Honda'.
"""

import ee
import pandas as pd

print('Recalculando Frecuencia y Área por Clase de Pendiente para Quebrada la Honda...')

if 'reclassified_slope_quebrada_honda' in locals() and reclassified_slope_quebrada_honda is not None and \
   'roi_quebrada_honda' in locals() and roi_quebrada_honda is not None:

    # Definir el reducer para obtener el histograma de las clases
    reducer_hist_qh = ee.Reducer.frequencyHistogram()

    # Reducir la región para obtener el histograma (usando la geometría de la cuenca)
    slope_class_counts_qh = reclassified_slope_quebrada_honda.reduceRegion(**{
        'reducer': reducer_hist_qh,
        'geometry': roi_quebrada_honda,
        'scale': 10, # Usar una escala más fina (10m) para mayor precisión dentro de la cuenca pequeña
        'maxPixels': 1e13,
        'bestEffort': True
    })

    histogram_data_qh = slope_class_counts_qh.getInfo().get('slope_class')

    if histogram_data_qh:
        frequency_df_slope_qh = pd.DataFrame(histogram_data_qh.items(), columns=['Clase de Pendiente', 'Número de Píxeles'])
        frequency_df_slope_qh['Clase de Pendiente'] = frequency_df_slope_qh['Clase de Pendiente'].astype(int)
        frequency_df_slope_qh = frequency_df_slope_qh.sort_values(by='Clase de Pendiente').reset_index(drop=True)

        total_pixels_slope_qh = frequency_df_slope_qh['Número de Píxeles'].sum()
        frequency_df_slope_qh['Porcentaje (%)'] = (frequency_df_slope_qh['Número de Píxeles'] / total_pixels_slope_qh * 100).round(2)

        # Calcular el área en m² y ha usando la misma lógica que para Colombia
        total_image_area_sq_m_qh = reclassified_slope_quebrada_honda.pixelArea().reduceRegion(**{
            'reducer': ee.Reducer.sum(),
            'geometry': roi_quebrada_honda,
            'scale': 10, # Misma escala
            'maxPixels': 1e13,
            'bestEffort': True
        }).getInfo().get('area')

        if total_image_area_sq_m_qh is None:
            print("Error: No se pudo calcular el área total de la imagen reclasificada para Quebrada la Honda.")
        else:
            # Si watershed_area_sq_m está disponible, la usamos para consistencia con cálculos previos
            if 'watershed_area_sq_m' in locals() and watershed_area_sq_m is not None:
                # Usar el área total de la cuenca para calcular el área por píxel
                pixel_area_sq_m_qh = watershed_area_sq_m / total_pixels_slope_qh
            else:
                # Si no, usar la estimación del pixelArea de Earth Engine
                pixel_area_sq_m_qh = total_image_area_sq_m_qh / total_pixels_slope_qh

            frequency_df_slope_qh['Área (m²)'] = frequency_df_slope_qh['Número de Píxeles'] * pixel_area_sq_m_qh
            frequency_df_slope_qh['Área (ha)'] = frequency_df_slope_qh['Área (m²)'] / 10000

            print("Frecuencia y Área por clase de pendiente para Quebrada la Honda:")
            display(frequency_df_slope_qh.round(2))
    else:
        print("No se pudieron calcular las frecuencias de píxeles para las clases de pendiente en Quebrada la Honda.")
else:
    print('Error: Variables necesarias (reclassified_slope_quebrada_honda o roi_quebrada_honda) no están definidas.')

display(frequency_df_slope_qh.round(2))

display(frequency_df_slope_qh.round(2))

"""### Carga y Preparación de la Red Hídrica"""

import zipfile
import os
import geopandas as gpd

zip_file_path_rivers = '/content/rivers.zip'
unzip_dir_rivers = '/content/rivers_extracted'

# Create the directory if it doesn't exist
os.makedirs(unzip_dir_rivers, exist_ok=True)

# Unzip the file
try:
    with zipfile.ZipFile(zip_file_path_rivers, 'r') as zip_ref:
        zip_ref.extractall(unzip_dir_rivers)
    print(f"Archivo '{zip_file_path_rivers}' descomprimido en '{unzip_dir_rivers}'.")

    # Identify the .shp file within the unzipped directory
    shp_file_rivers = None
    for root, dirs, files in os.walk(unzip_dir_rivers):
        for file in files:
            if file.endswith('.shp'):
                shp_file_rivers = os.path.join(root, file)
                break
        if shp_file_rivers:
            break

    if shp_file_rivers:
        # Load the Shapefile into a GeoDataFrame
        try:
            rivers_gdf = gpd.read_file(shp_file_rivers)
            print('\nShapefile de la red hídrica cargado exitosamente en un GeoDataFrame:')
            display(rivers_gdf.head())
            print(f'Sistema de Coordenadas (CRS): {rivers_gdf.crs}')
            print(f'Número de geometrías: {len(rivers_gdf)}')
        except Exception as e:
            print(f'Error al cargar el Shapefile de ríos: {e}')
    else:
        print(f'Error: No se encontró ningún archivo .shp en el directorio {unzip_dir_rivers}.')

except FileNotFoundError:
    print(f"Error: El archivo '{zip_file_path_rivers}' no se encontró. Asegúrate de que el archivo esté presente en la ruta especificada.")
except Exception as e:
    print(f"Ocurrió un error inesperado al descomprimir o cargar el archivo de ríos: {e}")

import ee

# Asegurarse de que `rivers_gdf` esté disponible
if 'rivers_gdf' in locals() and rivers_gdf is not None and not rivers_gdf.empty:
    # Convertir rivers_gdf a EPSG:4326 (si no lo está ya) para compatibilidad con Earth Engine
    rivers_gdf_wgs84 = rivers_gdf.to_crs(epsg=4326)

    # Convertir el GeoDataFrame a una ee.FeatureCollection
    ee_rivers = ee.FeatureCollection(rivers_gdf_wgs84.__geo_interface__)

    print('GeoDataFrame `rivers_gdf` convertido a `ee.FeatureCollection` exitosamente:')
    print(ee_rivers.limit(5).getInfo()) # Mostrar los primeros 5 elementos para verificar
else:
    print('Error: `rivers_gdf` no está disponible o está vacío. Asegúrate de cargarlo en una celda previa.')

