import folium

# Asegurarse de que `dem_quebrada_honda`, `rivers_gdf`, `water_mask_quebrada_honda`,
# `roi_quebrada_honda` y `watershed_gdf` estén definidos
if 'dem_quebrada_honda' not in locals() or dem_quebrada_honda is None:
    print('Error: La imagen DEM recortada para Quebrada la Honda (`dem_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'rivers_gdf' not in locals() or rivers_gdf is None:
    print('Error: El GeoDataFrame de ríos (`rivers_gdf`) no está disponible. Asegúrate de ejecutar las celdas anteriores.')
elif 'water_mask_quebrada_honda' not in locals() or water_mask_quebrada_honda is None:
    print('Error: La imagen de máscara de agua (`water_mask_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'watershed_gdf' not in locals() or watershed_gdf is None:
    print('Error: El GeoDataFrame de la cuenca (`watershed_gdf`) no está disponible. Por favor, ejecuta las celdas anteriores.')
else:
    # Parámetros de visualización para el DEM
    dem_vis = {
        'min': 0,        # Altitud mínima
        'max': 3000,     # Altitud máxima (ajustar según el rango real de tu DEM)
        'palette': ['#000000', '#555555', '#AAAAAA', '#FFFFFF'] # Escala de grises para el DEM
    }

    # Paleta de colores para las órdenes de corriente (re-definida para robustez)
    colors_rivers = ['#deebf7', '#c6dbef', '#9ecae1', '#6baed6', '#4292c6', '#2171b5', '#084594']

    # Parámetros de visualización para la Máscara de Agua
    water_mask_vis = {
      'min': 0,
      'max': 1,
      'palette': ['#FFFFFF00', 'blue'] # Transparente para tierra (0), azul para agua (1)
    }

    # Obtener el centroide de la cuenca para centrar el mapa (reutilizamos centroid_quebrada_honda)
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    # Crear un mapa Folium base
    m_combined_water = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # 1. Añadir la capa del DEM como base o capa de fondo
    map_id_dem = ee.Image(dem_quebrada_honda).getMapId(dem_vis)
    folium.TileLayer(
        tiles=map_id_dem['tile_fetcher'].url_format,
        attr='Google Earth Engine - DEM',
        overlay=True,
        name='DEM de Altitud',
        show=True # Visible por defecto
    ).add_to(m_combined_water)

    # 2. Añadir la capa de Red Hídrica por Orden de Corriente
    folium.GeoJson(
        rivers_gdf.to_json(),
        name='Red Hídrica por Orden de Corriente',
        style_function=lambda x: {
            'color': colors_rivers[x['properties']['sorder'] - 1] if x['properties']['sorder'] <= len(colors_rivers) else 'black',
            'weight': x['properties']['sorder'] * 0.75,
            'tooltip': f"Orden de Corriente: {x['properties']['sorder']}"
        },
        tooltip=folium.GeoJsonTooltip(fields=['sorder'], aliases=['Orden de Corriente:'], localize=True),
        popup=folium.GeoJsonPopup(fields=['sorder'], aliases=['Orden de Corriente:'], localize=True)
    ).add_to(m_combined_water)

    # 3. Añadir la capa de Máscara de Agua (MODIS)
    map_id_water_mask = water_mask_quebrada_honda.getMapId(water_mask_vis)
    folium.TileLayer(
        tiles=map_id_water_mask['tile_fetcher'].url_format,
        attr='Google Earth Engine - MODIS Water Mask',
        overlay=True,
        name='Máscara de Agua (MODIS)',
        show=False # Inicialmente oculto
    ).add_to(m_combined_water)

    # 4. Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_combined_water)

    # 5. Añadir control de capas
    m_combined_water.add_child(folium.LayerControl())

    display(m_combined_water)
    print('\nMapa interactivo combinado de DEM, red hídrica y máscara de agua completado.')

