"""### Leyenda Interactiva para Mapas Combinados

A continuación, se añade una leyenda interactiva al último mapa combinado (`m_combined_dem_prec_tree_new_colors`). Esta leyenda te permitirá interpretar los colores de las capas de DEM de Altitud, Precipitación Media y Cobertura Arbórea.

*   **DEM de Altitud:** Escala de colores azules, de 0 a 3000 metros.
*   **Precipitación Media:** Escala de colores azules claros a oscuros, de 0 a 10 mm.
*   **Cobertura Arbórea:** Escala de colores verdes claros a oscuros, de 0 a 100%.

### Re-inicialización de variables para la visualización del mapa combinado

Debido a que algunas variables necesarias para el mapa combinado (DEM, precipitación y cobertura arbórea) no estaban definidas o no estaban actualizadas, las redefiniremos para asegurar la correcta visualización del mapa.

### Regeneración de Variables Clave para el Mapa Combinado

Para asegurar que todas las capas del mapa combinado se visualicen correctamente y que la leyenda funcione sin errores, vamos a re-inicializar Earth Engine y cargar de nuevo las variables esenciales (DEM, precipitación, cobertura arbórea) y la geometría de la cuenca.
"""

import ee
import folium
import geopandas as gpd
import os

# Re-inicializar Earth Engine para asegurar el contexto
ee.Initialize(project='studious-camp-486620-m3')

# 1. Cargar watershed_gdf (si no está ya cargado)
# Se asume que '/content/watershed.zip' existe y ya se descomprimió.
# Si no, esta parte necesitaría un manejo de errores o carga explícita del zip.
zip_file_path = '/content/watershed.zip'
unzip_dir = '/content/watershed_extracted'
shp_file_path = os.path.join(unzip_dir, 'watershed.shp')

try:
    # Verificar si ya está descomprimido y cargado, si no, hacerlo.
    if 'watershed_gdf' not in locals() or watershed_gdf is None or watershed_gdf.empty:
        if not os.path.exists(shp_file_path):
            # Si el shp no existe, intenta descomprimir
            os.makedirs(unzip_dir, exist_ok=True)
            with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:
                zip_ref.extractall(unzip_dir)
            print(f"Archivo '{zip_file_path}' descomprimido en '{unzip_dir}'.")
        watershed_gdf = gpd.read_file(shp_file_path)
        print('Shapefile de la cuenca cargado exitosamente en un GeoDataFrame.')
    else:
        print('watershed_gdf ya está disponible.')
except Exception as e:
    print(f"Error al cargar watershed_gdf: {e}")
    watershed_gdf = None


# 2. Definir roi_quebrada_honda y centroid_quebrada_honda
if watershed_gdf is not None and not watershed_gdf.empty:
    roi_quebrada_honda = ee.Geometry(watershed_gdf.geometry.iloc[0].__geo_interface__)
    centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']
    print(f'ROI de Quebrada la Honda definida. Centroide: ({lon_qh}, {lat_qh})')
else:
    print('Error: watershed_gdf no está disponible o está vacío, no se puede definir roi_quebrada_honda.')
    roi_quebrada_honda = None


# 3. Cargar y recortar el DEM
if roi_quebrada_honda is not None:
    hydrosheds_dem_image = ee.Image('WWF/HydroSHEDS/03VFDEM')
    dem_quebrada_honda = hydrosheds_dem_image.clip(roi_quebrada_honda)
    print('DEM de HydroSHEDS recortado para Quebrada la Honda.')
else:
    print('Error: roi_quebrada_honda no está definida, no se puede cargar el DEM.')
    dem_quebrada_honda = None


# 4. Cargar y recortar la precipitación media
if roi_quebrada_honda is not None:
    new_start_date_analysis = '2020-01-01'
    new_end_date_analysis = '2035-12-31'
    chirps_daily_analysis = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')\
                                      .filterDate(new_start_date_analysis, new_end_date_analysis)
    mean_precipitation_analysis = chirps_daily_analysis.select('precipitation').mean().rename('mean_precipitation_2020_2035')
    precipitation_quebrada_honda_analysis = mean_precipitation_analysis.clip(roi_quebrada_honda)
    print(f'Imagen de precipitación media recortada para Quebrada la Honda ({new_start_date_analysis} a {new_end_date_analysis}).')
else:
    print('Error: roi_quebrada_honda no está definida, no se puede cargar la precipitación.')
    precipitation_quebrada_honda_analysis = None


# 5. Cargar y recortar la cobertura arbórea
if roi_quebrada_honda is not None:
    modis_tree_cover = ee.ImageCollection('MODIS/061/MOD44B')
    tree_cover_image = modis_tree_cover.filterDate('2015-01-01', '2015-12-31').select('Percent_Tree_Cover').first()
    tree_cover_quebrada_honda = tree_cover_image.clip(roi_quebrada_honda)
    print('Imagen de Cobertura Arbórea MODIS recortada para Quebrada la Honda.')
else:
    print('Error: roi_quebrada_honda no está definida, no se puede cargar la cobertura arbórea.')
    tree_cover_quebrada_honda = None

"""### Mapa Interactivo Combinado: DEM, Precipitación y Cobertura Arbórea (con leyenda corregida)

Este mapa interactivo te permite visualizar simultáneamente el Modelo de Elevación Digital (DEM), la precipitación media y la cobertura arbórea en la cuenca 'Quebrada la Honda'. Además, incluye una leyenda interactiva para facilitar la interpretación de los colores en cada capa.
"""

