if all(x is not None for x in [dem_quebrada_honda, precipitation_quebrada_honda_analysis,
                               tree_cover_quebrada_honda, roi_quebrada_honda, watershed_gdf]):

    # Parámetros de visualización para el DEM (tonos azules)
    dem_vis = {
        'min': 0,
        'max': 3000,
        'palette': ['#e0f2f7', '#a7d9ed', '#72c1e4', '#42a7d7', '#1a8ac7', '#08639e'] # Azules claros a oscuros para elevación
    }

    # Parámetros de visualización para la Precipitación (tonos azules)
    precipitation_vis = {
      'min': 0,
      'max': 10,
      'palette': ['#f0f8ff', '#d6e9f6', '#acd8f1', '#83c2e7', '#56a7db', '#2f8acd'] # Azules claros a oscuros para precipitación
    }

    # Parámetros de visualización para la Cobertura Arbórea (tonos verdes)
    tree_cover_vis = {
      'min': 0,
      'max': 100,
      'palette': ['#f7fcf5', '#e5f5e0', '#c7e9c0', '#a1d99b', '#74c476', '#41ab5d', '#238b45', '#006d2c', '#00441b'] # Verdes claros a oscuros para cobertura arbórea
    }

    # Obtener el centroide de la cuenca para centrar el mapa
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    # Crear un mapa Folium base
    m_combined_dem_prec_tree_new_colors = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    # 1. Añadir la capa del DEM
    map_id_dem = ee.Image(dem_quebrada_honda).getMapId(dem_vis)
    folium.TileLayer(
        tiles=map_id_dem['tile_fetcher'].url_format,
        attr='Google Earth Engine - DEM (Azules)',
        overlay=True,
        name='DEM de Altitud (Azules)',
        show=True # Visible por defecto
    ).add_to(m_combined_dem_prec_tree_new_colors)

    # 2. Añadir la capa de Precipitación Media
    map_id_prec_qh = ee.Image(precipitation_quebrada_honda_analysis).getMapId(precipitation_vis)
    folium.TileLayer(
        tiles=map_id_prec_qh['tile_fetcher'].url_format,
        attr='Google Earth Engine - Precipitación Media (Azules)',
        overlay=True,
        name='Precipitación Media (mm) (Azules)',
        show=False # Inicialmente oculto
    ).add_to(m_combined_dem_prec_tree_new_colors)

    # 3. Añadir la capa de Cobertura Arbórea
    map_id_tree_cover = ee.Image(tree_cover_quebrada_honda).getMapId(tree_cover_vis)
    folium.TileLayer(
        tiles=map_id_tree_cover['tile_fetcher'].url_format,
        attr='Google Earth Engine - Cobertura Arbórea (Verdes)',
        overlay=True,
        name='Cobertura Arbórea (%) (Verdes)',
        show=False # Inicialmente oculto
    ).add_to(m_combined_dem_prec_tree_new_colors)

    # 4. Añadir el límite de la cuenca para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
    ).add_to(m_combined_dem_prec_tree_new_colors)

    # 5. Añadir control de capas
    m_combined_dem_prec_tree_new_colors.add_child(folium.LayerControl())

    # 6. Función para generar una barra de color HTML
    def get_color_bar_html(title, vmin, vmax, palette, unit):
        colors = palette
        color_stops = ','.join([f'{c} {i * 100 / (len(colors) - 1)}%' for i, c in enumerate(colors)])
        return f'''
        <p style="font-weight: bold; margin-bottom: 5px;">{title}</p>
        <div style="width: 100%; height: 20px; background: linear-gradient(to right, {color_stops});"></div>
        <div style="display: flex; justify-content: space-between; font-size: 0.8em; margin-top: 2px;">
            <span>{vmin}{unit}</span>
            <span>{vmax}{unit}</span>
        </div>
        '''

    # Crear la leyenda HTML combinada
    legend_html_combined = f'''
    <div style="position: fixed;
                bottom: 50px; left: 50px; width: 250px; height: auto;
                border:2px solid grey; z-index:9999; font-size:14px;
                background-color:white; opacity:0.9; padding:10px;">
      <h4 style="margin-top:0;">Leyenda del Mapa</h4>
      {get_color_bar_html('DEM de Altitud', dem_vis['min'], dem_vis['max'], dem_vis['palette'], ' m')}
      <br>
      {get_color_bar_html('Precipitación Media', precipitation_vis['min'], precipitation_vis['max'], precipitation_vis['palette'], ' mm')}
      <br>
      {get_color_bar_html('Cobertura Arbórea', tree_cover_vis['min'], tree_cover_vis['max'], tree_cover_vis['palette'], '%')}
    </div>
    '''

    # Añadir la leyenda al mapa
    m_combined_dem_prec_tree_new_colors.get_root().html.add_child(folium.Element(legend_html_combined))

    display(m_combined_dem_prec_tree_new_colors)
    print('\nMapa interactivo combinado de DEM, precipitación y cobertura arbórea con leyenda completado.')

else:
    print('Error: Faltan variables necesarias para generar el mapa combinado. Asegúrate de que todas las celdas previas se hayan ejecutado correctamente.')

import ee
import geopandas as gpd

# Re-initialize Earth Engine to ensure the context
ee.Initialize(project='studious-camp-486620-m3')

# Ensure `watershed_gdf` is available from previous steps
# (Assuming watershed_gdf was loaded successfully in cell a6320703)
if 'watershed_gdf' not in locals() or watershed_gdf is None or watershed_gdf.empty:
    print('Error: El GeoDataFrame de la cuenca (`watershed_gdf`) no está disponible o está vacío. Asegúrate de ejecutar las celdas anteriores que lo cargan.')
    roi_quebrada_honda = None
else:
    # Convertir la geometría de la cuenca de GeoDataFrame a ee.Geometry
    roi_quebrada_honda = ee.Geometry(watershed_gdf.geometry.iloc[0].__geo_interface__)
    print(f'ROI de Quebrada la Honda creada en Earth Engine: {roi_quebrada_honda.getInfo()}')
    # Get centroid for map centering
    centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

"""#### Cargar y recortar el DEM"""

# Cargar el DEM de HydroSHEDS como ee.Image
hydrosheds_dem_image = ee.Image('WWF/HydroSHEDS/03VFDEM')
# Recortar el DEM a la región de interés de Quebrada la Honda
dem_quebrada_honda = hydrosheds_dem_image.clip(roi_quebrada_honda)

print('DEM de HydroSHEDS recortado para Quebrada la Honda:')
print(dem_quebrada_honda.getInfo())

"""#### Cargar y recortar la precipitación media"""

# Define el rango de fechas para el análisis de precipitación
new_start_date_analysis = '2020-01-01'
new_end_date_analysis = '2035-12-31'

# Cargar la colección de imágenes CHIRPS DAILY y calcular la media
chirps_daily_analysis = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')\
                                  .filterDate(new_start_date_analysis, new_end_date_analysis)
mean_precipitation_analysis = chirps_daily_analysis.select('precipitation').mean().rename('mean_precipitation_2020_2035')

# Recortar la imagen de precipitación a la región de interés de Quebrada la Honda
precipitation_quebrada_honda_analysis = mean_precipitation_analysis.clip(roi_quebrada_honda)

print(f'Imagen de precipitación media para Quebrada la Honda ({new_start_date_analysis} a {new_end_date_analysis}):')
print(precipitation_quebrada_honda_analysis.getInfo())

"""#### Cargar y recortar la cobertura arbórea"""

# Cargar la colección de imágenes MODIS/061/MOD44B (Tree Cover)
modis_tree_cover = ee.ImageCollection('MODIS/061/MOD44B')
# Seleccionar la imagen del año 2015 y la banda 'Percent_Tree_Cover'
tree_cover_image = modis_tree_cover.filterDate('2015-01-01', '2015-12-31').select('Percent_Tree_Cover').first()
# Recortar la imagen de cobertura arbórea a la región de interés
tree_cover_quebrada_honda = tree_cover_image.clip(roi_quebrada_honda)

print('Imagen de Cobertura Arbórea MODIS recortada para Quebrada la Honda:')
print(tree_cover_quebrada_honda.getInfo())

"""### Mapa Interactivo Combinado: DEM, Precipitación y Cobertura Arbórea"""

