# Definir un nivel de olor hipotético para la demostración
# Puedes cambiar este valor para probar diferentes escenarios
nivel_olor_actual = 75 # Escala de 0 (sin olor) a 100 (olor muy fuerte)

# Definir los umbrales para el semáforo de olores
# Estos umbrales son ejemplos y pueden ajustarse según los datos reales de olores

umbral_verde_max = 30 # Nivel de olor hasta 30 se considera bajo (verde)
umbral_amarillo_max = 70 # Nivel de olor entre 31 y 70 se considera medio (amarillo)
# Más de 70 se considera alto (rojo)

print(f"### Semáforo de Olores - Nivel Actual: {nivel_olor_actual} ###\n")

if nivel_olor_actual <= umbral_verde_max:
    estado_olor = "Bajo"
    color_semaforo = "Verde"
    mensaje = "El nivel de olor es bajo. No se requiere acción inmediata."
elif nivel_olor_actual <= umbral_amarillo_max:
    estado_olor = "Medio"
    color_semaforo = "Amarillo"
    mensaje = "El nivel de olor es moderado. Se recomienda monitoreo."
else:
    estado_olor = "Alto"
    color_semaforo = "Rojo"
    mensaje = "El nivel de olor es alto. Se requiere atención y posible intervención."

print(f"Estado del Olor: {estado_olor}")
print(f"Color del Semáforo: {color_semaforo}")
print(f"Mensaje: {mensaje}")

