plt.grid(True, linestyle='--', alpha=0.7)
plt.text(0.05, 0.95, f'Coeficiente de Pearson (R): {r_value_risk_tree_formatted:.2f}', transform=plt.gca().transAxes, fontsize=12, verticalalignment='top')
plt.show()

print('\nGráfico de dispersión de la correlación completado.')

import ee
import pandas as pd

print('Calculando Frecuencia y Área por Nivel de Cobertura Arbórea para Quebrada la Honda...')

# Asegurarse de que `reclassified_tree_cover`, `roi_quebrada_honda` y `watershed_area_sq_m` estén definidos
if 'reclassified_tree_cover' in locals() and reclassified_tree_cover is not None and \
   'roi_quebrada_honda' in locals() and roi_quebrada_honda is not None and \
   'watershed_area_sq_m' in locals() and watershed_area_sq_m is not None:

    # Definir el reducer para obtener el histograma de las clases
    reducer_hist_tc = ee.Reducer.frequencyHistogram()

    # Reducir la región para obtener el histograma (usando la geometría de la cuenca)
    tree_cover_class_counts_qh = reclassified_tree_cover.reduceRegion(**{
        'reducer': reducer_hist_tc,
        'geometry': roi_quebrada_honda,
        'scale': 30, # Usar una escala adecuada para los datos de cobertura arbórea
        'maxPixels': 1e13,
        'bestEffort': True
    })

    histogram_data_tc_qh = tree_cover_class_counts_qh.getInfo().get('Tree_Cover_Level')

    if histogram_data_tc_qh:
        frequency_df_tree_cover_qh = pd.DataFrame(histogram_data_tc_qh.items(), columns=['Nivel de Cobertura Arbórea', 'Número de Píxeles'])
        frequency_df_tree_cover_qh['Nivel de Cobertura Arbórea'] = frequency_df_tree_cover_qh['Nivel de Cobertura Arbórea'].astype(int)
        frequency_df_tree_cover_qh = frequency_df_tree_cover_qh.sort_values(by='Nivel de Cobertura Arbórea').reset_index(drop=True)

        total_pixels_tree_cover_qh = frequency_df_tree_cover_qh['Número de Píxeles'].sum()
        frequency_df_tree_cover_qh['Porcentaje (%)'] = (frequency_df_tree_cover_qh['Número de Píxeles'] / total_pixels_tree_cover_qh * 100).round(2)

        # Calcular el área en m² y ha
        # Usar el área total de la cuenca para calcular el área por píxel
        pixel_area_sq_m_tc_qh = watershed_area_sq_m / total_pixels_tree_cover_qh

        frequency_df_tree_cover_qh['Área (m²)'] = frequency_df_tree_cover_qh['Número de Píxeles'] * pixel_area_sq_m_tc_qh
        frequency_df_tree_cover_qh['Área (ha)'] = frequency_df_tree_cover_qh['Área (m²)'] / 10000

        print('\nFrecuencia y Área por nivel de cobertura arbórea para Quebrada la Honda:')
        display(frequency_df_tree_cover_qh.round(2))

        # Crear un mapa de etiquetas para las clases de cobertura arbórea
        tree_cover_level_labels = {
            1: 'Sin Cobertura (0-10%)',
            2: 'Cobertura Escasa (10-40%)',
            3: 'Cobertura Moderada (40-70%)',
            4: 'Cobertura Densa (> 70%)'
        }
        frequency_df_tree_cover_qh['Clase'] = frequency_df_tree_cover_qh['Nivel de Cobertura Arbórea'].map(tree_cover_level_labels)


    else:
        print('No se pudieron calcular las frecuencias de píxeles para los niveles de cobertura arbórea en Quebrada la Honda.')
else:
    print('Error: Variables necesarias (reclassified_tree_cover, roi_quebrada_honda o watershed_area_sq_m) no están definidas.')

