# --- 7. Crear una Leyenda Combinada ---
def get_threshold_legend_html(title, thresholds, class_key='clase', name_key='nombre', color_key='color'):
    html = f'<p style="font-weight: bold; margin-bottom: 5px;">{title}</p>'
    html += '<ul style="list-style:none; padding:0; margin:0;">'
    for threshold in thresholds:
        name = threshold[name_key] if name_key in threshold else f"Clase {threshold[class_key]}"
        color = threshold[color_key]
        html += f'''
            <li style="display:flex; align-items:center; margin-bottom:3px;">
              <span style="background:{color}; width:20px; height:15px; display:inline-block; margin-right:5px; border:1px solid black;"></span>
              <span>{name}</span>
            </li>
        '''
    html += '</ul>'
    return html

legend_html_combined_all = f'''
<div style="position: fixed;
            bottom: 50px; left: 50px; width: 280px; height: auto;
            border:2px solid grey; z-index:9999; font-size:14px;
            background-color:white; opacity:0.9; padding:10px;">
  <h4 style="margin-top:0;">Leyenda de Umbrales</h4>
  {get_threshold_legend_html('Altitud (m)', altitude_thresholds, name_key='nombre')}
  <br>
  {get_threshold_legend_html('Pendiente', slope_thresholds, name_key='rango')}
  <br>
  {get_threshold_legend_html('Precipitación', precipitation_thresholds, name_key='rango')}
  <br>
  {get_threshold_legend_html('Temperatura', temperature_thresholds, name_key='rango')}
  <br>
  {get_threshold_legend_html('Cobertura Arbórea', tree_cover_thresholds, name_key='rango')}
</div>
'''

m_thresholds.get_root().html.add_child(folium.Element(legend_html_combined_all))

display(m_thresholds)
print('\nMapa interactivo con todas las capas de umbrales y leyenda combinado completado.')

import ee
import numpy as np

# Asegurarse de que `temperature_quebrada_honda` y `roi_quebrada_honda` estén definidos
if 'temperature_quebrada_honda' not in locals() or temperature_quebrada_honda is None:
    print('Error: La imagen de temperatura (`temperature_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores que la definen.')
elif 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca `roi_quebrada_honda` no está definida. Por favor, ejecuta las celdas anteriores que la definen.')
else:
    # Calcular estadísticas de la imagen de temperatura dentro de la cuenca
    temp_stats = temperature_quebrada_honda.reduceRegion(**{
        'reducer': ee.Reducer.min().combine(ee.Reducer.max(), None, True).combine(ee.Reducer.mean(), None, True).combine(ee.Reducer.stdDev(), None, True),
        'geometry': roi_quebrada_honda,
        'scale': 30, # Usar una escala apropiada para los datos de temperatura
        'maxPixels': 1e13,
        'bestEffort': True
    }).getInfo()

    # Los nombres de las claves en temp_stats se basan en el nombre de la banda, que es 'temperature_celsius'
    min_temp = temp_stats.get('temperature_celsius_min')
    max_temp = temp_stats.get('temperature_celsius_max')
    mean_temp = temp_stats.get('temperature_celsius_mean')
    std_temp = temp_stats.get('temperature_celsius_stdDev')

    if all(v is not None for v in [min_temp, max_temp, mean_temp, std_temp]):
        print(f"Estadísticas de Temperatura en Quebrada la Honda (1 de julio de 2020):\n")
        print(f"  Mínima: {min_temp:.2f} °C")
        print(f"  Máxima: {max_temp:.2f} °C")
        print(f"  Media: {mean_temp:.2f} °C")
        print(f"  Desviación Estándar: {std_temp:.2f} °C")

        # Definir umbrales de temperatura basados en las estadísticas calculadas
        # Estos son ejemplos y pueden ajustarse. Por ejemplo, usando la media y desviación estándar.
        # Clases de temperatura:
        # Fría: < (Media - 0.5 * StdDev)
        # Templada: (Media - 0.5 * StdDev) a (Media + 0.5 * StdDev)
        # Cálida: > (Media + 0.5 * StdDev)

        temp_thresholds_calculated = [
            {'clase': 'Fría', 'rango': f'< {mean_temp - 0.5 * std_temp:.2f} °C', 'min': -np.inf, 'max': mean_temp - 0.5 * std_temp},
            {'clase': 'Templada', 'rango': f'{mean_temp - 0.5 * std_temp:.2f}-{mean_temp + 0.5 * std_temp:.2f} °C', 'min': mean_temp - 0.5 * std_temp, 'max': mean_temp + 0.5 * std_temp},
            {'clase': 'Cálida', 'rango': f'> {mean_temp + 0.5 * std_temp:.2f} °C', 'min': mean_temp + 0.5 * std_temp, 'max': np.inf}
        ]

        print('\nUmbrales de Temperatura Media calculados para Quebrada la Honda:')
        for umbral in temp_thresholds_calculated:
            print(umbral)
    else:
        print('No se pudieron calcular todas las estadísticas de temperatura. Verifique los datos o la región.')

"""### Definición de Zonas de Riesgo Integradas (Temperatura y Precipitación)

Vamos a combinar las clases de temperatura y precipitación para crear un mapa de zonas de riesgo integradas. Esto nos permitirá identificar áreas con combinaciones específicas de estos factores climáticos, lo cual es útil para la planificación y la gestión de recursos.

Utilizaremos las clases numéricas de temperatura (1=Fría, 2=Templada, 3=Cálida) y de precipitación (1=Baja, 2=Moderada, 3=Alta) para generar un nuevo raster con 9 clases combinadas. Cada clase representará una combinación única de temperatura y precipitación.
"""

import ee
import geopandas as gpd
import os
import zipfile

print('Asegurando la disponibilidad de variables clave para el cálculo de umbrales combinados...')

# 1. Re-inicializar Earth Engine
# (Esto asegura que ee.Initialize() esté activo, aunque se hace en el cuerpo de la celda de origen 3G6b85d0LCUs también, es bueno tenerlo explícito aquí)
ee.Initialize(project='studious-camp-486620-m3')
print('Earth Engine inicializado.')

# 2. Asegurar watershed_gdf y roi_quebrada_honda
if 'watershed_gdf' not in locals() or watershed_gdf is None or watershed_gdf.empty:
    print('`watershed_gdf` no encontrada o vacía. Intentando cargarla...')
    zip_file_path = '/content/watershed.zip'
    unzip_dir = '/content/watershed_extracted'
    shp_file_path = os.path.join(unzip_dir, 'watershed.shp')
    try:
        if not os.path.exists(shp_file_path): # Check if shp is already extracted
            os.makedirs(unzip_dir, exist_ok=True)
            with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:
                zip_ref.extractall(unzip_dir)
            print(f"Archivo '{zip_file_path}' descomprimido en '{unzip_dir}'.")
        watershed_gdf = gpd.read_file(shp_file_path)
        print('`watershed_gdf` cargada exitosamente.')
    except Exception as e:
        print(f'Error al cargar `watershed_gdf`: {e}')
        watershed_gdf = None

if watershed_gdf is not None and not watershed_gdf.empty:
    if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
        roi_quebrada_honda = ee.Geometry(watershed_gdf.geometry.iloc[0].__geo_interface__)
        print('`roi_quebrada_honda` creada.')
else:
    print('Error crítico: `watershed_gdf` no está disponible, no se puede definir `roi_quebrada_honda`.')
    roi_quebrada_honda = None

# 3. Asegurar watershed_area_sq_m (depende de watershed_gdf)
if 'watershed_area_sq_m' not in locals() or watershed_area_sq_m is None:
    if watershed_gdf is not None and not watershed_gdf.empty:
        watershed_gdf_projected = watershed_gdf.to_crs(epsg=3116)
        watershed_area_sq_m = watershed_gdf_projected.geometry.area.iloc[0]
        print(f'`watershed_area_sq_m` calculada: {watershed_area_sq_m:.2f} m².')
    else:
        print('Error: `watershed_gdf` no está disponible para calcular `watershed_area_sq_m`.')
        watershed_area_sq_m = None

# 4. Asegurar holdridge_gdf y ee_holdridge_zones
if 'holdridge_gdf' not in locals() or holdridge_gdf is None or holdridge_gdf.empty:
    print('`holdridge_gdf` no encontrada o vacía. Intentando cargarla...')
    zip_file_path_holdridge = '/content/Zonas_de_vida_de_Holdridge_1981_2010-shp.zip'
    unzip_dir_holdridge = '/content/holdridge_extracted'
    shp_file_holdridge = None

    try:
        # Ensure the directory exists
        os.makedirs(unzip_dir_holdridge, exist_ok=True)

        # Check if any .shp file exists in the extracted directory
        shp_files_in_dir = [f for f in os.listdir(unzip_dir_holdridge) if f.endswith('.shp')]
        if not shp_files_in_dir: # If no .shp files, then unzip
            with zipfile.ZipFile(zip_file_path_holdridge, 'r') as zip_ref:
                zip_ref.extractall(unzip_dir_holdridge)
            print(f"Archivo '{zip_file_path_holdridge}' descomprimido en '{unzip_dir_holdridge}'.")

        # Now, search for the .shp file (it might be in a subfolder or directly)
        for root, dirs, files in os.walk(unzip_dir_holdridge):
            for file in files:
                if file.endswith('.shp'):
                    shp_file_holdridge = os.path.join(root, file)
                    break
            if shp_file_holdridge:
                break

        if shp_file_holdridge: # If shp file is found (either existed or after unzipping)
            holdridge_gdf = gpd.read_file(shp_file_holdridge)
            print('`holdridge_gdf` cargada exitosamente.')
        else:
            print(f'Error: No se encontró ningún archivo .shp en el directorio {unzip_dir_holdridge} después de la descompresión.')
            holdridge_gdf = None
    except FileNotFoundError:
        print(f"Error: El archivo ZIP '{zip_file_path_holdridge}' no se encontró. Asegúrate de que el archivo esté presente en la ruta especificada.")
        holdridge_gdf = None
    except Exception as e:
        print(f'Error general al cargar `holdridge_gdf`: {e}')
        holdridge_gdf = None

if holdridge_gdf is not None and not holdridge_gdf.empty:
    if 'ee_holdridge_zones' not in locals() or ee_holdridge_zones is None:
        holdridge_gdf_wgs84 = holdridge_gdf.to_crs(epsg=4326)
        ee_holdridge_zones = ee.FeatureCollection(holdridge_gdf_wgs84.__geo_interface__['features'])
        print('`ee_holdridge_zones` creada.')
else:
    print('Error crítico: `holdridge_gdf` no está disponible, no se puede definir `ee_holdridge_zones`.')
    ee_holdridge_zones = None

# 5. Asegurar temperature_quebrada_honda
if 'temperature_quebrada_honda' not in locals() or temperature_quebrada_honda is None:
    print('`temperature_quebrada_honda` no encontrada. Intentando recrearla...')
    if roi_quebrada_honda is not None:
        try:
            era5_land_hourly = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
            start_date = '2020-07-01T00:00:00'
            end_date = '2020-07-01T23:59:59'
            temperature_collection = era5_land_hourly.filterDate(start_date, end_date)
            daily_temperature = temperature_collection.select('temperature_2m').mean()
            temperature_quebrada_honda = daily_temperature.subtract(273.15).rename('temperature_celsius').clip(roi_quebrada_honda)
            print('`temperature_quebrada_honda` recreada.')
        except Exception as e:
            print(f'Error recreando `temperature_quebrada_honda`: {e}')
            temperature_quebrada_honda = None
    else:
        print('Error: `roi_quebrada_honda` no está definida, no se puede recrear `temperature_quebrada_honda`.')
        temperature_quebrada_honda = None

print('Verificación de variables clave completada.')

import ee
import folium
import numpy as np
import matplotlib.colors as mcolors
import matplotlib.pyplot as plt

# Asegurarse de que las variables críticas estén definidas
# (reclassified_temperature_ee, reclassified_precipitation_ee, roi_quebrada_honda, watershed_gdf,
# temperature_thresholds, precipitation_thresholds deberían estar disponibles del contexto previo)

required_vars = [
    'reclassified_temperature_ee', 'reclassified_precipitation_ee',
    'roi_quebrada_honda', 'watershed_gdf',
    'temperature_thresholds', 'precipitation_thresholds'
]

for var_name in required_vars:
    if var_name not in locals() or locals()[var_name] is None:
        print(f'Error: La variable `{var_name}` no está definida o es None. Asegúrate de ejecutar las celdas previas.')
        # Para evitar que el notebook falle por completo, se podría intentar definir valores por defecto o salir.
        # Por ahora, simplemente imprimimos el error.

# 1. Combinar las imágenes de clases de temperatura y precipitación
# Las clases son 1, 2, 3 para ambos. Utilizaremos una fórmula para obtener clases únicas de 1 a 9.
# Fórmula: (temp_class - 1) * len(precipitation_thresholds) + precip_class
# Esto asume que len(precipitation_thresholds) es 3.

integrated_risk_zones_ee = (reclassified_temperature_ee.select('temperature_class').subtract(1).multiply(len(precipitation_thresholds)))
integrated_risk_zones_ee = integrated_risk_zones_ee.add(reclassified_precipitation_ee.select('precipitation_class'))
integrated_risk_zones_ee = integrated_risk_zones_ee.rename('integrated_risk_zone')

print('Imagen de Zonas de Riesgo Integradas (Temperatura y Precipitación) creada:')
print(integrated_risk_zones_ee.getInfo())

# 2. Definir una paleta de colores y etiquetas para las clases combinadas
# Habrá 9 clases (3 de temp * 3 de precip). Usaremos una paleta diversa.

combined_classes_info = []
color_palette_combined = []

# Generar una paleta de colores más amplia para 9 clases
cmap_combined = plt.colormaps.get_cmap('RdYlGn').resampled(9) # RdYlGn para riesgo (Rojo-Amarillo-Verde)

# Asignar colores y crear etiquetas descriptivas
class_counter = 0
for t_thresh in temperature_thresholds:
    for p_thresh in precipitation_thresholds:
        class_counter += 1
        # Asegurarse de que los colores sean distintivos para cada combinación
        color = mcolors.to_hex(cmap_combined(class_counter / 9.0)) # Normalizar para el cmap

        combined_classes_info.append({
            'clase_num': class_counter,
            'temp_clase_nombre': t_thresh['nombre'],
            'prec_clase_nombre': p_thresh['nombre'],
            'descripcion': f"T: {t_thresh['nombre']} (P: {p_thresh['nombre']})",
            'color': color
        })
        color_palette_combined.append(color)

integrated_risk_vis = {
    'min': 1,
    'max': 9,
    'palette': color_palette_combined
}

# 3. Crear el mapa Folium
lon_qh, lat_qh = centroid_quebrada_honda['coordinates'] # Asumiendo que centroid_quebrada_honda está definido
m_integrated_risk = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

# 4. Añadir la capa de Zonas de Riesgo Integradas
map_id_integrated_risk = integrated_risk_zones_ee.getMapId(integrated_risk_vis)
folium.TileLayer(
    tiles=map_id_integrated_risk['tile_fetcher'].url_format,
    attr='Google Earth Engine - Zonas de Riesgo Integradas',
    overlay=True,
    name='Zonas de Riesgo Integradas (Temp + Precip)'
).add_to(m_integrated_risk)

# 5. Añadir el límite de la cuenca para referencia
folium.GeoJson(
    watershed_gdf.geometry.iloc[0].__geo_interface__,
    name='Límite de Cuenca Quebrada la Honda',
    style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
).add_to(m_integrated_risk)

# 6. Añadir control de capas
m_integrated_risk.add_child(folium.LayerControl())

# 7. Crear y añadir la leyenda HTML combinada
legend_html_integrated_risk =   '''
<div style="position: fixed;
            bottom: 50px; left: 50px; width: 300px; height: auto;
            border:2px solid grey; z-index:9999; font-size:14px;
            background-color:white; opacity:0.9; padding:10px;">
  <h4 style="margin-top:0;">Zonas de Riesgo Integradas</h4>
  <ul style="list-style:none; padding:0;">
'''
for item in combined_classes_info:
    legend_html_integrated_risk += f'''
        <li style="display:flex; align-items:center; margin-bottom:5px;">
          <span style="background:{item['color']}; width:20px; height:15px; display:inline-block; margin-right:5px; border:1px solid black;"></span>
          <span>{item['descripcion']}</span>
        </li>
    '''
legend_html_integrated_risk +=  '''
  </ul>
</div>
'''
m_integrated_risk.get_root().html.add_child(folium.Element(legend_html_integrated_risk))

display(m_integrated_risk)
print('Mapa interactivo de Zonas de Riesgo Integradas (Temperatura y Precipitación) completado.')

"""Una vez que los puntos críticos estén cargados, los superpondremos en el mapa de zonas de riesgo de suelo.

### Carga de Puntos Críticos

Vamos a cargar el archivo ZIP que contiene los puntos críticos y lo convertiremos en un `GeoDataFrame` llamado `critical_points_gdf`. Esto es necesario para poder superponerlos en el mapa de zonas de riesgo.
"""

import zipfile
import os
import geopandas as gpd

# Ruta al archivo ZIP de puntos críticos (si existe, para extraerlo)
zip_file_path_critical_points = '/content/Puntos_Críticos_-46566576986356996.zip'
unzip_dir_critical_points = '/content/critical_points_extracted'

# Aseguramos que el directorio de extracción exista
os.makedirs(unzip_dir_critical_points, exist_ok=True)

# Ruta del archivo SHP esperado dentro del directorio extraído
shp_file_critical_points = os.path.join(unzip_dir_critical_points, 'Riesgos_-_Registros_de_Eventos.shp')

# Intentar descomprimir solo si el archivo ZIP existe y el SHP no existe aún
try:
    if not os.path.exists(shp_file_critical_points) and os.path.exists(zip_file_path_critical_points):
        with zipfile.ZipFile(zip_file_path_critical_points, 'r') as zip_ref:
            zip_ref.extractall(unzip_dir_critical_points)
        print(f"Archivo '{zip_file_path_critical_points}' descomprimido en '{unzip_dir_critical_points}'.")
    elif os.path.exists(shp_file_critical_points):
        print(f"El archivo SHP '{shp_file_critical_points}' ya existe, no se necesita descomprimir el ZIP.")
    else:
        print(f"Error: El archivo ZIP '{zip_file_path_critical_points}' no se encontró, y el SHP no está presente en '{unzip_dir_critical_points}'.")

    # Verificar si el archivo SHP existe después de la posible descompresión o si ya existía
    if os.path.exists(shp_file_critical_points):
        # Cargar el Shapefile en un GeoDataFrame
        try:
            critical_points_gdf = gpd.read_file(shp_file_critical_points)
            print('\nShapefile de Puntos Críticos cargado exitosamente en un GeoDataFrame:')
            display(critical_points_gdf.head())
            print(f'Sistema de Coordenadas (CRS): {critical_points_gdf.crs}')
            print(f'Número de geometrías: {len(critical_points_gdf)}')
        except Exception as e:
            print(f'Error al cargar el Shapefile de puntos críticos: {e}')
    else:
        print(f'Error: No se encontró ningún archivo .shp en el directorio {unzip_dir_critical_points}.')

except FileNotFoundError:
    print(f"Error: El archivo ZIP '{zip_file_path_critical_points}' no se encontró. Asegúrate de que el archivo esté presente en la ruta especificada.")
except Exception as e:
    print(f"Ocurrió un error inesperado al descomprimir o cargar el archivo de puntos críticos: {e}")

# Asegurarse de que `m_soil_risk_re_display` y `critical_points_gdf` estén disponibles
if 'm_soil_risk_re_display' in locals() and m_soil_risk_re_display is not None and \
   'critical_points_gdf' in locals() and critical_points_gdf is not None:

    # Convertir el GeoDataFrame de puntos críticos a WGS84 (EPSG:4326) para Folium
    critical_points_gdf_wgs84 = critical_points_gdf.to_crs(epsg=4326)

    # Añadir la capa de puntos críticos al mapa existente
    folium.GeoJson(
        critical_points_gdf_wgs84.to_json(),
        name='Puntos Críticos',
        marker=folium.Marker(icon=folium.Icon(color='purple', icon='info-sign')),
        tooltip=folium.GeoJsonTooltip(fields=list(critical_points_gdf_wgs84.columns.drop('geometry')), aliases=[col.replace('_', ' ').title() + ':' for col in critical_points_gdf_wgs84.columns.drop('geometry')], localize=True)
    ).add_to(m_soil_risk_re_display)

    # Re-añadir el control de capas para que la nueva capa sea visible
    m_soil_risk_re_display.add_child(folium.LayerControl())

    display(m_soil_risk_re_display)
    print('\nMapa interactivo de zonas de riesgo de suelo con puntos críticos completado.')
else:
    print('Error: El mapa de zonas de riesgo de suelo (`m_soil_risk_re_display`) o el GeoDataFrame de puntos críticos (`critical_points_gdf`) no están disponibles.')

import zipfile
import os
import geopandas as gpd
import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.colors as mcolors
import folium

# --- 1. Definir Umbrales (Categorías) para Zonas de Vida de Holdridge ---
# Las Zonas de Vida de Holdridge ya están categorizadas por 'ZV_Holdrid'
# y sus áreas se calcularon en `holdridge_area_summary_corrected`.
# Los umbrales son simplemente las categorías únicas de `ZV_Holdrid`.

if 'holdridge_area_summary_corrected' in locals() and holdridge_area_summary_corrected is not None:
    print('### Umbrales para Zonas de Vida de Holdridge en Quebrada la Honda ###')
    print('Estas son las categorías de Zonas de Vida presentes en la cuenca y sus rangos de temperatura/precipitación asociados (intrínsecos a la clasificación de Holdridge):')
    display(holdridge_area_summary_corrected.round(2))
    # Extraer las clases como umbrales
    holdridge_life_zone_thresholds = holdridge_area_summary_corrected['ZV_Holdrid'].tolist()
    print(f'Zonas de Vida de Holdridge identificadas como umbrales: {holdridge_life_zone_thresholds}')
else:
    print('Error: `holdridge_area_summary_corrected` no está disponible. No se pueden generar los umbrales de zonas de vida de Holdridge.')

print('\n' + '='*80 + '\n')

# --- 2. Procesar Zonificación de Degradación de Suelos por Erosión ---

zip_file_path_erosion = '/content/ZonificaciB3n_de_DegradaciB3n_de_Suelos_por_ErosiB3n.zip'
unzip_dir_erosion = '/content/soil_degradation_extracted'

# Aseguramos que el directorio de extracción exista
os.makedirs(unzip_dir_erosion, exist_ok=True)

# Descomprimir el archivo
try:
    with zipfile.ZipFile(zip_file_path_erosion, 'r') as zip_ref:
        zip_ref.extractall(unzip_dir_erosion)
    print(f"Archivo '{zip_file_path_erosion}' descomprimido en '{unzip_dir_erosion}'.")

    # Identificar el archivo .shp dentro del directorio descomprimido
    shp_file_erosion = None
    for root, dirs, files in os.walk(unzip_dir_erosion):
        for file in files:
            if file.endswith('.shp'):
                shp_file_erosion = os.path.join(root, file)
                break
        if shp_file_erosion:
            break

    if shp_file_erosion:
        # Cargar el Shapefile en un GeoDataFrame
        try:
            soil_degradation_gdf = gpd.read_file(shp_file_erosion)
            print('\nShapefile de Zonificación de Degradación de Suelos cargado exitosamente en un GeoDataFrame:')
            display(soil_degradation_gdf.head())
            print(f'Sistema de Coordenadas (CRS): {soil_degradation_gdf.crs}')
            print(f'Número de geometrías: {len(soil_degradation_gdf)}')

            # Recortar a la cuenca 'Quebrada la Honda'
            if 'watershed_gdf' in locals() and watershed_gdf is not None and not watershed_gdf.empty:
                # Asegurarse de que ambos GeoDataFrames estén en el mismo CRS para la operación de clip
                soil_degradation_gdf_reprojected = soil_degradation_gdf.to_crs(watershed_gdf.crs)
                soil_degradation_clipped_gdf = gpd.clip(soil_degradation_gdf_reprojected, watershed_gdf.geometry.iloc[0])

                if not soil_degradation_clipped_gdf.empty:
                    print('\nZonificación de Degradación de Suelos recortada a la cuenca Quebrada la Honda:')
                    display(soil_degradation_clipped_gdf.head())
                    print(f'Número de geometrías recortadas: {len(soil_degradation_clipped_gdf)}')

                    # Identificar una columna de categoría para la zonificación de degradación
                    degradation_category_column = None
                    # Columnas comunes que podrían contener la descripción de la degradación
                    potential_degradation_columns = ['DESCRIPCIO', 'CATEGORIA', 'CLASE', 'TIPO_EROSI', 'GRADO_EROC']
                    for col in potential_degradation_columns:
                        if col in soil_degradation_clipped_gdf.columns and not soil_degradation_clipped_gdf[col].isnull().all():
                            degradation_category_column = col
                            break

                    if degradation_category_column:
                        # Calcular el área de cada categoría de degradación
                        soil_degradation_clipped_gdf['area_sq_m'] = soil_degradation_clipped_gdf.geometry.area
                        soil_degradation_clipped_gdf['area_ha'] = soil_degradation_clipped_gdf['area_sq_m'] / 10000

                        soil_degradation_summary_df = soil_degradation_clipped_gdf.groupby(degradation_category_column)['area_ha'].sum().reset_index()

                        # Calculate the total area of *degraded* land within the watershed
                        total_degraded_area_ha_within_watershed = soil_degradation_summary_df['area_ha'].sum()

                        # Calculate percentage relative to the *total degraded area found within the watershed*
                        if total_degraded_area_ha_within_watershed > 0:
                            soil_degradation_summary_df['percentage'] = (soil_degradation_summary_df['area_ha'] / total_degraded_area_ha_within_watershed * 100).round(2)
                        else:
                            soil_degradation_summary_df['percentage'] = 0.0 # No degraded area found

                        print('\n### Umbrales para Zonificación de Degradación de Suelos por Erosión en Quebrada la Honda ###')
                        print('Estas son las categorías de degradación de suelos presentes en la cuenca y su área/porcentaje:')
                        display(soil_degradation_summary_df.round(2))
                        # Extraer las clases como umbrales
                        soil_degradation_thresholds = soil_degradation_summary_df[degradation_category_column].tolist()
                        print(f'Clases de Degradación de Suelos identificadas como umbrales: {soil_degradation_thresholds}')

                        # --- 3. Visualizar Zonificación de Degradación de Suelos --- (Opcional, pero útil)
                        if 'centroid_quebrada_honda' in locals() and centroid_quebrada_honda is not None:
                            lon_qh, lat_qh = centroid_quebrada_honda['coordinates']
                            m_soil_degradation = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

                            unique_degradation_categories = soil_degradation_summary_df[degradation_category_column].unique()
                            cmap_degradation = plt.colormaps.get_cmap('YlOrRd').resampled(len(unique_degradation_categories)) # Yellow-Orange-Red para degradación
                            colors_map_degradation = {cat: mcolors.to_hex(cmap_degradation(i)) for i, cat in enumerate(unique_degradation_categories)}

                            folium.GeoJson(
                                soil_degradation_clipped_gdf.to_crs(epsg=4326).to_json(),
                                name=f'Zonificación de Degradación de Suelos ({degradation_category_column})',
                                style_function=lambda x: {
                                    'fillColor': colors_map_degradation.get(x['properties'].get(degradation_category_column), '#808080'), # Gris por defecto
                                    'color': 'black',
                                    'weight': 1,
                                    'fillOpacity': 0.7
                                },
                                tooltip=folium.GeoJsonTooltip(fields=[degradation_category_column, 'area_ha', 'percentage'], aliases=[f'{degradation_category_column}:', 'Área (ha):', 'Porcentaje (%):'], localize=True)
                            ).add_to(m_soil_degradation)

                            folium.GeoJson(
                                watershed_gdf.geometry.iloc[0].__geo_interface__,
                                name='Límite de Cuenca Quebrada la Honda',
                                style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2, 'dashArray': '5, 5'}
                            ).add_to(m_soil_degradation)

                            m_soil_degradation.add_child(folium.LayerControl())

                            # Leyenda dinámica
                            legend_html_degradation =   '''
                                                    <div style="position: fixed;
                                                                bottom: 50px; left: 50px; width: 250px; height: auto;
                                                                border:2px solid grey; z-index:9999; font-size:14px;
                                                                background-color:white; opacity:0.9; padding:10px;">
                                                      <h4 style="margin-top:0;">Zonificación Degradación Suelos</h4>
                                                      <ul style="list-style:none; padding:0;">
                                                    '''
                            for zone, color in colors_map_degradation.items():
                                legend_html_degradation += f'''
                                                        <li style="display:flex; align-items:center; margin-bottom:5px;">
                                                          <span style="background:{color}; width:20px; height:15px; display:inline-block; margin-right:5px; border:1px solid black;"></span>
                                                          <span>{zone}</span>
                                                        </li>
                                                    '''
                            legend_html_degradation +=  '''
                                                      </ul>
                                                    </div>
                                                    '''
                            m_soil_degradation.get_root().html.add_child(folium.Element(legend_html_degradation))

                            display(m_soil_degradation)
                            print('\nMapa interactivo de Zonificación de Degradación de Suelos completado.')
                        else:
                            print('Error: `centroid_quebrada_honda` no está definida para centrar el mapa.')

                    else:
                        print('Advertencia: No se encontró una columna adecuada para categorizar la zonificación de degradación de suelos. No se pueden generar umbrales detallados ni visualización coloreada.')
                else:
                    print('No se encontró ninguna geometría de zonificación de degradación de suelos dentro de la cuenca.')
            else:
                print('Error: `watershed_gdf` no está disponible o está vacío para recortar la zonificación de degradación de suelos.')

        except Exception as e:
            print(f'Error al cargar el Shapefile de zonificación de degradación de suelos: {e}')
    else:
        print(f'Error: No se encontró ningún archivo .shp en el directorio {unzip_dir_erosion}.')

except FileNotFoundError:
    print(f"Error: El archivo ZIP '{zip_file_path_erosion}' no se encontró. Asegúrate de que el archivo esté presente en la ruta especificada.")
except Exception as e:
    print(f"Ocurrió un error inesperado al descomprimir o cargar el archivo de zonificación de degradación de suelos: {e}")

import pandas as pd
import numpy as np

# --- Asegurar que `holdridge_area_summary_corrected` esté disponible ---
# Si el kernel se ha reiniciado o las celdas previas no se ejecutaron, necesitamos recrear esta variable.
# Se asume que `ee_holdridge_zones`, `roi_quebrada_honda` y `watershed_area_sq_m` están disponibles.
# Recálculo para robustez si es necesario

if 'holdridge_area_summary_corrected' not in locals() or holdridge_area_summary_corrected is None:
    print('Recalculando `holdridge_area_summary_corrected`...')
    if 'ee_holdridge_zones' not in locals() or ee_holdridge_zones is None:
        print('Error: `ee_holdridge_zones` no está definida. Necesita ser creada en una celda previa.')
        # Intentar recrear ee_holdridge_zones si holdridge_gdf está disponible
        if 'holdridge_gdf' in locals() and holdridge_gdf is not None:
            holdridge_gdf_wgs84 = holdridge_gdf.to_crs(epsg=4326)
            ee_holdridge_zones = ee.FeatureCollection(holdridge_gdf_wgs84.__geo_interface__['features'])
            print('`ee_holdridge_zones` recreada.')
        else:
            print('Error: `holdridge_gdf` tampoco está definida. No se puede recrear `ee_holdridge_zones`.')
            ee_holdridge_zones = None

    if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
        print('Error: `roi_quebrada_honda` no está definida. Necesita ser creada en una celda previa.')

    if 'watershed_area_sq_m' not in locals() or watershed_area_sq_m is None:
        print('Error: `watershed_area_sq_m` no está definida. Necesita ser creada en una celda previa.')

    if all(v is not None for v in [ee_holdridge_zones, roi_quebrada_honda, watershed_area_sq_m]):
        def clip_and_calculate_area(feature):
            clipped_feature = feature.intersection(roi_quebrada_honda, ee.ErrorMargin(1))
            return clipped_feature.set({'area_sq_m': clipped_feature.area()})

        holdridge_zones_quebrada_honda_clipped = ee_holdridge_zones.filterBounds(roi_quebrada_honda).map(clip_and_calculate_area)
        holdridge_list_clipped = holdridge_zones_quebrada_honda_clipped.getInfo()['features']

        data_clipped = []
        for f in holdridge_list_clipped:
            properties = f['properties']
            if 'ZV_Holdrid' in properties and 'area_sq_m' in properties and properties['area_sq_m'] > 0:
                data_clipped.append({
                    'ZV_Holdrid': properties['ZV_Holdrid'],
                    'area_sq_m': properties['area_sq_m']
                })

        holdridge_area_df_corrected = pd.DataFrame(data_clipped)
        if not holdridge_area_df_corrected.empty:
            holdridge_area_summary_corrected = holdridge_area_df_corrected.groupby('ZV_Holdrid')['area_sq_m'].sum().reset_index()
            holdridge_area_summary_corrected['area_ha'] = holdridge_area_summary_corrected['area_sq_m'] / 10000
            watershed_total_area_ha = watershed_area_sq_m / 10000
            holdridge_area_summary_corrected['percentage'] = (holdridge_area_summary_corrected['area_ha'] / watershed_total_area_ha * 100).round(2)
            total_percentage = holdridge_area_summary_corrected['percentage'].sum()
            if total_percentage != 100.0:
                holdridge_area_summary_corrected['percentage'] = (holdridge_area_summary_corrected['percentage'] / total_percentage * 100).round(2)
            print('`holdridge_area_summary_corrected` recalculada y normalizada.')
        else:
            print('No se encontraron zonas de vida válidas para recrear `holdridge_area_summary_corrected`.')
            holdridge_area_summary_corrected = None
    else:
        print('No se pudo recrear `holdridge_area_summary_corrected` debido a variables faltantes.')

# --- Asegurar que `temp_thresholds_calculated` esté disponible ---
# Si el kernel se ha reiniciado o las celdas previas no se ejecutaron, necesitamos recrear esta variable.
# Se asume que `temperature_quebrada_honda` y `roi_quebrada_honda` están disponibles.
if 'temp_thresholds_calculated' not in locals() or temp_thresholds_calculated is None:
    print('Recalculando `temp_thresholds_calculated`...')
    if 'temperature_quebrada_honda' not in locals() or temperature_quebrada_honda is None:
        print('Error: `temperature_quebrada_honda` no está definida. Necesita ser creada en una celda previa.')
        # Intentar recrear temperature_quebrada_honda
        if 'roi_quebrada_honda' in locals() and roi_quebrada_honda is not None:
            try:
                era5_land_hourly = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
                start_date = '2020-07-01T00:00:00'
                end_date = '2020-07-01T23:59:59'
                temperature_collection = era5_land_hourly.filterDate(start_date, end_date)
                daily_temperature = temperature_collection.select('temperature_2m').mean()
                temperature_quebrada_honda = daily_temperature.subtract(273.15).rename('temperature_celsius').clip(roi_quebrada_honda)
                print('`temperature_quebrada_honda` recreada.')
            except Exception as e:
                print(f'Error recreando `temperature_quebrada_honda`: {e}')
                temperature_quebrada_honda = None
        else:
            print('Error: `roi_quebrada_honda` no está definida para recrear `temperature_quebrada_honda`.')
            temperature_quebrada_honda = None

    if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
        print('Error: `roi_quebrada_honda` no está definida. Necesita ser creada en una celda previa.')

    if all(v is not None for v in [temperature_quebrada_honda, roi_quebrada_honda]):
        try:
            temp_stats = temperature_quebrada_honda.reduceRegion(**{
                'reducer': ee.Reducer.min().combine(ee.Reducer.max(), None, True).combine(ee.Reducer.mean(), None, True).combine(ee.Reducer.stdDev(), None, True),
                'geometry': roi_quebrada_honda,
                'scale': 30,
                'maxPixels': 1e13,
                'bestEffort': True
            }).getInfo()

            min_temp = temp_stats.get('temperature_celsius_min')
            max_temp = temp_stats.get('temperature_celsius_max')
            mean_temp = temp_stats.get('temperature_celsius_mean')
            std_temp = temp_stats.get('temperature_celsius_stdDev')

            if all(v is not None for v in [min_temp, max_temp, mean_temp, std_temp]):
                temp_thresholds_calculated = [
                    {'clase': 'Fría', 'rango': f'< {mean_temp - 0.5 * std_temp:.2f} °C', 'min': -np.inf, 'max': mean_temp - 0.5 * std_temp},
                    {'clase': 'Templada', 'rango': f'{mean_temp - 0.5 * std_temp:.2f}-{mean_temp + 0.5 * std_temp:.2f} °C', 'min': mean_temp - 0.5 * std_temp, 'max': mean_temp + 0.5 * std_temp},
                    {'clase': 'Cálida', 'rango': f'> {mean_temp + 0.5 * std_temp:.2f} °C', 'min': mean_temp + 0.5 * std_temp, 'max': np.inf}
                ]
                print('`temp_thresholds_calculated` recalculados.')
            else:
                print('No se pudieron calcular todas las estadísticas de temperatura para `temp_thresholds_calculated`.')
                temp_thresholds_calculated = []
        except Exception as e:
            print(f'Error al calcular `temp_thresholds_calculated`: {e}')
            temp_thresholds_calculated = []
    else:
        print('No se pudo recrear `temp_thresholds_calculated` debido a variables faltantes.')
        temp_thresholds_calculated = []


# --- Generar los umbrales combinados ---
combined_life_zone_temp_thresholds = []

if 'holdridge_area_summary_corrected' in locals() and holdridge_area_summary_corrected is not None and \
   'temp_thresholds_calculated' in locals() and temp_thresholds_calculated:

    print('\n### Umbrales Combinados de Zonas de Vida de Holdridge y Temperatura ###')
    threshold_id = 1
    for holdridge_zone in holdridge_area_summary_corrected['ZV_Holdrid'].unique():
        for temp_thresh in temp_thresholds_calculated:
            combined_thresholds_entry = {
                'id': threshold_id,
                'Zona_Holdridge': holdridge_zone,
                'Clase_Temperatura': temp_thresh['clase'],
                'Rango_Temperatura': temp_thresh['rango'],
                'Descripcion_Combinada': f"Zona: {holdridge_zone} | Temp: {temp_thresh['clase']} ({temp_thresh['rango']})"
            }
            combined_life_zone_temp_thresholds.append(combined_thresholds_entry)
            threshold_id += 1

    combined_thresholds_df = pd.DataFrame(combined_life_zone_temp_thresholds)
    display(combined_thresholds_df)

    print('\nUmbrales combinados generados exitosamente.')

else:
    print('Error: `holdridge_area_summary_corrected` o `temp_thresholds_calculated` no están disponibles.')

"""### Carga y Visualización de Datos de Temperatura NOAA CFSV2 para la Cuenca 'Quebrada la Honda'

Vamos a cargar el conjunto de datos de pronóstico del Sistema de Pronóstico del Clima (CFSV2) de la NOAA, que proporciona datos de temperatura por encima del suelo. Luego, lo filtraremos a tu cuenca de interés, convertiremos la temperatura a grados Celsius y la visualizaremos en un mapa interactivo.
"""

import ee
import folium

# Asegurarse de que `roi_quebrada_honda` esté definido
if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca (`roi_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores que la definen.')
elif 'watershed_gdf' not in locals() or watershed_gdf is None:
    print('Error: El GeoDataFrame de la cuenca (`watershed_gdf`) no está disponible. Por favor, ejecuta las celdas anteriores.')
else:
    # 1. Cargar la colección de imágenes ERA5-Land Hourly (alternativa a NOAA CFSV2 debido a error de carga)
    # Este dataset contiene temperaturas a 2m sobre el suelo.
    # Usaremos ERA5-Land que ha funcionado en el cuaderno, ya que NOAA/CFSV2/DAILY_FORCS generó un error de asset not found.
    temperature_dataset = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')

    # 2. Filtrar por fecha: Usaremos una fecha reciente para la demostración.
    # Por ejemplo, el 1 de enero de 2024. Puedes ajustar estas fechas.
    start_date_cfs = '2024-01-01T00:00:00'
    end_date_cfs = '2024-01-01T23:59:59'
    temperature_collection_cfs = temperature_dataset.filterDate(start_date_cfs, end_date_cfs)

    # 3. Seleccionar la banda 'temperature_2m' y tomar la imagen promedio o la primera.
    # Tomaremos la media diaria para esta fecha.
    daily_temperature_cfs = temperature_collection_cfs.select('temperature_2m').mean()

    # 4. Convertir de Kelvin a Celsius (T(°C) = T(K) - 273.15)
    daily_temperature_celsius_cfs = daily_temperature_cfs.subtract(273.15).rename('temperature_celsius_cfs')

    # 5. Recortar la imagen de temperatura a la región de interés de Quebrada la Honda
    temperature_quebrada_honda_cfs = daily_temperature_celsius_cfs.clip(roi_quebrada_honda)

    print('Imagen de temperatura ERA5-Land para Quebrada la Honda (en Celsius):')
    print(temperature_quebrada_honda_cfs.getInfo())

    # 6. Visualizar la imagen de temperatura recortada
    # Definir parámetros de visualización para la temperatura en Celsius
    # Ajusta min/max según los valores esperados en tu región para ERA5-Land
    temperature_cfs_vis = {
      'min': 0,  # Valor mínimo de temperatura esperado
      'max': 30, # Valor máximo de temperatura esperado
      'palette': ['blue', 'purple', 'cyan', 'green', 'yellow', 'red'] # Escala de color de frío a cálido
    }

    # Obtener el MapId y el token de la imagen de temperatura
    map_id_temp_cfs_qh = ee.Image(temperature_quebrada_honda_cfs).getMapId(temperature_cfs_vis)

    # Obtener el centroide de la cuenca para centrar el mapa (reutilizamos centroid_quebrada_honda)
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    m_temperature_cfs = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    folium.TileLayer(
        tiles=map_id_temp_cfs_qh['tile_fetcher'].url_format,
        attr='Google Earth Engine - ERA5-Land Temperatura',
        overlay=True,
        name=f'ERA5-Land Temp ({start_date_cfs[:10]})'
    ).add_to(m_temperature_cfs)

    # Añadir la geometría de la cuenca como un contorno para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2}
    ).add_to(m_temperature_cfs)

    m_temperature_cfs.add_child(folium.LayerControl())

    display(m_temperature_cfs)

    print(f'\nVisualización de la temperatura media diaria (ERA5-Land, {start_date_cfs[:10]}) en Quebrada la Honda completada.')

"""### Cálculo y Visualización de la Temperatura Media Histórica (2010-2019) de ERA5-Land

Vamos a calcular la temperatura media histórica para la cuenca 'Quebrada la Honda' utilizando el conjunto de datos ERA5-Land. Este análisis nos permitirá entender el patrón de temperatura a largo plazo en la región, lo cual es fundamental para el análisis climático e hidrológico.
"""

import ee
import folium

# Asegurarse de que `roi_quebrada_honda` esté definido
# (se asume que se ha ejecutado la celda `4d19799f` para definirla de forma robusta)
if 'roi_quebrada_honda' not in locals() or roi_quebrada_honda is None:
    print('Error: La geometría de la cuenca (`roi_quebrada_honda`) no está definida. Por favor, ejecuta las celdas anteriores.')
elif 'watershed_gdf' not in locals() or watershed_gdf is None:
    print('Error: El GeoDataFrame de la cuenca (`watershed_gdf`) no está disponible. Por favor, ejecuta las celdas anteriores.')
else:
    # 1. Cargar la colección de imágenes ERA5-Land Hourly
    era5_land_hourly = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')

    # 2. Definir el período histórico para el cálculo de la temperatura media (ej. 2010-2019)
    historical_start_date = '2010-01-01'
    historical_end_date = '2019-12-31'

    # 3. Filtrar por fecha y seleccionar la banda 'temperature_2m'
    historical_temperature_collection = era5_land_hourly.filterDate(historical_start_date, historical_end_date)
    historical_temperature_band = historical_temperature_collection.select('temperature_2m')

    # 4. Calcular la temperatura media para todo el período histórico
    mean_historical_temperature_kelvin = historical_temperature_band.mean()

    # 5. Convertir de Kelvin a Celsius (T(°C) = T(K) - 273.15)
    mean_historical_temperature_celsius = mean_historical_temperature_kelvin.subtract(273.15).rename('mean_historical_temperature_celsius')

    # 6. Recortar la imagen de temperatura media a la región de interés de Quebrada la Honda
    historical_temperature_quebrada_honda = mean_historical_temperature_celsius.clip(roi_quebrada_honda)

    print(f'Imagen de temperatura media histórica para Quebrada la Honda ({historical_start_date} a {historical_end_date}):')
    print(historical_temperature_quebrada_honda.getInfo())

    # 7. Calcular y mostrar estadísticas descriptivas
    historical_temp_stats = historical_temperature_quebrada_honda.reduceRegion(**{
        'reducer': ee.Reducer.min().combine(ee.Reducer.max(), None, True).combine(ee.Reducer.mean(), None, True).combine(ee.Reducer.stdDev(), None, True),
        'geometry': roi_quebrada_honda,
        'scale': 1000, # Usar una escala adecuada para los datos de ERA5-Land (aproximadamente 10km, pero puede ser más fina para la cuenca)
        'maxPixels': 1e13,
        'bestEffort': True
    }).getInfo()

    min_temp_hist = historical_temp_stats.get('mean_historical_temperature_celsius_min')
    max_temp_hist = historical_temp_stats.get('mean_historical_temperature_celsius_max')
    mean_temp_hist = historical_temp_stats.get('mean_historical_temperature_celsius_mean')
    std_temp_hist = historical_temp_stats.get('mean_historical_temperature_celsius_stdDev')

    print(f'\nEstadísticas de Temperatura Media Histórica en Quebrada la Honda ({historical_start_date} a {historical_end_date}):')
    print(f'  Mínima: {min_temp_hist:.2f} °C')
    print(f'  Máxima: {max_temp_hist:.2f} °C')
    print(f'  Media: {mean_temp_hist:.2f} °C')
    print(f'  Desviación Estándar: {std_temp_hist:.2f} °C')

    # 8. Visualizar la imagen de temperatura recortada
    temperature_hist_vis = {
      'min': 10,  # Valor mínimo de temperatura esperado
      'max': 25, # Valor máximo de temperatura esperado
      'palette': ['blue', 'purple', 'cyan', 'green', 'yellow', 'red'] # Escala de color de frío a cálido
    }

    map_id_temp_hist_qh = ee.Image(historical_temperature_quebrada_honda).getMapId(temperature_hist_vis)

    # Obtener el centroide de la cuenca para centrar el mapa (asumimos que centroid_quebrada_honda está definido)
    if 'centroid_quebrada_honda' not in locals() or centroid_quebrada_honda is None:
        centroid_quebrada_honda = roi_quebrada_honda.centroid().getInfo()
    lon_qh, lat_qh = centroid_quebrada_honda['coordinates']

    m_historical_temperature = folium.Map(location=[lat_qh, lon_qh], zoom_start=12)

    folium.TileLayer(
        tiles=map_id_temp_hist_qh['tile_fetcher'].url_format,
        attr='Google Earth Engine - ERA5-Land Temperatura Histórica',
        overlay=True,
        name=f'ERA5-Land Temp Histórica ({historical_start_date}-{historical_end_date})'
    ).add_to(m_historical_temperature)

    # Añadir la geometría de la cuenca como un contorno para referencia
    folium.GeoJson(
        watershed_gdf.geometry.iloc[0].__geo_interface__,
        name='Límite de Cuenca Quebrada la Honda',
        style_function=lambda x: {'fillColor': '#00000000', 'color': 'black', 'weight': 2}
    ).add_to(m_historical_temperature)

    m_historical_temperature.add_child(folium.LayerControl())

    display(m_historical_temperature)

    print(f'\nVisualización de la temperatura media histórica ({historical_start_date}-{historical_end_date}) en Quebrada la Honda completada.')

"""### Mapa Comparativo de Temperaturas: Histórica (2010-2019) vs. Reciente (2024)

Este mapa interactivo te permite comparar la distribución espacial de la temperatura media histórica de la cuenca 'Quebrada la Honda' con la temperatura media del 1 de enero de 2024. Esto es útil para observar tendencias y anomalías en la temperatura a lo largo del tiempo.

**Instrucciones:**
*   Usa el icono de capas (generalmente en la esquina superior derecha del mapa) para activar/desactivar las capas de temperatura.
*   La capa 'Límite de Cuenca' siempre estará visible para referencia.
"""

import ee
import folium

# Asegurarse de que `historical_temperature_quebrada_honda` y `temperature_quebrada_honda_cfs` estén definidos
