import seaborn as sns

if 'pivot_table_percentage' in locals() and pivot_table_percentage is not None:
    plt.figure(figsize=(12, 8))
    sns.heatmap(pivot_table_percentage, annot=True, cmap='YlGnBu', fmt=".1f", linewidths=.5)
    plt.title('Distribución Porcentual de Clases de Precipitación por Clase de Pendiente')
    plt.xlabel('Clase de Precipitación')
    plt.ylabel('Clase de Pendiente')
    plt.tight_layout()
    plt.show()
else:
    print('Error: La variable `pivot_table_percentage` no está disponible. Asegúrate de que las celdas previas se hayan ejecutado correctamente.')